"use client";

import React, { useState } from 'react';
import { ShieldAlert, DatabaseBackup, ActivitySquare, Loader2, RotateCcw } from 'lucide-react';
import { useFleet } from '@/shared/contexts/FleetContext';
import { useAuth } from '@/shared/providers/NexusCoreProvider';
import { toast } from 'sonner';
import { authedFetch } from '@/lib/client/authedFetch';

export function DisasterRecoveryPanel() {
  const { instances } = useFleet();
  const { currentUser } = useAuth();
  const [loadingAction, setLoadingAction] = useState<string | null>(null);

  const toggleShadowMode = async (tenantId: string) => {
    setLoadingAction(`shadow-${tenantId}`);
    try {
      // Pour la démo, on bascule en 'local_survival' (Offline Cloud)
      const res = await authedFetch('/api/admin/fleet/shadow-mode', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tenantId, mode: 'local_survival' })
      });
      if (!res.ok) throw new Error('Shadow mode error');
      toast.success(`Shadow Mode activé pour ${tenantId} (Local Survival)`);
    } catch (e) {
      toast.error('Erreur lors de la bascule en Shadow Mode');
    } finally {
      setLoadingAction(null);
    }
  };

  const triggerGlobalBackup = async () => {
    setLoadingAction('backup');
    try {
      const res = await authedFetch('/api/admin/fleet/backup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({})
      });
      if (!res.ok) throw new Error('Backup error');
      const data = await res.json();
      toast.success(`Sauvegarde globale déclenchée (${data.succeeded} succès)`);
    } catch (e) {
      toast.error('Erreur lors du déclenchement de la sauvegarde');
    } finally {
      setLoadingAction(null);
    }
  };

  const triggerRestore = async (tenantId: string) => {
    // Dans la vraie vie on demanderait l'heure cible et la raison. Pour la démo :
    const targetTimestamp = new Date(Date.now() - 3600 * 1000).toISOString(); // 1h PITR window
    const reason = 'PRA Automatique (1-Click Restore)';
    const operatorId = currentUser?.id ?? currentUser?.email ?? 'mcc_unknown';

    if (!confirm(`Restauration PITR pour ${tenantId} ? (Attention, annule les écritures depuis 1h)`)) {
      return;
    }

    setLoadingAction(`restore-${tenantId}`);
    try {
      const res = await authedFetch('/api/admin/fleet/restore', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tenantId, targetTimestamp, reason, operatorId })
      });
      if (!res.ok) throw new Error('Restore error');
      toast.success(`Restauration initiée pour ${tenantId}`);
    } catch (e) {
      toast.error('Erreur lors de la restauration');
    } finally {
      setLoadingAction(null);
    }
  };

  return (
    <div className="p-6 bg-surface-card backdrop-blur-md border border-rose-500/30 rounded-2xl relative overflow-hidden">
      <div className="absolute top-0 right-0 p-8 opacity-5">
        <ShieldAlert className="w-48 h-48 text-rose-500" />
      </div>

      <div className="flex items-center justify-between mb-6 relative z-10">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-rose-500/10 rounded-xl border border-rose-500/20 text-rose-500">
            <ShieldAlert className="w-5 h-5" />
          </div>
          <div>
            <h3 className="text-sm font-bold uppercase tracking-widest text-text-primary">Plan de Reprise d'Activité (PRA)</h3>
            <p className="text-xs text-secondary">Restauration Firestore PITR & Sauvegarde Globale</p>
          </div>
        </div>

        <button 
          onClick={triggerGlobalBackup}
          disabled={loadingAction === 'backup'}
          className="flex items-center gap-2 px-4 py-2 bg-indigo-500 hover:bg-indigo-600 text-white text-xs font-bold uppercase tracking-wider rounded-xl transition-colors disabled:opacity-50"
        >
          {loadingAction === 'backup' ? <Loader2 className="w-4 h-4 animate-spin" /> : <DatabaseBackup className="w-4 h-4" />}
          Sauvegarde Globale
        </button>
      </div>

      <div className="space-y-3 relative z-10">
        {instances.map(inst => (
          <div key={inst.id} className="flex items-center justify-between p-4 bg-surface-card border border-border-subtle rounded-xl">
            <div className="flex items-center gap-3">
              <ActivitySquare className="w-5 h-5 text-secondary" />
              <div>
                <div className="text-sm font-bold">{inst.name || inst.id}</div>
                <div className="text-[10px] text-secondary font-mono">ID: {inst.id}</div>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <button
                onClick={() => toggleShadowMode(inst.id)}
                disabled={loadingAction === `shadow-${inst.id}`}
                className="px-3 py-1.5 flex items-center gap-2 bg-amber-500/10 hover:bg-amber-500/20 text-amber-500 text-[10px] font-black uppercase tracking-widest rounded-lg border border-amber-500/20 transition-colors disabled:opacity-50"
              >
                {loadingAction === `shadow-${inst.id}` ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <ShieldAlert className="w-3.5 h-3.5" />}
                Mode Survie
              </button>
              <button
                onClick={() => triggerRestore(inst.id)}
                disabled={loadingAction === `restore-${inst.id}`}
                className="px-3 py-1.5 flex items-center gap-2 bg-rose-500/10 hover:bg-rose-500/20 text-rose-500 text-[10px] font-black uppercase tracking-widest rounded-lg border border-rose-500/20 transition-colors disabled:opacity-50"
              >
                {loadingAction === `restore-${inst.id}` ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <RotateCcw className="w-3.5 h-3.5" />}
                Restauration 1-Clic
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

'use client';

/**
 * MFAGate — mcc-core-3
 *
 * Enforces TOTP 2FA enrollment for fleet_admin accounts.
 * Wraps MCC pages with an enrollment modal when the Firebase user has no MFA factor.
 *
 * Flow:
 *  1. On mount: check multiFactor(user).enrolledFactors
 *  2. If none → show enrollment modal (blocks the page)
 *  3. User opens Google Authenticator, enters manual key (or scans otpauth:// URI)
 *  4. User enters 6-digit OTP → completeTOTPEnrollment
 *  5. On success → gate dissolves, children render
 */

import React, { useCallback, useEffect, useState } from 'react';
import { useAuth } from '@/shared/hooks';
import { MCC_DEV_MODE_CLIENT } from '@/lib/mcc/devMode';
import { ShieldAlert, ShieldCheck, Copy, Check, Loader2, AlertCircle } from 'lucide-react';
import {
    isMFAEnrolled,
    startTOTPEnrollment,
    completeTOTPEnrollment,
    type MFAEnrollmentSession,
} from '@/lib/auth/mfa';

type GateStatus = 'checking' | 'enrolled' | 'needs_enrollment' | 'enrolling' | 'verifying' | 'error';

interface MFAGateProps {
    /** Role required to trigger the MFA check — defaults to fleet_admin */
    role?: string;
    children: React.ReactNode;
}

/** Point d'entrée public — délègue à l'implémentation complète ou au bypass dev */
export function MFAGate({ role = 'fleet_admin', children }: MFAGateProps) {
    if (MCC_DEV_MODE_CLIENT) {
        return <>{children}</>;
    }
    return <MFAGateImpl role={role}>{children}</MFAGateImpl>;
}

function MFAGateImpl({ role = 'fleet_admin', children }: MFAGateProps) {
    const [status, setStatus] = useState<GateStatus>('checking');
    const [session, setSession] = useState<MFAEnrollmentSession | null>(null);
    const [otp, setOtp] = useState('');
    const [error, setError] = useState<string | null>(null);
    const [copied, setCopied] = useState<'url' | 'key' | null>(null);

    // Determine the current user's role from the DB-Agnostic Nexus Auth
    const { currentUser } = useAuth();
    const [userRole, setUserRole] = useState<string | null>(null);

    useEffect(() => {
        if (!currentUser) {
            setStatus('enrolled'); // Auth guard upstream will block non-authed users
            return;
        }
        setUserRole(currentUser.role || null);
    }, [currentUser]);

    useEffect(() => {
        if (userRole === null) return;
        // Only gate fleet_admin (or the specified role)
        if (userRole !== role && role === 'fleet_admin' && userRole !== 'SUPER_ADMIN') {
            setStatus('enrolled');
            return;
        }
        setStatus(isMFAEnrolled() ? 'enrolled' : 'needs_enrollment');
    }, [userRole, role]);

    const handleStartEnrollment = useCallback(async () => {
        setStatus('enrolling');
        setError(null);
        try {
            const accountName = currentUser?.email || currentUser?.name || currentUser?.id || 'Admin';
            const sess = await startTOTPEnrollment(accountName);
            setSession(sess);
        } catch (err) {
            setError(err instanceof Error ? err.message : 'Erreur lors de la génération du secret TOTP');
            setStatus('needs_enrollment');
        }
    }, []);

    const handleVerifyOTP = useCallback(async () => {
        if (!session || otp.length !== 6) return;
        setStatus('verifying');
        setError(null);
        try {
            await completeTOTPEnrollment(session.secret, otp);
            setStatus('enrolled');
        } catch (err) {
            setError("Code incorrect ou expiré. Vérifiez l'heure système et réessayez.");
            setStatus('enrolling');
        }
    }, [session, otp]);

    const copy = useCallback(async (text: string, field: 'url' | 'key') => {
        await navigator.clipboard.writeText(text);
        setCopied(field);
        setTimeout(() => setCopied(null), 2000);
    }, []);

    if (status === 'checking') {
        return (
            <div className="flex items-center justify-center min-h-screen bg-black">
                <Loader2 className="animate-spin text-orange-500" size={32} />
            </div>
        );
    }

    if (status === 'enrolled') {
        return <>{children}</>;
    }

    // -- Enrollment gate --
    return (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/95 backdrop-blur-sm">
            <div className="w-full max-w-lg mx-4 bg-surface-bg border border-orange-500/40 rounded-2xl shadow-2xl shadow-orange-900/20 p-8">

                {/* Header */}
                <div className="flex items-center gap-3 mb-6">
                    <div className="p-2 bg-orange-500/10 rounded-lg">
                        <ShieldAlert className="text-orange-400" size={24} />
                    </div>
                    <div>
                        <h2 className="text-text-primary font-semibold text-lg">Authentification 2 facteurs requise</h2>
                        <p className="text-text-secondary text-sm">Accès MCC — fleet_admin</p>
                    </div>
                </div>

                <p className="text-text-secondary text-sm mb-6 leading-relaxed">
                    Un compte admin compromis donne accès à <strong className="text-orange-400">tous les restaurants</strong> de la flotte.
                    Vous devez activer le TOTP (Google Authenticator, Authy, 1Password) pour continuer.
                </p>

                {status === 'needs_enrollment' && (
                    <div className="space-y-4">
                        <button
                            onClick={handleStartEnrollment}
                            className="w-full py-3 px-4 bg-orange-500 hover:bg-orange-600 text-text-primary font-medium rounded-xl transition-colors"
                        >
                            Configurer l&apos;authentificateur
                        </button>
                        {error && (
                            <div className="flex items-center gap-2 text-status-danger text-sm bg-status-danger/10 p-3 rounded-lg border border-status-danger/20">
                                <AlertCircle size={14} />
                                <span>{error}</span>
                            </div>
                        )}
                    </div>
                )}

                {status === 'enrolling' && session && (
                    <div className="space-y-5">
                        <div className="bg-surface-card rounded-xl p-4 space-y-4">
                            <p className="text-text-secondary text-sm font-medium">
                                1 — Ouvrez votre application (Google Authenticator · Authy · 1Password)
                            </p>
                            <p className="text-text-secondary text-sm font-medium">
                                2 — Ajoutez un compte manuellement et copiez cette clé secrète :
                            </p>

                            {/* Manual key */}
                            <div className="flex items-center gap-2">
                                <code className="flex-1 bg-surface-bg text-orange-300 text-xs font-mono px-3 py-2 rounded-lg break-all select-all">
                                    {session.manualKey}
                                </code>
                                <button
                                    onClick={() => copy(session.manualKey, 'key')}
                                    className="shrink-0 p-2 bg-surface-elevated hover:bg-zinc-600 rounded-lg transition-colors"
                                    title="Copier la clé"
                                >
                                    {copied === 'key' ? <Check size={14} className="text-green-400" /> : <Copy size={14} className="text-text-secondary" />}
                                </button>
                            </div>

                            <p className="text-text-muted text-xs">
                                Type : TOTP · Algorithme : SHA-1 · Période : 30 s · Chiffres : 6
                            </p>

                            <p className="text-text-secondary text-sm font-medium mt-2">
                                Ou scannez l&apos;URI otpauth (mode avancé) :
                            </p>
                            <div className="flex items-center gap-2">
                                <code className="flex-1 bg-surface-bg text-text-secondary text-xs font-mono px-3 py-2 rounded-lg break-all select-all">
                                    {session.qrUrl}
                                </code>
                                <button
                                    onClick={() => copy(session.qrUrl, 'url')}
                                    className="shrink-0 p-2 bg-surface-elevated hover:bg-zinc-600 rounded-lg transition-colors"
                                    title="Copier l'URI"
                                >
                                    {copied === 'url' ? <Check size={14} className="text-green-400" /> : <Copy size={14} className="text-text-secondary" />}
                                </button>
                            </div>
                        </div>

                        {/* OTP input */}
                        <div className="space-y-2">
                            <label className="text-text-secondary text-sm font-medium">
                                3 — Entrez le code à 6 chiffres affiché dans l&apos;app :
                            </label>
                            <input
                                type="text"
                                inputMode="numeric"
                                maxLength={6}
                                pattern="\d{6}"
                                placeholder="000000"
                                value={otp}
                                onChange={e => setOtp(e.target.value.replace(/\D/g, '').slice(0, 6))}
                                onKeyDown={e => e.key === 'Enter' && handleVerifyOTP()}
                                className="w-full bg-surface-card border border-zinc-600 text-text-primary text-center text-xl font-mono tracking-widest rounded-xl px-4 py-3 focus:outline-none focus:border-orange-500 transition-colors"
                            />
                        </div>

                        {error && (
                            <div className="flex items-center gap-2 text-status-danger text-sm">
                                <AlertCircle size={14} />
                                <span>{error}</span>
                            </div>
                        )}

                        <button
                            onClick={handleVerifyOTP}
                            disabled={otp.length !== 6}
                            className="w-full py-3 px-4 bg-orange-500 hover:bg-orange-600 disabled:bg-surface-elevated disabled:cursor-not-allowed text-text-primary font-medium rounded-xl transition-colors"
                        >
                            Vérifier et activer le 2FA
                        </button>
                    </div>
                )}

                {status === 'verifying' && (
                    <div className="flex items-center justify-center gap-3 py-8 text-text-secondary">
                        <Loader2 className="animate-spin" size={20} />
                        <span>Vérification en cours…</span>
                    </div>
                )}

                {/* Footer */}
                <div className="mt-6 pt-4 border-t border-zinc-800">
                    <div className="flex items-center gap-2 text-text-muted text-xs">
                        <ShieldCheck size={12} />
                        <span>Le secret TOTP n&apos;est jamais stocké sur nos serveurs — clé locale dans l&apos;app uniquement.</span>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useEffect, useState } from 'react';
import { Package, Plus, Trash2, Edit2, Loader2, Save, X } from 'lucide-react';
import { toast } from 'sonner';
import { authedFetch } from '@/lib/client/authedFetch';

interface CatalogItem {
  id: string;
  name: string;
  basePrice: number;
  category: string;
}

export function PluginCatalogManager() {
  const [catalog, setCatalog] = useState<CatalogItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Partial<CatalogItem>>({});

  const [isCreating, setIsCreating] = useState(false);

  const loadCatalog = async () => {
    setLoading(true);
    try {
      const res = await authedFetch('/api/admin/fleet/catalog');
      if (!res.ok) throw new Error('Erreur de chargement');
      const data = await res.json();
      const itemsArray = Object.entries(data.catalog || {}).map(([id, val]: [string, Record<string, unknown>]) => ({
        id,
        ...val
      }));
      setCatalog(itemsArray as unknown as CatalogItem[]);
    } catch (e) {
      toast.error('Impossible de charger le catalogue');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadCatalog();
  }, []);

  const handleSave = async (id: string, form: Partial<CatalogItem>) => {
    if (!id.trim()) { toast.error('L\'identifiant du plugin est obligatoire'); return; }
    if (!form.name?.trim()) { toast.error('Le nom du plugin est obligatoire'); return; }
    try {
      const payload = { id: id.trim(), ...form };
      const res = await authedFetch('/api/admin/fleet/catalog', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      if (!res.ok) throw new Error('Save error');
      toast.success('Offre sauvegardée avec succès');
      setEditingId(null);
      setIsCreating(false);
      await loadCatalog();
    } catch (e) {
      toast.error('Erreur lors de la sauvegarde');
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Voulez-vous vraiment supprimer cette offre du catalogue ?')) return;
    try {
      const res = await authedFetch(`/api/admin/fleet/catalog?id=${encodeURIComponent(id)}`, {
        method: 'DELETE'
      });
      if (!res.ok) throw new Error('Delete error');
      toast.success('Offre supprimée');
      await loadCatalog();
    } catch (e) {
      toast.error('Erreur lors de la suppression');
    }
  };

  const startEdit = (item: CatalogItem) => {
    setEditingId(item.id);
    setEditForm(item);
  };

  const startCreate = () => {
    setIsCreating(true);
    setEditForm({ id: '', name: '', basePrice: 0, category: 'General' });
  };

  return (
    <div className="p-6 bg-surface-card backdrop-blur-md border border-border-subtle rounded-2xl">
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <Package className="w-5 h-5 text-brand" />
          <h3 className="text-sm font-bold uppercase tracking-widest text-text-secondary">Gestion du Catalogue</h3>
        </div>
        <button
          onClick={startCreate}
          className="flex items-center gap-2 px-3 py-1.5 bg-brand/10 hover:bg-brand/20 text-brand text-xs font-bold rounded-lg transition-colors"
        >
          <Plus className="w-3.5 h-3.5" /> Nouvelle Offre
        </button>
      </div>

      {loading ? (
        <div className="flex justify-center py-8"><Loader2 className="w-6 h-6 animate-spin text-brand" /></div>
      ) : (
        <div className="space-y-4">
          {isCreating && (
            <div className="p-4 bg-brand/5 border border-brand/20 rounded-xl space-y-3">
              <div className="grid grid-cols-2 gap-4">
                <input 
                  type="text" 
                  placeholder="ID Unique (ex: my_plugin)"
                  value={editForm.id || ''}
                  onChange={e => setEditForm({ ...editForm, id: e.target.value })}
                  className="bg-surface-card border border-border-subtle rounded-lg px-3 py-2 text-sm"
                />
                <input 
                  type="text" 
                  placeholder="Nom de l'offre"
                  value={editForm.name || ''}
                  onChange={e => setEditForm({ ...editForm, name: e.target.value })}
                  className="bg-surface-card border border-border-subtle rounded-lg px-3 py-2 text-sm"
                />
                <input 
                  type="number" 
                  placeholder="Prix mensuel (€)"
                  value={editForm.basePrice || ''}
                  onChange={e => setEditForm({ ...editForm, basePrice: parseFloat(e.target.value) })}
                  className="bg-surface-card border border-border-subtle rounded-lg px-3 py-2 text-sm"
                />
                <input 
                  type="text" 
                  placeholder="Catégorie (ex: Marketing)"
                  value={editForm.category || ''}
                  onChange={e => setEditForm({ ...editForm, category: e.target.value })}
                  className="bg-surface-card border border-border-subtle rounded-lg px-3 py-2 text-sm"
                />
              </div>
              <div className="flex justify-end gap-2">
                <button onClick={() => setIsCreating(false)} className="px-3 py-1.5 text-xs text-secondary hover:text-text-primary">Annuler</button>
                <button onClick={() => handleSave(editForm.id!, editForm)} className="px-3 py-1.5 bg-brand text-white text-xs font-bold rounded-lg flex items-center gap-1">
                  <Save className="w-3.5 h-3.5" /> Sauvegarder
                </button>
              </div>
            </div>
          )}

          {catalog.map(item => (
            <div key={item.id} className="flex items-center justify-between p-4 bg-surface-card border border-border-subtle rounded-xl group hover:border-focus/30 transition-all">
              {editingId === item.id ? (
                <div className="flex-1 grid grid-cols-4 gap-4 mr-4">
                  <input 
                    type="text" 
                    value={editForm.name || ''}
                    onChange={e => setEditForm({ ...editForm, name: e.target.value })}
                    className="bg-surface-card border border-border-subtle rounded-lg px-3 py-1 text-sm col-span-2"
                  />
                  <input 
                    type="number" 
                    value={editForm.basePrice !== undefined ? editForm.basePrice : ''}
                    onChange={e => setEditForm({ ...editForm, basePrice: parseFloat(e.target.value) })}
                    className="bg-surface-card border border-border-subtle rounded-lg px-3 py-1 text-sm"
                  />
                  <input 
                    type="text" 
                    value={editForm.category || ''}
                    onChange={e => setEditForm({ ...editForm, category: e.target.value })}
                    className="bg-surface-card border border-border-subtle rounded-lg px-3 py-1 text-sm"
                  />
                </div>
              ) : (
                <div className="flex-1">
                  <div className="flex items-center gap-2">
