"use client";

import React, { useEffect, useState } from 'react';
import { PackageOpen, ToggleLeft, ToggleRight, Loader2, ServerCog, Store } from 'lucide-react';
import { useFleet } from '@/shared/contexts/FleetContext';
import { toast } from 'sonner';
import { authedFetch } from '@/lib/client/authedFetch';

interface CatalogItem {
  name: string;
  basePrice: number;
  category?: string;
}

interface TenantPluginState {
  tenantId: string;
  activePlugins: Record<string, { active: boolean, activatedAt?: string }>;
}

interface PluginApiResponse {
  catalog: Record<string, CatalogItem>;
  tenantId: string;
  activePlugins: Record<string, { active: boolean, activatedAt?: string }>;
}

export function PluginEnginePanel() {
  const { instances } = useFleet();
  const [pluginsByTenant, setPluginsByTenant] = useState<TenantPluginState[]>([]);
  const [dynamicCatalog, setDynamicCatalog] = useState<Record<string, CatalogItem>>({});
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState<string | null>(null);

  const load = async () => {
    setLoading(true);
    try {
      let latestCatalog = {};
      const results = await Promise.allSettled(
        instances.map(async inst => {
          const res = await authedFetch(`/api/admin/fleet/plugins?tenantId=${encodeURIComponent(inst.id)}`);
          return res.ok ? (await res.json()) : null;
        })
      );

      const parsedResults = results
        .filter((r): r is PromiseFulfilledResult<PluginApiResponse> => r.status === 'fulfilled' && r.value !== null)
        .map(r => {
          latestCatalog = { ...latestCatalog, ...r.value.catalog };
          return { tenantId: r.value.tenantId, activePlugins: r.value.activePlugins };
        });

      setDynamicCatalog(latestCatalog);
      setPluginsByTenant(parsedResults);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (instances.length > 0) void load();
  }, [instances]);

  const togglePlugin = async (tenantId: string, pluginId: string, currentlyActive: boolean) => {
    setActionLoading(`${tenantId}-${pluginId}`);
    try {
      const method = currentlyActive ? 'DELETE' : 'POST';
      const res = await authedFetch('/api/admin/fleet/plugins', {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tenantId, pluginId })
      });

      if (!res.ok) throw new Error('API Error');

      toast.success(`Plugin ${currentlyActive ? 'désactivé' : 'activé'} avec succès`);
      await load(); // Refresh data
    } catch (e) {
      toast.error('Erreur lors du changement de statut');
    } finally {
      setActionLoading(null);
    }
  };

  return (
    <div className="p-6 bg-surface-card backdrop-blur-md border border-border-subtle rounded-2xl">
      <div className="flex items-center gap-3 mb-6">
        <ServerCog className="w-5 h-5 text-brand" />
        <h3 className="text-sm font-bold uppercase tracking-widest text-text-secondary">Moteur de Plugins (Marketplace)</h3>
      </div>

      {loading ? (
        <div className="flex justify-center py-8"><Loader2 className="w-6 h-6 animate-spin text-brand" /></div>
      ) : instances.length === 0 ? (
        <p className="text-xs text-secondary text-center py-6">Aucun tenant trouvé.</p>
      ) : (
        <div className="space-y-6">
          {pluginsByTenant.map(tenant => (
            <div key={tenant.tenantId} className="border border-focus/10 rounded-xl overflow-hidden">
              <div className="bg-surface-card border-b border-focus/10 p-3 flex items-center gap-2">
                <Store className="w-4 h-4 text-brand" />
                <span className="text-xs font-bold">{tenant.tenantId}</span>
              </div>
              <div className="p-4 grid grid-cols-1 lg:grid-cols-2 gap-4 bg-background/50">
                {Object.entries(dynamicCatalog).map(([pluginId, info]) => {
                  const isActive = tenant.activePlugins[pluginId]?.active === true;
                  const isActionLoading = actionLoading === `${tenant.tenantId}-${pluginId}`;

                  return (
                    <div key={pluginId} className="flex items-center justify-between p-3 bg-surface-card border border-border-subtle rounded-xl">
                      <div className="flex items-center gap-3">
                        <div className={`p-2 rounded-lg ${isActive ? 'bg-emerald-500/10 text-emerald-500' : 'bg-surface-card border border-border-subtle text-secondary'}`}>
                          <PackageOpen className="w-4 h-4" />
                        </div>
                        <div>
                          <div className="text-xs font-bold">{info.name}</div>
                          <div className="text-[10px] text-secondary font-mono">+{info.basePrice}€/mois</div>
                        </div>
                      </div>

                      <button 
                        disabled={isActionLoading}
                        onClick={() => togglePlugin(tenant.tenantId, pluginId, isActive)}
                        className="p-1 transition-transform active:scale-95 disabled:opacity-50"
                      >
                        {isActionLoading ? (
                          <Loader2 className="w-6 h-6 animate-spin text-brand" />
                        ) : isActive ? (
                          <ToggleRight className="w-8 h-8 text-emerald-500" />
                        ) : (
                          <ToggleLeft className="w-8 h-8 text-secondary" />
                        )}
                      </button>
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { PageHeader } from "@ui/PageHeader";
import { GlassCard } from "@ui/GlassCard";
import { StatCard, StatsGrid } from "@ui/StatCard";
import { Button } from "@ui/button";
import { SimulationService, MonteCarloResult, SimulationProfile } from "@/modules/intelligence/ia/simulator/SimulationService";
import { SimulatorConsole } from '@/shared/nexus/guards/admin/simulator/SimulatorConsole';
import { TrendingUp, Users, AlertTriangle, Play, RefreshCcw, DollarSign } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";

/**
 * 🌀 Nexus Temporal Simulator (Grade X)
 * UI de contrôle pour le forking de réalité et les prédictions Monte-Carlo.
 */
export default function SimulatorPage() {
    const [days, setDays] = useState(7);
    const [iterations, setIterations] = useState(5);
    const [profile, setProfile] = useState<SimulationProfile>("PIZZERIA_RUSH");
    const [loading, setLoading] = useState(false);
    const [results, setResults] = useState<MonteCarloResult[] | null>(null);

    const runSimulation = async () => {
        setLoading(true);
        try {
            const results = await SimulationService.runMonteCarlo(days, iterations, profile, 'EMPIRE');
            setResults(results);
        } catch (error) {
            console.error("Simulation failed:", error);
        } finally {
            setLoading(false);
        }
    };

    const formatCurrency = (cents: number) => {
        return new Intl.NumberFormat('fr-FR', { style: 'currency', currency: 'EUR' }).format(cents / 100);
    };

    return (
        <div className="flex flex-col gap-10 p-8 max-w-[1400px] mx-auto animate-in fade-in duration-1000">
            <PageHeader 
                title="Nexus Temporal Simulator" 
                subtitle="Grade X Shadow Context Forking & Live Monitoring"
                emoji="🌀"
            />

            <section className="flex flex-col gap-4">
                <SectionTitle title="Live Temporal Monitor" />
                <SimulatorConsole />
            </section>

            <section className="flex flex-col gap-6 pt-10 border-t border-border/50">
                <SectionTitle title="Predictive Monte-Carlo Forge" />
                <GlassCard className="p-8">
                <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                    <div className="flex flex-col gap-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-text-muted">Horizon Temporel (Jours)</label>
                        <input 
                            type="number" 
                            value={days} 
                            onChange={(e) => setDays(Number(e.target.value))}
                            className="bg-bg-primary border border-border rounded-xl p-3 focus:outline-none focus:border-action-primary"
                        />
                    </div>
                    <div className="flex flex-col gap-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-text-muted">Itérations (Timelines)</label>
                        <input 
                            type="number" 
                            value={iterations} 
                            onChange={(e) => setIterations(Number(e.target.value))}
                            className="bg-bg-primary border border-border rounded-xl p-3 focus:outline-none focus:border-action-primary"
                        />
                    </div>
                    <div className="flex flex-col gap-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-text-muted">Profil de Charge</label>
                        <select 
                            value={profile} 
                            onChange={(e) => setProfile(e.target.value as SimulationProfile)}
                            className="bg-bg-primary border border-border rounded-xl p-3 focus:outline-none focus:border-action-primary"
                        >
                            <option value="PIZZERIA_RUSH">Pizzeria Rush (Vol. Élevé)</option>
                            <option value="FINE_DINING_CALM">Fine Dining (Haute Marge)</option>
                            <option value="SUMMER_PEAK">Summer Peak (Chaos-ready)</option>
                            <option value="DEFAULT">Standard Business</option>
                        </select>
                    </div>
                    <div className="flex items-end">
                        <Button 
                            onClick={runSimulation} 
                            disabled={loading}
                            className="w-full h-[52px] gap-2"
                        >
                            {loading ? <RefreshCcw className="animate-spin w-4 h-4" /> : <Play className="w-4 h-4" />}
                            Lancer la Simulation
                        </Button>
                    </div>
                </div>
            </GlassCard>
            </section>

            <AnimatePresence>
                {results && (
                    <motion.div 
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="flex flex-col gap-8"
                    >
                        <SectionTitle title="Moyenne des Mondes Parallèles" />
                        <StatsGrid columns={4}>
                            <StatCard
                                label="Chiffre d'Affaire Estimé"
                                value={formatCurrency(results.reduce((acc, r) => acc + r.metrics.totalRevenue, 0) / results.length)}
                                icon={<DollarSign />}
                                accentColor="success"
                            />
                            <StatCard
                                label="Profit Net Prédit"
                                value={formatCurrency(results.reduce((acc, r) => acc + r.metrics.netProfit, 0) / results.length)}
                                icon={<TrendingUp />}
                                accentColor="accent"
                            />
                            <StatCard
                                label="Index de Burnout Staff"
                                value={`${(results.reduce((acc, r) => acc + r.metrics.burnoutIndex, 0) / results.length).toFixed(1)}%`}
                                icon={<Users />}
                                accentColor={results.reduce((acc, r) => acc + r.metrics.burnoutIndex, 0) / results.length > 70 ? "error" : "info"}
                            />
                            <StatCard
                                label="Anomalies Potentielles"
                                value={(results.reduce((acc, r) => acc + r.metrics.anomalyCount, 0) / results.length).toFixed(1)}
                                icon={<AlertTriangle />}
                                accentColor="warning"
                            />
                        </StatsGrid>

                        <SectionTitle title="Visualisation des Timelines" />
                        <GlassCard className="p-8 h-[300px] flex items-end gap-1">
                            {results.map((r, i) => (
                                <div key={i} className="flex-1 flex flex-col items-center gap-2 group relative">
                                    <div 
                                        className="w-full bg-action-primary border-t-2 border-action-primary rounded-t-lg transition-all hover:bg-action-primary"
                                        style={{ height: `${Math.max(10, (r.metrics.netProfit / results[0].metrics.totalRevenue) * 500)}%` }}
                                    >
                                        <div className="absolute -top-12 left-1/2 -translate-x-1/2 bg-bg-secondary border border-border p-2 rounded text-[8px] opacity-0 group-hover:opacity-100 transition-opacity z-10 whitespace-nowrap">
                                            {r.timelineId}<br/>
                                            Profit: {formatCurrency(r.metrics.netProfit)}
                                        </div>
                                    </div>
                                    <span className="text-[8px] text-text-muted font-mono">T-{i+1}</span>
                                </div>
                            ))}
                        </GlassCard>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}

function SectionTitle({ title }: { title: string }) {
    return (
        <div className="flex items-center gap-4">
            <h2 className="font-brand italic text-2xl text-text-primary capitalize">{title}</h2>
            <div className="h-px bg-border flex-1" />
        </div>
    );
}

