import { NextRequest, NextResponse } from 'next/server';
import { FECGenerator } from '@/modules/finance';
import { DocumentVault } from '@/modules/compliance/securite/DocumentVault';
import { FinanceErrorCode, CoreErrorCode } from '@/shared/nexus/contracts/errors.types';
import { JournalEntry } from '@/shared/nexus/contracts/finance.types';
import { requireTenantAdmin, isDenied } from '@/lib/server/adminAuthGuard';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/logger';

/**
 * 🏛️ Route: Export FEC - Grade X+++
 * Endpoint d'export du Fichier des Écritures Comptables.
 * Auth : JWT vérifié (admin/manager du tenant, ou fleet_admin).
 * Le tenant vient du token — jamais d'un header client.
 */
export async function POST(request: NextRequest) {
    try {
        const caller = await requireTenantAdmin(request);
        if (isDenied(caller)) return caller;
        const tenantId = caller.tenantId;

        const body = await request.json();
        const { siren, yearMonth } = body as { siren: string, yearMonth: string };

        if (!siren || !yearMonth || !/^\d{4}-\d{2}$/.test(yearMonth)) {
            return NextResponse.json({
                success: false,
                error: FinanceErrorCode.TRANSACTION_FAILED,
                metadata: { version: 'v2', timestamp: new Date().toISOString() }
            }, { status: 400 });
        }

        // 1. Lecture server-side du ledger scellé (jamais depuis le body client)
        //
        // Bornes de période EXCLUSIVES en fin de mois : les dates sont stockées en
        // ISO complet (ex. "2026-07-31T09:12:00Z"). Un `<= "2026-07-31"` exclurait
        // toutes les écritures du 31 (comparaison lexicale : "...T09" > "...-31").
        // On borne donc par `< 1er du mois suivant`, ce qui inclut toute la
        // journée du dernier jour, quelle que soit l'heure — et évite le faux
        // "-31" pour les mois de 28/30 jours.
        const [year, month] = yearMonth.split('-');
        const y = parseInt(year, 10);
        const m = parseInt(month, 10);
        const monthPadded = month.padStart(2, '0');
        const startOfMonth = `${year}-${monthPadded}-01`;
        const startOfNextMonth = m === 12
            ? `${y + 1}-01-01`
            : `${y}-${String(m + 1).padStart(2, '0')}-01`;

        const entries = await Nexus.adapter.query<JournalEntry>(
            `tenants/${tenantId}/journalEntries`,
            {
                where: [
                    { field: 'date', operator: '>=', value: startOfMonth },
                    { field: 'date', operator: '<', value: startOfNextMonth },
                ],
                orderBy: { field: 'date', direction: 'asc' },
            }
        );

        logger.info(`[FEC] Export demandé — tenant ${tenantId}, période ${yearMonth}`);

        if (entries.length === 0) {
            logger.warn(`[FEC] Aucune écriture pour ${tenantId} sur ${yearMonth}`);
            return NextResponse.json({
                success: false,
                error: FinanceErrorCode.TRANSACTION_FAILED,
                metadata: { version: 'v2', timestamp: new Date().toISOString() }
            }, { status: 404 });
        }

        // 2. Génération et scellage NF525 (QuantumCrypto)
        const result = await FECGenerator.generate(entries, siren, yearMonth);

        // 3. Archivage immuable des preuves fiscales
        await DocumentVault.archive(result.filename, result.content, {
            tenantId,
            type: 'FEC_EXPORT',
            finalHash: result.finalHash
        });

        logger.info(`[FEC] Export généré — tenant ${tenantId}, ${entries.length} écritures, fichier ${result.filename}`);

        // 4. Retour du Fichier (Headers stricts DGFiP)
        return new NextResponse(result.content, {
            status: 200,
            headers: {
                'Content-Type': 'text/plain; charset=utf-8',
                'Content-Disposition': `attachment; filename="${result.filename}"`
            }
        });

    } catch (err) {
        logger.error('[FEC] Erreur lors de la génération', err);
        return NextResponse.json({
            success: false,
            error: CoreErrorCode.INTERNAL_CRASH,
            metadata: { version: 'v2', timestamp: new Date().toISOString() }
        }, { status: 500 });
    }
}

import { NextResponse } from 'next/server';
import { requireFleetAdmin, isDenied } from '@/lib/server/adminAuthGuard';
import { FleetOutboxDrainService } from '@/modules/intelligence/ia/fleet/FleetOutboxDrainService';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/logger';
import { toError } from "@/lib/toError";

/**
 * 🚀 Draine les outboxes de tous les tenants vers la vue globale MCC.
 * Endpoint accessible uniquement aux Fleet Admins (ou déclenché par un cron sécurisé).
 */
export async function POST(request: Request) {
  try {
    const admin = await requireFleetAdmin(request);
    if (isDenied(admin)) return admin;

    // Récupérer la liste des tenants actifs
    const tenants = await Nexus.adapter.query<{ id: string }>('mcc/tenants', {
        where: [{ field: 'status', operator: '==', value: 'active' }]
    });

    let totalDrained = 0;
    const results = [];

    for (const tenant of tenants) {
        const count = await FleetOutboxDrainService.drainTenant(tenant.id);
        if (count > 0) {
            results.push({ tenantId: tenant.id, count });
            totalDrained += count;
        }
    }

    logger.info(`[DrainOutbox] Drained ${totalDrained} events across ${results.length} tenants`);

    return NextResponse.json({
        success: true,
        drained: totalDrained,
        details: results
    });

  } catch (error) {
    logger.error('[DrainOutbox] Error during global drain', toError(error).message);
    return new NextResponse(JSON.stringify({ error: 'Internal Server Error' }), { status: 500, headers: { 'Content-Type': 'application/json' } });
  }
}

import 'server-only';
import { NextResponse } from 'next/server';
import { requireTenantRole, isDenied } from '@/lib/server/adminAuthGuard';
import { ConnectorHub } from '@/modules/intelligence/connectors/hub';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { NexusEventBus } from '@/shared/eventBus/NexusEventBus';
import { logger } from '@/lib/logger';
import type { ConnectorState } from '@/shared/connector-manifest';

/**
 * POST /api/connectors/[id]/activate
 * Active un connecteur pour le tenant.
 * - authType 'none' → status 'active' immédiatement
 * - authType autre  → status 'pending_config' (credentials requis via PUT /credentials)
 * Rôle minimum : directeur (niveau 90 = CONNECTOR_PERM_LEVELS['configure'])
 */
export async function POST(
  req: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const caller = await requireTenantRole(req, 'directeur');
  if (isDenied(caller)) return caller;

  const { id } = await params;
  const { tenantId, uid } = caller;

  let manifest;
  try {
    manifest = ConnectorHub.getManifest(id);
  } catch {
    return NextResponse.json({ error: `Connecteur inconnu : ${id}` }, { status: 404 });
  }

  const tenantConfig = await Nexus.adapter.get(`tenants/${tenantId}/tenantConfig`) as Record<string, unknown> | null;
  if (!tenantConfig || !ConnectorHub.isAvailableForTenant(id, tenantConfig as Parameters<typeof ConnectorHub.isAvailableForTenant>[1])) {
    return NextResponse.json({ error: 'Connecteur non disponible pour ce vertical ou ces capabilities' }, { status: 403 });
  }

  const status: ConnectorState['status'] = manifest.authType === 'none' ? 'active' : 'pending_config';

  const existing = await Nexus.adapter.get(`tenants/${tenantId}/connectors/${id}`) as ConnectorState | null;
  if (existing?.status === 'active') {
    return NextResponse.json({ message: 'Déjà actif', status: 'active' });
  }

  const state: ConnectorState = {
    status,
    activatedAt: Date.now(),
    activatedBy: uid,
    ...(existing?.credentials ? { credentials: existing.credentials } : {}),
  };

  await Nexus.adapter.set(`tenants/${tenantId}/connectors/${id}`, state);

  await NexusEventBus.emit('connectors.activated', { tenantId, connectorId: id, activatedBy: uid });

  logger.info(`[connectors/activate] tenant=${tenantId} connector=${id} status=${status} by=${uid}`);

  return NextResponse.json({ status, message: status === 'active' ? 'Connecteur actif' : 'En attente de configuration' });
}

/**
 * DELETE /api/connectors/[id]/activate
 * Désactive un connecteur (status → 'disabled'). Les credentials chiffrés sont conservés.
 * Rôle minimum : directeur
 */
export async function DELETE(
  req: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const caller = await requireTenantRole(req, 'directeur');
  if (isDenied(caller)) return caller;

  const { id } = await params;
  const { tenantId, uid } = caller;

  try { ConnectorHub.getManifest(id); } catch {
    return NextResponse.json({ error: `Connecteur inconnu : ${id}` }, { status: 404 });
  }

  const existing = await Nexus.adapter.get(`tenants/${tenantId}/connectors/${id}`) as ConnectorState | null;
  if (!existing || existing.status === 'disabled') {
    return NextResponse.json({ message: 'Déjà désactivé', status: 'disabled' });
  }

  await Nexus.adapter.set(`tenants/${tenantId}/connectors/${id}`, {
    ...existing,
    status: 'disabled',
  });

  await NexusEventBus.emit('connectors.deactivated', { tenantId, connectorId: id, deactivatedBy: uid });

  logger.info(`[connectors/deactivate] tenant=${tenantId} connector=${id} by=${uid}`);

  return NextResponse.json({ status: 'disabled' });
}

import 'server-only';
import { NextResponse } from 'next/server';
import { requireTenantRole, isDenied } from '@/lib/server/adminAuthGuard';
import { ConnectorHub } from '@/modules/intelligence/connectors/hub';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { NexusEventBus } from '@/shared/eventBus/NexusEventBus';
import { encryptCredentials, validateCredentialFields } from '@/lib/server/credentialCipher';
import { logger } from '@/lib/logger';
import type { ConnectorState } from '@/shared/connector-manifest';

/**
 * PUT /api/connectors/[id]/credentials
 * Sauvegarde les credentials chiffrés pour un connecteur.
 * Les champs requis du manifest sont validés avant chiffrement.
 * Après sauvegarde le status passe à 'pending_config' — utiliser POST /test pour activer.
 * Rôle minimum : directeur
 */
export async function PUT(
  req: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const caller = await requireTenantRole(req, 'directeur');
  if (isDenied(caller)) return caller;

  const { id } = await params;
  const { tenantId, uid } = caller;

  let manifest;
  try {
    manifest = ConnectorHub.getManifest(id);
  } catch {
    return NextResponse.json({ error: `Connecteur inconnu : ${id}` }, { status: 404 });
  }

  if (manifest.authType === 'none') {
    return NextResponse.json({ error: 'Ce connecteur ne requiert pas de credentials' }, { status: 400 });
  }

  const body = await req.json() as Record<string, string>;

  // Valider les champs requis selon le manifest
  if (manifest.fields && manifest.fields.length > 0) {
    const { valid, missing } = validateCredentialFields(body, manifest.fields);
    if (!valid) {
      return NextResponse.json({ error: 'Champs manquants', missing }, { status: 422 });
    }
  }

  const encrypted = encryptCredentials(body);

  const existing = await Nexus.adapter.get(`tenants/${tenantId}/connectors/${id}`) as ConnectorState | null;
  const state: ConnectorState = {
    status: 'pending_config',
    activatedAt: existing?.activatedAt ?? Date.now(),
    activatedBy: existing?.activatedBy ?? uid,
    credentials: encrypted,
  };

  await Nexus.adapter.set(`tenants/${tenantId}/connectors/${id}`, state);
  await NexusEventBus.emit('connectors.config_saved', { tenantId, connectorId: id, savedBy: uid });

  logger.info(`[connectors/credentials] PUT tenant=${tenantId} connector=${id} by=${uid}`);

  return NextResponse.json({
    message: 'Credentials sauvegardés — utilisez POST /test pour valider et activer',
    status: 'pending_config',
  });
}

/**
 * DELETE /api/connectors/[id]/credentials
 * Supprime les credentials et repasse le connecteur en 'pending_config'.
 * Rôle minimum : directeur
 */
export async function DELETE(
  req: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const caller = await requireTenantRole(req, 'directeur');
  if (isDenied(caller)) return caller;

  const { id } = await params;
  const { tenantId, uid } = caller;

  try { ConnectorHub.getManifest(id); } catch {
    return NextResponse.json({ error: `Connecteur inconnu : ${id}` }, { status: 404 });
  }

  const existing = await Nexus.adapter.get(`tenants/${tenantId}/connectors/${id}`) as ConnectorState | null;
  if (!existing) return NextResponse.json({ error: 'Connecteur non activé' }, { status: 404 });

  const { credentials: _removed, ...stateWithout } = existing as ConnectorState & { credentials?: unknown };
  await Nexus.adapter.set(`tenants/${tenantId}/connectors/${id}`, {
    ...stateWithout,
    status: 'pending_config',
  });

  logger.info(`[connectors/credentials] DELETE tenant=${tenantId} connector=${id} by=${uid}`);

  return NextResponse.json({ message: 'Credentials supprimés', status: 'pending_config' });
}

import 'server-only';
import { NextResponse } from 'next/server';
import { requireTenantUser, isDenied } from '@/lib/server/adminAuthGuard';
import { ConnectorHub } from '@/modules/intelligence/connectors/hub';
import { Nexus } from '@/lib/nexus/NexusAdapter';
