/**
 * GET /api/connectors/[id]
 * Détail d'un connecteur (manifest + état). Sans credentials.
 */
export async function GET(
  req: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const caller = await requireTenantUser(req);
  if (isDenied(caller)) return caller;

  const { id } = await params;
  const { tenantId } = caller;

  let manifest;
  try {
    manifest = ConnectorHub.getManifest(id);
  } catch {
    return NextResponse.json({ error: `Connecteur inconnu : ${id}` }, { status: 404 });
  }

  const raw = await Nexus.adapter.get(`tenants/${tenantId}/connectors/${id}`) as ConnectorState & { credentials?: unknown } | null;
  const state = raw ? (({ credentials: _c, ...s }) => s)(raw) : null;

  return NextResponse.json({ manifest, state });
}

import 'server-only';
import { NextResponse } from 'next/server';
import { requireTenantRole, isDenied } from '@/lib/server/adminAuthGuard';
import { ConnectorHub } from '@/modules/intelligence/connectors/hub';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { NexusEventBus } from '@/shared/eventBus/NexusEventBus';
import { decryptCredentials } from '@/lib/server/credentialCipher';
import { logger } from '@/lib/logger';
import type { ConnectorState } from '@/shared/connector-manifest';
import { toError } from "@/lib/toError";

// Pilier-specific factories — importés à la demande selon la catégorie du manifest
const SYNC_HANDLERS: Record<string, (tenantId: string, credentials: Record<string, string>) => Promise<number>> = {
  reservations: async (tenantId, credentials) => {
    const { ReservationProviderFactory } = await import('@/modules/ops/connectors/reservations');
    const provider = ReservationProviderFactory.get(credentials._providerId);
    const items = await provider.listUpcoming(tenantId);
    await Promise.all(items.map(r => Nexus.adapter.set(`tenants/${tenantId}/reservations/${r.id}`, r)));
    return items.length;
  },
  reviews: async (tenantId, _credentials) => {
    const { ReviewProviderFactory } = await import('@/modules/commerce/connectors/reviews');
    const provider = ReviewProviderFactory.get();
    const since = new Date(Date.now() - 7 * 86_400_000); // 7 derniers jours
    const items = await provider.fetchRecent(tenantId, since);
    await Promise.all(items.map(r => Nexus.adapter.set(`tenants/${tenantId}/reviews/${r.id}`, r)));
    return items.length;
  },
  delivery: async (tenantId, credentials) => {
    const { DeliveryProviderFactory } = await import('@/modules/ops/connectors/delivery');
    const provider = DeliveryProviderFactory.get(credentials._providerId);
    const items = await provider.listPendingOrders(tenantId);
    return items.length;
  },
};

/**
 * POST /api/connectors/[id]/sync
 * Déclenche une synchronisation manuelle pour un connecteur actif.
 * Rôle minimum : manager (CONNECTOR_PERM_LEVELS['manage'] = 70)
 */
export async function POST(
  req: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const caller = await requireTenantRole(req, 'manager');
  if (isDenied(caller)) return caller;

  const { id } = await params;
  const { tenantId } = caller;

  let manifest;
  try {
    manifest = ConnectorHub.getManifest(id);
  } catch {
    return NextResponse.json({ error: `Connecteur inconnu : ${id}` }, { status: 404 });
  }

  const stored = await Nexus.adapter.get(`tenants/${tenantId}/connectors/${id}`) as (ConnectorState & { credentials?: string }) | null;
  if (!stored || stored.status !== 'active') {
    return NextResponse.json({ error: 'Connecteur non actif — activez-le d\'abord' }, { status: 409 });
  }

  const credentials: Record<string, string> = stored.credentials
    ? { ...decryptCredentials(stored.credentials), _providerId: id }
    : { _providerId: id };

  const handler = SYNC_HANDLERS[manifest.category];
  if (!handler) {
    // Pas de handler dédié : émettre un événement générique pour traitement asynchrone
    await NexusEventBus.emit('connectors.sync_completed', { tenantId, connectorId: id, itemsSynced: 0 });
    logger.info(`[connectors/sync] tenant=${tenantId} connector=${id} → async (no sync handler)`);
    return NextResponse.json({ queued: true, message: 'Synchronisation mise en file d\'attente' });
  }

  try {
    const count = await handler(tenantId, credentials);

    await Nexus.adapter.set(`tenants/${tenantId}/connectors/${id}`, {
      ...stored,
      lastSyncAt: Date.now(),
      errorMessage: undefined,
    });

    await NexusEventBus.emit('connectors.sync_completed', { tenantId, connectorId: id, itemsSynced: count });
    logger.info(`[connectors/sync] tenant=${tenantId} connector=${id} synced=${count}`);

    return NextResponse.json({ ok: true, itemsSynced: count });
  } catch (err) {
    const error = toError(err).message;
    await Nexus.adapter.set(`tenants/${tenantId}/connectors/${id}`, { ...stored, status: 'error', errorMessage: error });
    await NexusEventBus.emit('connectors.sync_failed', { tenantId, connectorId: id, error });
    logger.error(`[connectors/sync] tenant=${tenantId} connector=${id} failed`, err);
    return NextResponse.json({ ok: false, error }, { status: 500 });
  }
}

import 'server-only';
import { NextResponse } from 'next/server';
import { requireTenantRole, isDenied } from '@/lib/server/adminAuthGuard';
import { ConnectorHub } from '@/modules/intelligence/connectors/hub';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { NexusEventBus } from '@/shared/eventBus/NexusEventBus';
import { decryptCredentials } from '@/lib/server/credentialCipher';
import { ConnectorRegistry } from '@/modules/commerce/acquisition/onboarding/migration/connectors';
import { logger } from '@/lib/logger';
import type { ConnectorState } from '@/shared/connector-manifest';
import type { ConnectorId } from '@/modules/commerce/acquisition/onboarding/migration/connectors/types';
import { toError } from "@/lib/toError";

/**
 * POST /api/connectors/[id]/test
 * Teste la connexion avec les credentials stockés.
 * Si le test réussit : status → 'active'.
 * Si le test échoue  : status → 'error' + errorMessage.
 * Rôle minimum : directeur
 */
export async function POST(
  req: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const caller = await requireTenantRole(req, 'directeur');
  if (isDenied(caller)) return caller;

  const { id } = await params;
  const { tenantId } = caller;

  let manifest;
  try {
    manifest = ConnectorHub.getManifest(id);
  } catch {
    return NextResponse.json({ error: `Connecteur inconnu : ${id}` }, { status: 404 });
  }

  // Connecteurs sans auth → toujours OK
  if (manifest.authType === 'none') {
    await Nexus.adapter.set(`tenants/${tenantId}/connectors/${id}`, {
      status: 'active',
      activatedAt: Date.now(),
      activatedBy: caller.uid,
    } satisfies ConnectorState);
    return NextResponse.json({ ok: true, message: 'Aucune configuration requise — connecteur actif' });
  }

  // Lire l'état stocké
  const stored = await Nexus.adapter.get(`tenants/${tenantId}/connectors/${id}`) as (ConnectorState & { credentials?: string }) | null;
  if (!stored?.credentials) {
    return NextResponse.json({ ok: false, error: 'Aucun credential trouvé — utilisez PUT /credentials d\'abord' }, { status: 422 });
  }

  let credentials: Record<string, string>;
  try {
    credentials = decryptCredentials(stored.credentials);
  } catch (err) {
    logger.error(`[connectors/test] Déchiffrement échoué tenant=${tenantId} connector=${id}`, err);
    return NextResponse.json({ ok: false, error: 'Credentials corrompus — veuillez les ressaisir' }, { status: 500 });
  }

  // Test via le ConnectorRegistry d'onboarding si le connecteur est connu là
  let testResult: { ok: boolean; error?: string } = { ok: false, error: 'Test non implémenté pour ce connecteur' };

  const migrationIds = ConnectorRegistry.available() as string[];
  if (migrationIds.includes(id)) {
    try {
      const connector = ConnectorRegistry.get(id as ConnectorId);
      const result = await connector.testConnection({ apiKey: credentials.apiKey, accessToken: credentials.accessToken, ...credentials });
      testResult = { ok: result.ok, error: result.error };
    } catch (err) {
      testResult = { ok: false, error: toError(err).message };
    }
  } else {
    // Pour les autres providers runtime : vérification de présence des champs requis
    const allFieldsPresent = !manifest.fields || manifest.fields
      .filter(f => !f.optional)
      .every(f => !!credentials[f.key]);
    testResult = allFieldsPresent
      ? { ok: true }
      : { ok: false, error: 'Champs de configuration manquants' };
  }

  // Mettre à jour le statut selon le résultat
  const newStatus: ConnectorState['status'] = testResult.ok ? 'active' : 'error';
  await Nexus.adapter.set(`tenants/${tenantId}/connectors/${id}`, {
    ...stored,
    status: newStatus,
    ...(testResult.ok ? { errorMessage: undefined, lastSyncAt: Date.now() } : { errorMessage: testResult.error }),
  });

  if (testResult.ok) {
    await NexusEventBus.emit('connectors.activated', { tenantId, connectorId: id, activatedBy: caller.uid });
  } else {
    await NexusEventBus.emit('connectors.sync_failed', { tenantId, connectorId: id, error: testResult.error ?? 'Test échoué' });
  }

  logger.info(`[connectors/test] tenant=${tenantId} connector=${id} ok=${testResult.ok}`);

  return NextResponse.json({ ok: testResult.ok, status: newStatus, error: testResult.error });
}

import 'server-only';
import { NextResponse } from 'next/server';
import { requireTenantUser, isDenied } from '@/lib/server/adminAuthGuard';
import { ConnectorHub } from '@/modules/intelligence/connectors/hub';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import type { ConnectorState } from '@/shared/connector-manifest';

/**
 * GET /api/connectors
 * Liste tous les connecteurs disponibles pour le tenant avec leur état Nexus.
 * Accessible à tous les rôles — les credentials chiffrés sont toujours omis.
 */
export async function GET(req: Request) {
  const caller = await requireTenantUser(req);
  if (isDenied(caller)) return caller;

  const { tenantId } = caller;

  let tenantConfig: Record<string, unknown> | null = null;
  let states: (ConnectorState & { id: string })[] = [];
  try {
    tenantConfig = await Nexus.adapter.get(`tenants/${tenantId}/tenantConfig`) as Record<string, unknown> | null;
    if (tenantConfig) {
      states = await Nexus.adapter.query<ConnectorState & { id: string }>(`tenants/${tenantId}/connectors`, {}).catch(() => []);
    }
  } catch {
    // Nexus server adapter non configuré (dev local sans Firebase) — on utilise un config par défaut
  }
  // Fallback dev : config minimale pour afficher le catalogue
  if (!tenantConfig) tenantConfig = { variant: 'restaurant' };

  const stateMap: Record<string, ConnectorState> = {};
  for (const s of states) {
    const { id, ...rest } = s;
    // Ne jamais exposer les credentials chiffrés au client
    const { credentials: _creds, ...safeState } = rest as ConnectorState & { credentials?: unknown };
    stateMap[id] = safeState as ConnectorState;
  }

  const connectors = ConnectorHub.forTenant(
    tenantConfig as Parameters<typeof ConnectorHub.forTenant>[0],
    stateMap,
  );

  return NextResponse.json({ connectors });
}

import { NextRequest, NextResponse } from 'next/server';
import { z } from 'zod';
import { Resend } from 'resend';
import { requireTenantAdmin, isDenied } from '@/lib/server/adminAuthGuard';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/logger';

const resend = process.env.RESEND_API_KEY ? new Resend(process.env.RESEND_API_KEY) : null;
const FROM_EMAIL = process.env.RESEND_FROM_EMAIL ?? 'noreply@restaurant-os.app';

const AutomationConfigSchema = z.object({
    enabled: z.boolean(),
    delayDays: z.number().int().min(0).max(365),
    subject: z.string().min(1).max(200),
    body: z.string().min(1),
});

const BodySchema = z.object({
    automation: z.enum(['birthday', 'winback', 'postvisit']),
    config: AutomationConfigSchema,
});

interface Customer {
    id: string;
    email?: string;
    firstName?: string;
    lastName?: string;
    lastVisitDate?: string;
    birthDate?: string;
}

function interpolate(template: string, vars: Record<string, string>): string {
    return template.replace(/\{\{(\w+)\}\}/g, (_, key) => vars[key] ?? '');
}

function isBirthdayToday(birthDate?: string): boolean {
    if (!birthDate) return false;
    const today = new Date();
    const bd = new Date(birthDate);
    return bd.getMonth() === today.getMonth() && bd.getDate() === today.getDate();
}

function daysSince(date?: string): number {
    if (!date) return 9999;
    return Math.floor((Date.now() - new Date(date).getTime()) / 86_400_000);
}

export async function POST(req: NextRequest) {
    const auth = await requireTenantAdmin(req);
    if (isDenied(auth)) return auth;

    const parsed = BodySchema.safeParse(await req.json().catch(() => null));
    if (!parsed.success) {
        return NextResponse.json({ error: 'Payload invalide' }, { status: 400 });
    }

    // tenantId vient TOUJOURS du token (SovereignGuard) — jamais du body client
    const tenantId = auth.tenantId;
    const { automation, config } = parsed.data;

    let targets: Array<Customer & { email: string }> = [];

    if (automation === 'birthday') {
        const raw = await Nexus.adapter.query<Customer>(`tenants/${tenantId}/customers`, {});
        targets = raw
            .filter((c): c is Customer & { email: string } => !!c.email)
            .filter(c => isBirthdayToday(c.birthDate));
    } else if (automation === 'winback') {
        const cutoff = new Date(Date.now() - config.delayDays * 86_400_000).toISOString();
        const raw = await Nexus.adapter.query<Customer>(`tenants/${tenantId}/customers`, {
            where: [{ field: 'lastVisitDate', operator: '<=', value: cutoff }],
        });
        targets = raw.filter((c): c is Customer & { email: string } => !!c.email);
    } else if (automation === 'postvisit') {
        const delay = config.delayDays;
        const windowStart = new Date(Date.now() - (delay + 1) * 86_400_000).toISOString();
        const windowEnd = new Date(Date.now() - delay * 86_400_000).toISOString();
        const raw = await Nexus.adapter.query<Customer>(`tenants/${tenantId}/customers`, {
            where: [
                { field: 'lastVisitDate', operator: '>=', value: windowStart },
                { field: 'lastVisitDate', operator: '<', value: windowEnd },
            ],
        });
        targets = raw.filter((c): c is Customer & { email: string } => !!c.email);
    }

    if (!targets.length) {
        return NextResponse.json({ sent: 0, message: 'Aucun client ciblé pour ce scénario' });
    }

    if (!resend) {
        logger.warn('[automations/run] RESEND_API_KEY not set — skipping real send');
        return NextResponse.json({ sent: targets.length, dry: true });
    }

    const BATCH = 50;
    let sent = 0;

    for (let i = 0; i < targets.length; i += BATCH) {
        const batch = targets.slice(i, i + BATCH);
        try {
            await resend.batch.send(
                batch.map(c => ({
                    from: FROM_EMAIL,
                    to: c.email!,
                    subject: interpolate(config.subject, { firstName: c.firstName ?? 'cher client', delayDays: String(config.delayDays) }),
                    text: interpolate(config.body, { firstName: c.firstName ?? 'cher client', delayDays: String(config.delayDays) }),
                }))
            );
            sent += batch.length;
        } catch (err) {
            logger.error('[automations/run] Batch error', err);
        }
    }

    logger.info(`[automations/run] ${automation}: ${sent}/${targets.length} emails sent for tenant ${tenantId}`);
    return NextResponse.json({ sent });
}

import { NextRequest, NextResponse } from 'next/server';
import { timingSafeEqual } from 'node:crypto';
import { requireTenantAdmin, isDenied } from '@/lib/server/adminAuthGuard';
import { getRateLimiter } from '@/infrastructure/services/rate-limiter';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { OpenBankingProviderFactory } from '@/modules/finance';
import { BankConnectionStore } from '@/modules/finance';
import { inferPCGAccount } from '@/modules/finance';
import { FiscalEngine } from '@/modules/finance/fiscalite/FiscalAdapter';
import { CryptoService } from '@/lib/CryptoService';
import type { FiscalSeal } from '@nexus/contracts';

async function resolveTenantId(request: NextRequest): Promise<{ tenantId: string } | NextResponse> {
    const internalSecret   = request.headers.get('x-internal-secret');
    const internalTenantId = request.headers.get('x-tenant-id');
    if (internalSecret && internalTenantId) {
        const expectedSecret = process.env.INTERNAL_API_SECRET;
        if (!expectedSecret) return NextResponse.json({ error: 'INTERNAL_API_SECRET manquant.' }, { status: 503 });
        const secretBuf   = Buffer.from(internalSecret);
        const expectedBuf = Buffer.from(expectedSecret);
        if (secretBuf.length !== expectedBuf.length || !timingSafeEqual(secretBuf, expectedBuf)) {
            return NextResponse.json({ error: 'Secret interne invalide.' }, { status: 401 });
        }
        return { tenantId: internalTenantId };
    }
    const caller = await requireTenantAdmin(request);
    if (isDenied(caller)) return caller;
    return { tenantId: caller.tenantId };
}

/**
 * POST /api/finance/bank/sync
 * Déclenche une synchronisation bancaire pour le tenant authentifié.
 * Auth : admin/manager du tenant (ou fleet_admin) — le tenant vient du token.
 * Aucun secret global n'est utilisé pour rafraîchir un compte : uniquement
 * le jeton utilisateur propre à CE tenant, chargé depuis sa connexion persistée.
 */
export async function POST(request: NextRequest) {
    try {
        const resolved = await resolveTenantId(request);
        if (resolved instanceof NextResponse) return resolved;
        const { tenantId } = resolved;

        // Rate limiting : max 10 syncs/heure par tenant (manuel ou webhook)
        const rl = await getRateLimiter().check(`bank:sync:${tenantId}`, 10, 60 * 60 * 1000);
        if (!rl.allowed) {
            return NextResponse.json({ error: 'Trop de synchronisations — réessayez dans 1h.' }, { status: 429 });
        }

        // Charger la connexion une seule fois — le provider est lu depuis connection.provider
        const connection = await BankConnectionStore.get(tenantId);
        const provider   = OpenBankingProviderFactory.get(connection?.provider);

        if (!provider.isDemoMode()) {
            if (!connection || connection.status !== 'active') {
                return NextResponse.json({ error: 'Aucune connexion bancaire active pour ce restaurant.' }, { status: 400 });
            }
            const userToken = BankConnectionStore.decryptToken(connection);
            await provider.refreshConnection(userToken);
        }

        const userToken = provider.isDemoMode() ? 'demo-user-token' : BankConnectionStore.decryptToken(connection!);
        const accounts = await provider.getAccounts(userToken);
        const fromDate = connection?.lastSyncAt
            ? connection.lastSyncAt.slice(0, 10)
            : new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);

        const existing = await Nexus.adapter.query<{ id: string; signature?: string }>(
            `tenants/${tenantId}/bankTransactions`
        );
        const knownSignatures = new Set(existing.map((e) => e.signature).filter(Boolean));

        const batch = Nexus.adapter.batch();
        let created = 0;

        // Charger le dernier seal pour chaîner les entrées (fin-6)
        const existingSeals = await Nexus.adapter.query<FiscalSeal>(
            `tenants/${tenantId}/fiscalSeals`
        );
        let lastSeal: FiscalSeal | undefined = existingSeals.sort(
            (a, b) => new Date(b.timestamp ?? 0).getTime() - new Date(a.timestamp ?? 0).getTime()
        )[0];

        for (const account of accounts) {
            const transactions = await provider.getTransactions(account.id, userToken, fromDate);
            for (const tx of transactions) {
                if (tx.signature && knownSignatures.has(tx.signature)) continue;
                const txId  = Nexus.adapter.generateId(`tenants/${tenantId}/bankTransactions`);
                const pcg   = inferPCGAccount(tx.label);

                // fin-6 : JournalEntry NF525
                const jeId = Nexus.adapter.generateId(`tenants/${tenantId}/journalEntries`);
                const journalEntry = {
                    id:              jeId,
                    date:            tx.date,
                    label:           tx.label,
                    amountInMicrounits: tx.amountInCents * 10_000,
                    type:            tx.type,
                    pcgAccount:      pcg?.account ?? '512',
                    pcgLabel:        pcg?.label ?? 'Banque',
                    source:          'bank_sync' as const,
                    bankTransactionId: txId,
                    createdAt:       new Date().toISOString(),
                };
                batch.set(`tenants/${tenantId}/journalEntries/${jeId}`, journalEntry);

                // fin-6 : scellement NF525
                const dataSnapshot = CryptoService.canonicalStringify(
                    journalEntry
                );
                const seal = await FiscalEngine.sealEntry(jeId, journalEntry as Record<string, string | number | boolean | null | undefined | object>, { lastSeal });
                batch.set(`tenants/${tenantId}/fiscalSeals/${seal.id}`, {
                    ...seal, dataSnapshot,
                });
                lastSeal = seal;

                batch.set(`tenants/${tenantId}/bankTransactions/${txId}`, {
                    id: txId,
                    ...tx,
                    accountId: account.id,
                    pcgAccount: pcg?.account,
                    pcgLabel: pcg?.label,
                    journalEntryId: jeId,
                    importedAt: Date.now(),
                    source: provider.id,
                });
                created++;
            }
        }

        await batch.commit();
        if (!provider.isDemoMode()) {
            await BankConnectionStore.markSynced(tenantId);
        }

        return NextResponse.json({
            success: true,
            isDemoMode: provider.isDemoMode(),
            synced: created,
            syncedAt: new Date().toISOString(),
        });
    } catch (err) {
        return NextResponse.json(
            { error: err instanceof Error ? err.message : 'Erreur interne lors de la synchronisation.' },
            { status: 500 }
        );
    }
}

import 'server-only';
import { NextRequest, NextResponse } from 'next/server';
import { FiscalSealer } from '@/modules/finance/fiscalite/FiscalSealer';
import { logger } from '@/lib/axiom';
import { JournalEntry } from '@nexus/contracts';
import { CryptoService } from '@/lib/CryptoService';
import { requireTenantRole, isDenied } from '@/lib/server/adminAuthGuard';
import { JsonObject } from "@/shared/types/json";
import { toError } from "@/lib/toError";

/**
 * 🛰️ API Backend de Synchro Hors-Ligne (Grade X)
 *
 * Reçoit les paquets de JournalEntry générés hors-ligne par la caisse.
 * Valide les montants, génère le vrai sceau NF525 serveur (avec NEXUS_TENANT_SECRET)
 * et enregistre de force dans Firestore (outrepassant les rules clientes).
 *
 * Auth : token Firebase JWT du POS (n'importe quel rôle tenant).
 * Le tenantId vient EXCLUSIVEMENT du token — pas du body (protection cross-tenant).
 */
export async function POST(req: NextRequest) {
  const caller = await requireTenantRole(req, 'serveur');
  if (isDenied(caller)) return caller;

  try {
    const body = await req.json();
    // tenantId du body intentionnellement ignoré — seul le claim JWT fait foi.
    const { journalEntries, isTrainingMode = false } = body;
    const tenantId = caller.tenantId;

    if (!tenantId || !journalEntries || !Array.isArray(journalEntries)) {
      return NextResponse.json({ error: 'Payload invalide' }, { status: 400 });
    }

    logger.info(`[Sync API] Réception de ${journalEntries.length} tickets hors-ligne pour le tenant ${tenantId}`);

    const sealedEntries = [];

    // On traite chaque ticket hors-ligne un par un pour garantir l'atomicité de la chaîne
    for (const entry of journalEntries as JournalEntry[]) {
      const receiptNumber = await FiscalSealer.generateSequentialReceiptNumber(tenantId);

      // 🛡️ DURCISSEMENT ANTI-FRAUDE : Recalcul serveur obligatoire
      const declaredTotal = entry.totalInMicrounits ?? (entry.amountInCents ?? 0) * 10_000;

      let computedCredits = 0;
      let computedDebits = 0;
      if (Array.isArray(entry.lines)) {
         for (const line of entry.lines) {
             if (line.side === 'credit') computedCredits += (line.creditInMicrounits ?? line.amountInCents * 10_000);
             if (line.side === 'debit') computedDebits += (line.debitInMicrounits ?? line.amountInCents * 10_000);
         }
      }

      if (computedCredits !== declaredTotal || computedDebits !== declaredTotal) {
         logger.error(`[Sync API] TENTATIVE DE FRAUDE NF525 DÉTECTÉE (Tenant: ${tenantId}). Totaux incohérents. Déclaré: ${declaredTotal}, Crédits: ${computedCredits}, Débits: ${computedDebits}`);
         // Rejeter le ticket et déclencher potentiellement un Sovereign Lockout
         return NextResponse.json({ error: 'NF525 Integrity Breach: Amounts mismatch' }, { status: 403 });
      }

      const sealedEntry = {
        ...entry,
        pieceNumber: receiptNumber,
        isValidated: true,
        status: 'validated',
      } as JsonObject & { id: string };

      const dataSnapshot = CryptoService.canonicalStringify({
        id: entry.id,
        receiptNumber,
        operatorId: 'OFFLINE_SYNC', // On pourrait récupérer l'opérateur d'origine
        tableId: entry.referenceId,
        totalTTCInMicrounits: entry.totalInMicrounits ?? (entry.amountInCents ?? 0) * 10_000,
        timestamp: entry.date,
      });

      const { hash, sealId } = await FiscalSealer.sealDataAtomically(
        dataSnapshot,
        tenantId,
        isTrainingMode,
        sealedEntry
      );

      sealedEntries.push({ id: entry.id, receiptNumber, sealId, hash });
    }

    logger.info(`[Sync API] Synchro réussie pour ${sealedEntries.length} tickets.`);
    return NextResponse.json({ success: true, sealedEntries });
  } catch (error) {
    logger.error('[Sync API] Erreur lors de la synchronisation', { error: toError(error).message });
    return NextResponse.json({ error: 'Erreur interne de synchronisation' }, { status: 500 });
  }
}

/**
 * Acompte privatisation/groupe — res-14
 *
 * Crée une session Stripe Checkout pour collecter un acompte sur
 * une réservation de privatisation ou de groupe.
 * L'acompte encaissé crée automatiquement un JournalEntry + FiscalSeal NF525.
 *
 * POST /api/reservations/deposit/create
 *   Body: { reservationId: string; amountInMicrounits: number; description?: string }
 *   Retourne: { sessionId: string; checkoutUrl: string }
 *
 * POST /api/reservations/deposit/confirm (webhook Stripe)
 *   Vérifie HMAC, crée JournalEntry + FiscalSeal si checkout.session.completed
 *
 * Protégé : requireTenantAdmin pour create. Webhook = signature Stripe.
 */
import { NextRequest, NextResponse } from 'next/server';
import { requireTenantAdmin, isDenied } from '@/lib/server/adminAuthGuard';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { FiscalEngine } from '@/modules/finance/fiscalite/FiscalAdapter';
import { CryptoService } from '@/lib/CryptoService';
import { logger } from '@/lib/logger';
import Stripe from 'stripe';
import type { FiscalSeal } from '@nexus/contracts';
import { toError } from "@/lib/toError";

const MICROUNITS_PER_CENT = 10; // 1 microunit = 0.000001€, 1 cent = 0.01€ = 10 000 µ

export async function POST(req: NextRequest): Promise<NextResponse> {
  const action = req.nextUrl.searchParams.get('action');

  if (action === 'confirm') {
    return handleStripeWebhook(req);
  }

  // Create checkout session
  const caller = await requireTenantAdmin(req);
  if (isDenied(caller)) return caller as NextResponse;
  const { tenantId } = caller as { tenantId: string };

  let body: { reservationId: string; amountInMicrounits: number; description?: string };
  try {
    body = await req.json() as typeof body;
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 });
  }

  const { reservationId, amountInMicrounits, description = 'Acompte privatisation' } = body;
  if (!reservationId || !amountInMicrounits) {
    return NextResponse.json({ error: 'reservationId et amountInMicrounits requis' }, { status: 400 });
  }

  const stripeKey = process.env.STRIPE_SECRET_KEY;
  if (!stripeKey) {
    return NextResponse.json({ error: 'STRIPE_SECRET_KEY non configuré' }, { status: 503 });
  }

  const stripe     = new Stripe(stripeKey, { apiVersion: '2026-06-24.dahlia' });
  const amountCents = Math.round(amountInMicrounits / MICROUNITS_PER_CENT);
  const appUrl     = process.env.NEXT_PUBLIC_APP_URL ?? 'https://app.restaurantos.app';

  const session = await stripe.checkout.sessions.create({
    mode:        'payment',
    line_items:  [{
      price_data: {
        currency:     'eur',
        unit_amount:  amountCents,
        product_data: { name: description },
      },
      quantity: 1,
    }],
    success_url: `${appUrl}/reservations/${reservationId}?deposit=success`,
    cancel_url:  `${appUrl}/reservations/${reservationId}?deposit=cancelled`,
    metadata:    { tenantId, reservationId, amountInMicrounits: String(amountInMicrounits) },
  });

  await Nexus.adapter.set(`tenants/${tenantId}/reservations/${reservationId}`, {
    depositStatus:   'pending',
    depositSessionId: session.id,
    depositAmountInMicrounits: amountInMicrounits,
  }, { merge: true });

  logger.info(`[Deposit] Session Stripe ${session.id} créée pour réservation ${reservationId}`);
  return NextResponse.json({ sessionId: session.id, checkoutUrl: session.url });
}

async function handleStripeWebhook(req: NextRequest): Promise<NextResponse> {
  const stripeKey    = process.env.STRIPE_SECRET_KEY;
  const webhookSecret = process.env.STRIPE_DEPOSIT_WEBHOOK_SECRET;

  if (!stripeKey || !webhookSecret) {
    return NextResponse.json({ error: 'Stripe non configuré' }, { status: 503 });
  }

  const rawBody  = await req.text();
  const signature = req.headers.get('stripe-signature') ?? '';

  let event: Stripe.Event;
  try {
    const stripe = new Stripe(stripeKey, { apiVersion: '2026-06-24.dahlia' });
    event = stripe.webhooks.constructEvent(rawBody, signature, webhookSecret);
  } catch (err) {
    logger.warn(`[Deposit/webhook] Signature invalide: ${toError(err).message}`);
    return NextResponse.json({ error: 'Signature invalide' }, { status: 401 });
  }

  if (event.type === 'checkout.session.completed') {
    const session  = event.data.object as Stripe.Checkout.Session;
    const tenantId = session.metadata?.tenantId;
    const reservationId = session.metadata?.reservationId;
    const amountInMicrounits = Number(session.metadata?.amountInMicrounits ?? 0);

    if (!tenantId || !reservationId) {
      return NextResponse.json({ received: true });
    }

    // JournalEntry NF525
    const jeId = Nexus.adapter.generateId(`tenants/${tenantId}/journalEntries`);
    const journalEntry = {
      id:              jeId,
      date:            new Date().toISOString().slice(0, 10),
      label:           `Acompte privatisation — réservation ${reservationId}`,
      amountInMicrounits,
      type:            'credit' as const,
      pcgAccount:      '4119',
      pcgLabel:        'Acomptes reçus clients',
      source:          'stripe_deposit' as const,
      stripeSessionId: session.id,
      reservationId,
      createdAt:       new Date().toISOString(),
    };

    const existingSeals = await Nexus.adapter.query<FiscalSeal>(`tenants/${tenantId}/fiscalSeals`);
    const lastSeal = existingSeals.sort((a, b) =>
      new Date(b.timestamp ?? 0).getTime() - new Date(a.timestamp ?? 0).getTime()
    )[0];

    const dataSnapshot = CryptoService.canonicalStringify(
      journalEntry
    );
    const seal = await FiscalEngine.sealEntry(
      jeId,
      journalEntry as Record<string, string | number | boolean | null | undefined | object>,
      { lastSeal }
    );

    const batch = Nexus.adapter.batch();
    batch.set(`tenants/${tenantId}/journalEntries/${jeId}`, journalEntry);
    batch.set(`tenants/${tenantId}/fiscalSeals/${seal.id}`, { ...seal, dataSnapshot });
    batch.set(`tenants/${tenantId}/reservations/${reservationId}`, {
      depositStatus:   'paid',
      depositPaidAt:   new Date().toISOString(),
      depositJournalEntryId: jeId,
    });
    await batch.commit();

    logger.info(`[Deposit] Acompte encaissé → JournalEntry ${jeId} + FiscalSeal ${seal.id}`);
  }

  return NextResponse.json({ received: true });
}

/**
 * Reservations API — res-arch-1 : Architecture biface
 *
 * Surface BACKOFFICE (employés) :
 *   GET  /api/reservations?date=YYYY-MM-DD  — liste jour (requireTenantUser)
 *   POST /api/reservations                  — création interne (requireTenantUser)
 *   PATCH /api/reservations?id=xxx          — mise à jour statut/table (requireTenantUser)
 *
 * Surface WIDGET PUBLIC :
 *   POST /api/widget/book         — réservation client externe (sans auth)
 *   GET  /api/widget/availability — créneaux libres (sans auth)
 *
 * Cette route gère la surface interne (backoffice).
 * La surface publique est dans /api/widget/* (rate-limitée, sans auth).
 *
 * Règles :
 *   - jamais de cross-tenant : tenantId TOUJOURS depuis le token
 *   - statuts valides : 'pending' | 'confirmed' | 'arrived' | 'completed' | 'cancelled' | 'no_show'
 */
import { NextRequest, NextResponse } from 'next/server';
import { z } from 'zod';
import { requireTenantUser, isDenied } from '@/lib/server/adminAuthGuard';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/logger';

type ReservationStatus = 'pending' | 'confirmed' | 'arrived' | 'completed' | 'cancelled' | 'no_show';
const VALID_STATUSES: ReservationStatus[] = ['pending', 'confirmed', 'arrived', 'completed', 'cancelled', 'no_show'];

const CreateReservationSchema = z.object({
  date:         z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'Format YYYY-MM-DD requis'),
  time:         z.string().regex(/^\d{2}:\d{2}$/, 'Format HH:MM requis'),
  covers:       z.number().int().min(1).max(200),
  customerName: z.string().min(1).max(100).trim(),
  phone:        z.string().max(30).optional(),
  email:        z.string().email().max(254).optional(),
  notes:        z.string().max(500).optional(),
  tableId:      z.string().max(80).optional(),
});

const PatchReservationSchema = z.object({
  status:  z.enum(['pending', 'confirmed', 'arrived', 'completed', 'cancelled', 'no_show']).optional(),
  tableId: z.string().max(80).optional(),
  notes:   z.string().max(500).optional(),
});

export async function GET(req: NextRequest): Promise<NextResponse> {
  const caller = await requireTenantUser(req);
  if (isDenied(caller)) return caller as NextResponse;
  const { tenantId } = caller as { tenantId: string };

  const date = req.nextUrl.searchParams.get('date');

  const all = await Nexus.adapter.query(`tenants/${tenantId}/reservations`) as Array<{ date?: string }>;
  const filtered = date ? all.filter(r => r.date === date) : all;

  return NextResponse.json({ reservations: filtered, date: date ?? 'all', total: filtered.length });
}

export async function POST(req: NextRequest): Promise<NextResponse> {
  const caller = await requireTenantUser(req);
  if (isDenied(caller)) return caller as NextResponse;
  const { tenantId } = caller as { tenantId: string };

  const raw = await req.json().catch(() => null);
  const parsed = CreateReservationSchema.safeParse(raw);
  if (!parsed.success) {
    return NextResponse.json({ error: 'Données invalides', details: parsed.error.flatten() }, { status: 400 });
  }
  const { date, time, covers, customerName, phone, email, notes, tableId } = parsed.data;

  const id = Nexus.adapter.generateId(`tenants/${tenantId}/reservations`);
  const reservation = {
    id,
    date,
    time,
    covers,
    customerName,
    ...(phone   ? { phone }   : {}),
    ...(email   ? { email }   : {}),
    ...(notes   ? { notes }   : {}),
    ...(tableId ? { tableId } : {}),
    status:        'confirmed' as ReservationStatus,
    source:        'backoffice',
    schemaVersion: 2,
    createdAt:     new Date().toISOString(),
    updatedAt:     Date.now(),
  };

  await Nexus.adapter.set(`tenants/${tenantId}/reservations/${id}`, reservation);

  logger.info(`[Reservations] Réservation backoffice ${id} créée — ${customerName} le ${date}`);
  return NextResponse.json({ success: true, reservation });
}

export async function PATCH(req: NextRequest): Promise<NextResponse> {
  const caller = await requireTenantUser(req);
  if (isDenied(caller)) return caller as NextResponse;
  const { tenantId } = caller as { tenantId: string };

  const id = req.nextUrl.searchParams.get('id');
  if (!id) return NextResponse.json({ error: 'id requis' }, { status: 400 });

  const rawPatch = await req.json().catch(() => null);
  const patchParsed = PatchReservationSchema.safeParse(rawPatch);
  if (!patchParsed.success) {
    return NextResponse.json({ error: 'Données invalides', details: patchParsed.error.flatten() }, { status: 400 });
  }
  const { status, tableId, notes } = patchParsed.data;

  const update: Record<string, unknown> = { updatedAt: Date.now() };
  if (status  !== undefined) update.status  = status;
  if (tableId !== undefined) update.tableId = tableId;
  if (notes   !== undefined) update.notes   = notes;

  await Nexus.adapter.set(`tenants/${tenantId}/reservations/${id}`, update, { merge: true });

  logger.info(`[Reservations] Réservation ${id} mise à jour — status: ${status ?? 'inchangé'}`);
  return NextResponse.json({ success: true, id, updated: patchParsed.data });
}

import 'server-only';
import { NextRequest, NextResponse } from 'next/server';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { createHash } from 'node:crypto';
import jwt from 'jsonwebtoken';
import { getRateLimiter } from '@/infrastructure/services/rate-limiter';
import { logger } from '@/lib/logger';

function hashKey(key: string): string {
  return createHash('sha256').update(key).digest('hex');
}

interface StoredApiKey {
  id: string;
  keyHash: string;
  permissions: string[];
  revokedAt: string | null;
}

export async function POST(req: NextRequest): Promise<NextResponse> {
  // Rate-limit par IP — 20 tentatives / 15 min pour contrer le brute-force
  const ip = req.headers.get('x-forwarded-for') ?? req.headers.get('x-real-ip') ?? 'unknown';
  const rl = await getRateLimiter().check(`api-key-validate:${ip}`, 20, 15 * 60 * 1000);
  if (!rl.allowed) {
    logger.warn(`[api-keys/validate] Rate limit dépassé ip=${ip}`);
    return NextResponse.json({ error: 'Trop de tentatives — réessayez dans 15 min.' }, { status: 429 });
  }

  const body = await req.json().catch(() => null) as { key?: string } | null;
  if (!body?.key) {
    return NextResponse.json({ error: 'key requis' }, { status: 400 });
  }

  const tokenString = body.key.startsWith('ros_') ? body.key.slice(4) : body.key;
  let tenantId: string;
  try {
    const secret = process.env.INTERNAL_API_SECRET;
    if (!secret) {
      logger.error('[api-keys/validate] INTERNAL_API_SECRET non configuré — refus de validation');
      return NextResponse.json({ error: 'Configuration serveur manquante' }, { status: 500 });
    }
    const decoded = jwt.verify(tokenString, secret) as { tenantId: string };
    if (!decoded.tenantId) throw new Error('No tenantId in JWT');
    tenantId = decoded.tenantId;
  } catch (err) {
    logger.warn(`[api-keys/validate] Clé invalide ou falsifiée`);
    return NextResponse.json({ valid: false }, { status: 401 });
  }

  const hash = hashKey(body.key);
  const all = await Nexus.adapter.query<StoredApiKey>(`tenants/${tenantId}/apiKeys`);
  const match = all.find(k => k.keyHash === hash && !k.revokedAt);

  if (!match) return NextResponse.json({ valid: false }, { status: 401 });

  await Nexus.adapter.set(
    `tenants/${tenantId}/apiKeys/${match.id}`,
    { lastUsedAt: new Date().toISOString() },
    { merge: true },
  );

  return NextResponse.json({ valid: true, permissions: match.permissions ?? [] });
}

/**
 * POST /api/tenant/onboarding/connector/pull
 * Body: { provider: ConnectorId, category: ImportCategory, credentials: ConnectorCredentials }
 * → Pull les données depuis le concurrent et retourne un ParsedFile compatible.
 *
 * Note : les credentials ne sont JAMAIS persistés côté serveur ici.
 * Ils transitent uniquement en mémoire pour le pull.
 */
import { NextRequest, NextResponse } from 'next/server';
import { requireTenantUser, isDenied } from '@/lib/server/adminAuthGuard';
import { logger } from '@/lib/logger';
import { ConnectorRegistry } from '@/modules/commerce/acquisition/onboarding/migration/connectors/ConnectorRegistry';
import { runImporter } from '@/modules/commerce/acquisition/onboarding/migration/importers';
import type { ConnectorId, ConnectorCredentials } from '@/modules/commerce/acquisition/onboarding/migration/connectors/types';
import type { ImportCategory } from '@/modules/commerce/acquisition/onboarding/migration/types';
import { toError } from "@/lib/toError";

export async function POST(req: NextRequest) {
    const caller = await requireTenantUser(req);
    if (isDenied(caller)) return caller;

    try {
        const { provider, category, credentials, autoImport } = await req.json() as {
            provider:    ConnectorId;
            category:    ImportCategory;
            credentials: ConnectorCredentials;
            autoImport?: boolean;
        };

        if (!provider || !category || !credentials) {
            return NextResponse.json({ error: 'provider, category et credentials sont requis' }, { status: 400 });
        }

        logger.info('[onboarding/connector/pull]', { tenantId: caller.tenantId, provider, category });

        const connector = ConnectorRegistry.get(provider);
        const parsedFile = await connector.pull(category, credentials);

        // Mode preview (défaut) : retourne les données sans importer
        if (!autoImport) {
            return NextResponse.json({
                ok: true,
                preview: {
                    headers:  parsedFile.headers,
                    rowCount: parsedFile.rows.length,
                    sample:   parsedFile.rows.slice(0, 5),
                    source:   parsedFile.source,
                    warnings: parsedFile.warnings,
                },
            });
        }

        // Mode autoImport : injecte directement en DB
        const rawFile = new File(
            [JSON.stringify(parsedFile.rows)],
            `${provider}-${category}.json`,
            { type: 'application/json' },
        );

        const progress: number[] = [];
        const result = await runImporter(category, parsedFile, rawFile, p => progress.push(p));

        return NextResponse.json({ ok: true, result });
    } catch (err) {
        logger.error('[onboarding/connector/pull]', err);
        return NextResponse.json({ ok: false, error: toError(err).message }, { status: 500 });
    }
}

