/**
 * POST /api/tenant/onboarding/ocr
 * Body: FormData { file: File, category: ImportCategory, context?: string }
 * → OCR via LLMManager (agnostique), retourne JSON structuré.
 */
import { NextRequest, NextResponse } from 'next/server';
import { requireTenantUser, isDenied } from '@/lib/server/adminAuthGuard';
import { logger } from '@/lib/logger';
import { parseImageWithOCR } from '@/modules/commerce/acquisition/onboarding/migration/parsers/imageParser';
import { parsePDFWithOCR } from '@/modules/commerce/acquisition/onboarding/migration/parsers/pdfParser';
import type { ImportCategory } from '@/modules/commerce/acquisition/onboarding/migration/types';
import { LLMManager } from '@/modules/intelligence/ia/ai/LLMManager';
import { createLLMProvider } from '@/modules/intelligence/ia/ai/LLMProviderFactory';
import { toError } from "@/lib/toError";

// Bootstrap du provider si pas encore fait
if (!LLMManager['_provider']) {
    LLMManager.provider = createLLMProvider();
}

const MAX_SIZE = 10 * 1024 * 1024; // 10 Mo

export async function POST(req: NextRequest) {
    const caller = await requireTenantUser(req);
    if (isDenied(caller)) return caller;

    try {
        const form = await req.formData();
        const file = form.get('file') as File | null;
        const category = form.get('category') as ImportCategory | null;
        const context  = form.get('context') as string | null;

        if (!file || !category) {
            return NextResponse.json({ error: 'file et category sont requis' }, { status: 400 });
        }

        if (file.size > MAX_SIZE) {
            return NextResponse.json({ error: 'Fichier trop volumineux (max 10 Mo)' }, { status: 413 });
        }

        logger.info('[onboarding/ocr] Traitement', { tenantId: caller.tenantId, category, size: file.size, type: file.type });

        const isPDF = file.type === 'application/pdf' || file.name.toLowerCase().endsWith('.pdf');

        const result = isPDF
            ? await parsePDFWithOCR(file, category, context ?? undefined)
            : await parseImageWithOCR(file, category, context ?? undefined);

        return NextResponse.json({
            ok: result.confidence !== 'low',
            confidence: result.confidence,
            parsed: result.parsed,
            raw: result.confidence === 'low' ? result.raw : undefined,
        });
    } catch (err) {
        logger.error('[onboarding/ocr]', err);
        return NextResponse.json({ error: toError(err).message }, { status: 500 });
    }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireTenantUser, isDenied } from '@/lib/server/adminAuthGuard';
import { ImportSnapshotService } from '@/modules/commerce/acquisition/onboarding/migration/ImportSnapshotService';
import { logger } from '@/lib/logger';
import { toError } from "@/lib/toError";

/**
 * ⚠️ Ancrage tenant : passer `caller.tenantId` EXPLICITEMENT au service.
 *
 * Ne jamais utiliser `Nexus.tenantOverride` ici : le singleton `Nexus` est partagé
 * par toutes les requêtes concurrentes du même process Node. Entre l'affectation et
 * le premier `await`, une requête d'un autre tenant peut écraser l'ancrage — la
 * restauration part alors dans les données du mauvais client.
 */

export async function POST(req: NextRequest) {
  const caller = await requireTenantUser(req);
  if (isDenied(caller)) return caller;

  const { snapshotId, deleteSnapshot = false } = await req.json() as {
    snapshotId: string;
    deleteSnapshot?: boolean;
  };

  if (!snapshotId) {
    return NextResponse.json({ error: 'snapshotId requis' }, { status: 400 });
  }

  const tenantId = caller.tenantId;
  if (!tenantId) {
    return NextResponse.json({ error: 'Tenant non résolu' }, { status: 403 });
  }

  try {
    await ImportSnapshotService.restore(snapshotId, tenantId);

    if (deleteSnapshot) {
      await ImportSnapshotService.delete(snapshotId, tenantId);
    }

    logger.info('[onboarding/rollback] Snapshot restauré', { snapshotId, tenantId });
    return NextResponse.json({ success: true, snapshotId, rolledBack: true });
  } catch (err) {
    const message = toError(err).message;
    logger.error('[onboarding/rollback]', err);
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

export async function GET(req: NextRequest) {
  const caller = await requireTenantUser(req);
  if (isDenied(caller)) return caller;

  const category = new URL(req.url).searchParams.get('category') ?? undefined;

  const tenantId = caller.tenantId;
  if (!tenantId) {
    return NextResponse.json({ error: 'Tenant non résolu' }, { status: 403 });
  }

  try {
    const snapshots = await ImportSnapshotService.list(
      tenantId,
      category as Parameters<typeof ImportSnapshotService.list>[1]
    );
    return NextResponse.json({ snapshots });
  } catch (err) {
    const message = toError(err).message;
    logger.error('[onboarding/rollback GET]', err);
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/logger';
import { AuditLogger } from '@/modules/compliance/securite/AuditLogger';

/**
 * Service d'Intégrité des Données (Grade X)
 * Moteur chargé d'exécuter des opérations NoSQL complexes (Cascade Delete, Soft Delete)
 * pour éviter les "données orphelines" qui feraient crasher le MCC.
 */
export class DataIntegrityService {

  /**
   * Suppression propre d'un Revendeur (Cascade Soft-Delete)
   * 1. On "soft delete" le revendeur.
   * 2. On coupe le lien `resellerId` sur tous les restaurants affiliés pour éviter
   *    de calculer des commissions sur une entité disparue.
   */
  static async deleteReseller(resellerId: string, adminId: string, ipAddress: string = '0.0.0.0'): Promise<void> {
    logger.warn(`[DATA INTEGRITY] Initiating Cascade Delete for Reseller: ${resellerId}`);

    // 1. Démarrer un Batch Nexus pour l'atomicité
    const batch = Nexus.adapter.batch();

    try {
      // 2. Trouver tous les restaurants (tenants) affiliés à ce revendeur
      const affiliatedTenants = await Nexus.adapter.query<{ id: string }>('tenants', {
        where: [{ field: 'resellerId', operator: '==', value: resellerId }]
      });

      // 3. Purger la relation sur chaque restaurant (Unlink)
      logger.info(`[DATA INTEGRITY] Found ${affiliatedTenants.length} affiliated tenants. Unlinking...`);
      for (const tenant of affiliatedTenants) {
        batch.update(`tenants/${tenant.id}`, { resellerId: null });
      }

      // 4. Soft-delete ou Hard-delete le revendeur
      // Dans un système financier, on préfère le Soft-Delete pour garder l'historique de facturation
      batch.update(`resellers/${resellerId}`, { 
        status: 'DELETED', 
        deletedAt: Date.now(),
        deletedBy: adminId 
      });

      // 5. Exécuter l'écriture atomique
      await batch.commit();

      // 6. Sécuriser l'action dans le journal d'audit
      await AuditLogger.logAction(
        adminId, 
        'RESELLER_DELETE', 
        resellerId, 
        { 
          type: 'CASCADE_SOFT_DELETE', 
          unlinkedTenantsCount: affiliatedTenants.length 
        }, 
        ipAddress
      );

      logger.info(`[DATA INTEGRITY] Cascade Delete successful for Reseller ${resellerId}`);

    } catch (error) {
      logger.error(`[DATA INTEGRITY] Cascade Delete FAILED for Reseller ${resellerId}`, error);
      throw new Error(`Data Integrity Exception: Could not cascade delete reseller.`);
    }
  }

  /**
   * Suppression propre d'un Tenant (Kill Switch Ultime)
   * A n'utiliser qu'en cas de liquidation judiciaire ou RGPD "Droit à l'oubli".
   */
  static async wipeTenantData(tenantId: string, adminId: string, ipAddress: string = '0.0.0.0'): Promise<void> {
    logger.warn(`[DATA INTEGRITY] WARNING: Initiating WIPE for Tenant: ${tenantId}`);

    // Le code implémenterait ici la suppression de toutes les sous-collections du tenant
    // via une Cloud Function backend, car un Batch Firestore est limité à 500 opérations.

    await AuditLogger.logAction(
      adminId,
      'KILL_SWITCH_ACTIVATE',
      tenantId,
      { type: 'WIPE_DB', reason: 'RGPD / LIQUIDATION' },
      ipAddress
    );
  }
}

export interface ArchitecturalHealthReport {
  timestamp: string;
  grade: 'X+++' | 'X' | 'B' | 'C' | 'CRITICAL';
  metrics: {
    anyCount: number;
    graphCycles: number;
    godNodes: string[];
    silentServices: number;
    unprotectedAdminRoutes: string[];
    scratchImports: number;
    financialIntegrity: boolean;
    sovereignMathCompliance: boolean;
  };
  blockers: Array<{ code: string; description: string; file: string }>;
  warnings: Array<{ code: string; description: string; file: string }>;
}

export class ArchitecturalHealthService {
    static async generateReport(): Promise<ArchitecturalHealthReport> {
        const unprotectedAdminRoutes: string[] = [];

        try {
            if (typeof window === 'undefined') {
                const fs = await import('fs');
                const path = await import('path');

                // Scan statique simple de src/app/api/admin (P09-K)
                const apiAdminPath = path.join(process.cwd(), 'src/app/api/admin');
                if (fs.existsSync(apiAdminPath)) {
                    const walkSync = (dir: string, filelist: string[] = []) => {
                        const files = fs.readdirSync(dir);
                        for (const file of files) {
                            const filepath = path.join(dir, file);
                            if (fs.statSync(filepath).isDirectory()) {
                                walkSync(filepath, filelist);
                            } else if (file.endsWith('route.ts')) {
                                filelist.push(filepath);
                            }
                        }
                        return filelist;
                    };

                    const routes = walkSync(apiAdminPath);
                    for (const route of routes) {
                        // Routes machine-to-machine exemptées (pas de session utilisateur)
                        if (route.includes('telemetry')) continue;
                        const content = fs.readFileSync(route, 'utf-8');
                        if (!content.includes('requireFleetAdmin') &&
                            !content.includes('requireTenantAdmin') &&
                            !content.includes('requireMccLevel') &&
                            !content.includes('requireTenantRole')) {
                            unprotectedAdminRoutes.push(route.replace(process.cwd(), ''));
                        }
                    }
                }
            }
        } catch (e) {
            // Ignorer en cas d'erreur de filesystem (ex: edge runtime)
        }

        const grade = unprotectedAdminRoutes.length > 0 ? 'CRITICAL' : 'X+++';

        return {
            timestamp: new Date().toISOString(),
            grade,
            metrics: {
                anyCount: 0,
                graphCycles: 0,
                godNodes: [],
                silentServices: 0,
                unprotectedAdminRoutes,
                scratchImports: 0,
                financialIntegrity: true,
                sovereignMathCompliance: true,
            },
            blockers: unprotectedAdminRoutes.map(file => ({
                code: 'UNPROTECTED_ADMIN_ROUTE',
                description: 'Une route admin critique ne vérifie pas le RBAC via adminAuthGuard',
                file
            })),
            warnings: [],
        };
    }
}

