/**
 * 🤖 MaintenanceAgent - Restaurant OS
 * Gère l'automatisation du support technique et de la maintenance flotte.
 * Grade VI: Industrialized Security & Support.
 */
export const MaintenanceAgent = {
    /**
     * 1. SIGNALEMENT (Submit SOS)
     */
    async submitSOS(ticket: Omit<MaintenanceTicket, 'status' | 'createdAt' | 'updatedAt' | 'priority' | 'id'>): Promise<string> {
        try {
            const ticketId = Math.random().toString(36).substring(2, 12) + Math.random().toString(36).substring(2, 12);

            // Calcul automatique de la priorité
            let priority: MaintenanceTicket['priority'] = 'medium';
            if (ticket.type === 'CRITICAL_BUG') priority = 'critical';
            else if (ticket.type === 'DATA_INCONSISTENCY') priority = 'high';
            else if (ticket.type === 'PERFORMANCE') priority = 'medium';
            else priority = 'low';

            const now = new Date().toISOString();
            const data: MaintenanceTicket = {
                ...ticket,
                id: ticketId,
                status: 'pending',
                priority,
                createdAt: now,
                updatedAt: now,
            };

            await Nexus.adapter.set(`maintenanceTickets/${ticketId}`, data);

            logger.info('MaintenanceAgent: [Step 1] SOS Ticket signals', { 
                ticketId, 
                domain: ticket.pageKey,
                type: ticket.type 
            });

            // Lancement immédiat de la contextualisation
            this.runAutoMaintenance(ticketId, data);

            return ticketId;
        } catch (error) {
            logger.error('MaintenanceAgent: SOS submission failed', { error: toError(error).message });
            throw error;
        }
    },

    /**
     * ORCHESTRATEUR CENTRAL (Steps 2 to 8)
     */
    async runAutoMaintenance(ticketId: string, ticketData: MaintenanceTicket) {
        try {
            // 2. CONTEXTUALISATION
            logger.info('MaintenanceAgent: [Step 2] Collecting system context', { ticketId, domain: ticketData.pageKey });
            const context: MaintenanceTicketContext = {
                route: ticketData.systemState.currentRoute,
                domain: ticketData.pageKey || 'Universal',
                logs: ticketData.logs.slice(-50), // Plus de logs pour l'analyse
                tenant: ticketData.tenantId,
                activeModules: ticketData.systemState.activeModules
            };

            // 3. DIAGNOSTIC & 4. PROPOSITION PR
            logger.info('MaintenanceAgent: [Step 3-4] AI Diagnosis & PR Generation', { ticketId });
            const analysis = await this.analyzeWithAI(ticketData, context);

            // 5. VALIDATION (Prêt pour revue Admin dans le MCC)
            await Nexus.adapter.update(`maintenanceTickets/${ticketId}`, {
                status: 'pr_ready',
                aiAnalysis: analysis,
                updatedAt: new Date().toISOString(),
            });
            logger.info('MaintenanceAgent: [Step 5] PR Ready for Admin Review', { ticketId, diagnostic: analysis.summary });

            // Note: Steps 6 & 7 (Application & Vérification) sont manuelles/semi-auto via l'UI.
        } catch (error) {
            logger.error('MaintenanceAgent: Maintenance cycle failed', { ticketId, error: toError(error).message });
        }
    },

    /**
     * AI CORE : Analyse Gemini Pro avec Injection d'ADN
     */
    async analyzeWithAI(ticket: MaintenanceTicket, context: MaintenanceTicketContext): Promise<MaintenanceAIAnalysis> {
        const tenantDNA = await DNAInjector.getTenantDNA(ticket.tenantId);

        const userPrompt = `
            === CLIENT DNA (Rules to respect) ===
            ${tenantDNA}

            === MAINTENANCE REQUEST ===
            - Ticket ID: ${ticket.id}
            - Domain/Module: ${ticket.pageKey || 'Universal'}
            - Issue: ${ticket.description}
            - Type: ${ticket.type}
            - Technical Context: ${JSON.stringify(context)}

            === TASK ===
            1. Identify root cause in the module "${ticket.pageKey || 'Universal'}".
            2. Provide a code fix OR a configuration change suggestion.
            3. Ensure compliance with NF525 and the client's DNA rules.
            4. If it's a UI glitch, specify components to check.

            Return JSON format only:
            {
                "summary": "Short explanation",
                "potentialCause": "Technical depth",
                "affectedFiles": ["src/app/..."],
                "proposedFix": "diff or instruction",
                "domainConfig": {} // Optional suggested config update
            }
        `;

        const response = await LLMManager.provider.generateText({
            model: AI_MODELS.fast,
            systemPrompt: 'You are the Senior SRE for Restaurant OS Empire.',
            userPrompt,
            responseMimeType: 'application/json',
        });
        const text = response.text;

        // Nettoyage JSON strict
        const jsonMatch = text.match(/\{[\s\S]*\}/);
        if (!jsonMatch) {
            return { 
                summary: "Analyse brute (Echec parsing JSON)", 
                potentialCause: "Analysis engine fallback", 
                affectedFiles: [], 
                proposedFix: text 
            };
        }

        try {
            const analysis: MaintenanceAIAnalysis = JSON.parse(jsonMatch[0]);
            return analysis;
        } catch (_e) {
            return { 
                summary: "Erreur de formatage AI", 
                potentialCause: "JSON Parse Error", 
                affectedFiles: [], 
                proposedFix: text 
            };
        }
    },

    /**
     * 8. NOTIFICATION (Simple Log Final)
     */
    async finalizeTicket(ticketId: string, resolution: string) {
        logger.info(`🏛️ [EMPIRE NOTIFICATION] Ticket ${ticketId} résolu.`, { resolution });
    }
};

/**
 * 🛰️ NexusTelemetryService - The OS Mirror
 * Responsible for sending real-time health pulses to the Suzerain (MCC).
 * Grade VI - Certified Reliability.
 */

import { TelemetryPulse } from "@shared/nexus-contract";
import { whiteLabelInstanceConfig } from "@/config/instance";
import { logger } from "@/lib/logger";
import { fleetTelemetry } from "@/modules/intelligence/ia/fleet/FleetTelemetryService";
import { registerAuditPulseSink } from "@/shared/nexus/telemetry/NexusTelemetryService";
import type { SiteTelemetry } from "@/shared/nexus/contracts/fleet.types";
import { tenantScopedKey } from "@/lib/storage/tenantScopedKey";
import { JsonObject } from "@/shared/types/json";

class TelemetryService {
  private intervalId: NodeJS.Timeout | null = null;
  private readonly PULSE_INTERVAL = 5 * 60 * 1000; // 5 minutes

  /**
   * Starts the rhythmic heartbeat of the Vassal.
   */
  public start(tenantId: string) {
    if (this.intervalId) return;

    // Initial pulse
    this.sendPulse(tenantId);

    // Schedule subsequent pulses
    this.intervalId = setInterval(() => {
      this.sendPulse(tenantId);
    }, this.PULSE_INTERVAL);

    logger.info(`[NexusTelemetry] Heartbeat activated for tenant: ${tenantId}`);
  }

  /**
   * Stops the pulse.
   */
  public stop() {
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = null;
    }
  }

  /**
   * Collects current system telemetry and mirrors it to the Suzerain.
   */

  /**
   * 🖋️ Suture GRADE X+++: Emission d'Audit Pulse
   */
  public emitAuditPulse(pillar: string, action: string, data: object) {
      logger.debug(`[AuditPulse|${pillar}] ${action}`, data as JsonObject);
      // Implémentation réelle vers le MCC
  }

  private async sendPulse(tenantId: string) {
    try {
      const pulse: TelemetryPulse = await this.collectPulse();

      // Inclure l'état du RAG local dans le pulse (fire-and-forget sans bloquer).
      let ragStatus: SiteTelemetry['ragStatus'] | undefined;
      try {
        const res = await fetch('/api/health/rag', { signal: AbortSignal.timeout(4_000) });
        if (res.ok) {
          const h = await res.json() as { status: string; version?: string; document_count?: number; last_indexed?: string; latencyMs?: number };
          ragStatus = {
            status: h.status as NonNullable<SiteTelemetry['ragStatus']>['status'],
            version: h.version,
            documentCount: h.document_count,
            lastIndexed: h.last_indexed,
            latencyMs: h.latencyMs,
          };
        }
      } catch { /* RAG indisponible — on continue sans bloquer */ }

      // 1. Persist local for quick reads (existing behavior)
      localStorage.setItem(tenantScopedKey('nexus_last_pulse'), JSON.stringify({
        timestamp: Date.now(),
        status: pulse.status,
        ragStatus,
      }));

      // 2. Push to Nexus fleet-telemetry so the MCC can see this instance's RAG status.
      await fleetTelemetry.pushSiteTelemetry(tenantId as import('@/shared/types/brands').TenantID, {
        status: pulse.status === 'ACTIVE' ? 'ONLINE' : 'OFFLINE',
        lastHeartbeat: pulse.lastPulse,
        ...(ragStatus ? { ragStatus } : {}),
      } as Partial<SiteTelemetry>);

      logger.debug(`[NexusTelemetry] Pulse emitted at ${pulse.lastPulse}`, { tenantId, rag: ragStatus?.status ?? 'unknown' });

    } catch (error) {
      console.error("[NexusTelemetry] Pulse failure:", error);
    }
  }

  private async collectPulse(): Promise<TelemetryPulse> {
    const battery = await this.getBatteryInfo();
    const network = this.getNetworkInfo();

    return {
      version: whiteLabelInstanceConfig.version || "1.0.0",
      status: 'ACTIVE', // Dynamic status based on error store in real app
      lastPulse: new Date().toISOString(),
      health: {
        uptime: performance.now(),
        battery,
        network
      },
      security: {
        nf525Sealed: true, // Placeholder for real seal status
        integrityGrade: "VI"
      }
    };
  }

  private async getBatteryInfo() {
    try {
      if ('getBattery' in navigator) {
        const bat = await (navigator as Navigator & { getBattery: () => Promise<{ level: number, charging: boolean }> }).getBattery();
        return {
          level: bat.level,
          charging: bat.charging,
          supported: true
        };
      }
    } catch (_e) {}

    return {
      level: 1,
      charging: true,
      supported: false
    };
  }

  private getNetworkInfo() {
    const nav = navigator as Navigator & { connection?: { effectiveType: string }, mozConnection?: { effectiveType: string }, webkitConnection?: { effectiveType: string } };
    const conn = nav.connection || nav.mozConnection || nav.webkitConnection;
    return {
      online: navigator.onLine,
      effectiveType: conn?.effectiveType || 'unknown'
    };
  }
}

export const NexusTelemetryService = new TelemetryService();

// Inversion de dépendance anti-cycle : le wrapper shared (importé par
// NexusInterceptor) délègue l'émission réelle des audit pulses ici, sans
// jamais importer ce module statiquement.
registerAuditPulseSink((pillar, action, data) =>
    NexusTelemetryService.emitAuditPulse(pillar, action, data),
);

import { logger } from '@/lib/logger';
import { db } from "@/lib/offline/offline-store";
import { Order } from '@nexus/contracts';
import { CryptoService } from '@/lib/CryptoService';
import { ImmunityAuditLogger } from '@/modules/compliance/securite/ImmunityAuditLogger';
import { toError } from "@/lib/toError";

const GENESIS_HASH = '0'.repeat(64);
const INSTANCE_PREFIX_LENGTH = 4;

interface OfflineSeal {
    id: string;
    receiptNumber: string;
    dataSnapshot: string;
    hash: string;
    previousHash: string;
    timestamp: string;
    synced: boolean;
}

export const OfflineMasteryEngine = {
    _instanceId: '',
    _offlineSeqCounter: 0,
    _lastOfflineHash: GENESIS_HASH,

    getInstanceId(): string {
        if (!this._instanceId) {
            this._instanceId = Math.random().toString(36).slice(2, 2 + INSTANCE_PREFIX_LENGTH).toUpperCase();
        }
        return this._instanceId;
    },

    generateOfflineReceiptNumber(): string {
        this._offlineSeqCounter++;
        const year = new Date().getFullYear();
        const seq = String(this._offlineSeqCounter).padStart(6, '0');
        return `${year}-${this.getInstanceId()}-${seq}`;
    },

    async sealOffline(data: Record<string, unknown>): Promise<OfflineSeal> {
        const receiptNumber = this.generateOfflineReceiptNumber();
        const timestamp = new Date().toISOString();

        const dataSnapshot = CryptoService.canonicalStringify({
            ...data,
            receiptNumber,
            timestamp,
            instanceId: this.getInstanceId(),
        } as import("@/shared/nexus-contract").SovereignData);

        const hash = await CryptoService.generateHash(dataSnapshot, this._lastOfflineHash);

        const seal: OfflineSeal = {
            id: `offline-${this.getInstanceId()}-${this._offlineSeqCounter}`,
            receiptNumber,
            dataSnapshot,
            hash,
            previousHash: this._lastOfflineHash,
            timestamp,
            synced: false,
        };

        this._lastOfflineHash = hash;

        await db.syncQueue.add({
            type: 'FISCAL_SEAL',
            action: 'SET',
            collection: 'offlineSeals',
            targetId: seal.id,
            payload: seal as unknown as import('@/shared/nexus-contract').SovereignField,
            status: 'pending',
            timestamp: timestamp,
            priority: 1,
            attempts: 0,
        });

        return seal;
    },

    async bufferTransaction(order: Order) {
        logger.info(`[Offline-Mastery] Buffering Order ${order.id}. Current connectivity: [LOW/NONE]`);
        await db.orders.add(order);

        await this.sealOffline({
            orderId: order.id,
            totalInMicrounits: (order as unknown as { totalInMicrounits?: number }).totalInMicrounits ?? 0,
            operatorId: (order as unknown as { operatorId?: string }).operatorId ?? '',
        });

        ImmunityAuditLogger.logTechnicalEvent({
            eventType: 'power_outage',
            description: `Vente scellée hors-ligne: ${order.id}`,
            deviceId: this.getInstanceId(),
        }).catch(() => {});
    },

    async verifyChainIntegrity(): Promise<{ valid: boolean; brokenAt?: number }> {
        const seals = await db.syncQueue
            .where('collection').equals('offlineSeals')
            .sortBy('timestamp');

        if (seals.length === 0) return { valid: true };

        let expectedPrev = GENESIS_HASH;
        for (let i = 0; i < seals.length; i++) {
            const seal = seals[i].payload as unknown as OfflineSeal;
            if (seal.previousHash !== expectedPrev) {
                logger.error(`[Offline-Mastery] Chain break at seal index ${i}: expected ${expectedPrev}, got ${seal.previousHash}`);
                ImmunityAuditLogger.logTechnicalEvent({
                    eventType: 'chain_break',
                    description: `Rupture de chaîne détectée à l'index ${i}`,
                    deviceId: this.getInstanceId(),
                }).catch(() => {});
                return { valid: false, brokenAt: i };
            }
            expectedPrev = seal.hash;
        }
        return { valid: true };
    },

    async reconcileFleet(tenantId: string): Promise<{ synced: number; failed: number; chainValid: boolean }> {
        logger.info(`[Offline-Mastery] Initiating Mass Reconciliation for ${tenantId}...`);

        const chainCheck = await this.verifyChainIntegrity();

        const pending = await db.syncQueue
            .where('status').equals('pending')
            .sortBy('timestamp');

        if (pending.length === 0) return { synced: 0, failed: 0, chainValid: chainCheck.valid };

        logger.info(`[Offline-Mastery] ${pending.length} operations to synchronize (chain ${chainCheck.valid ? 'OK' : 'BROKEN'}).`);

        let synced = 0;
        let failed = 0;

        for (const op of pending) {
            try {
                await db.syncQueue.update(op.id!, { status: 'syncing' });

                const { Nexus } = await import('@/lib/nexus/NexusAdapter');
                await Nexus.adapter.set(
                    `tenants/${tenantId}/${op.collection}/${op.targetId}`,
                    op.payload
                );

                await db.syncQueue.delete(op.id!);
                synced++;
            } catch (err) {
                const attempts = (op.attempts || 0) + 1;
                const status = attempts >= 3 ? 'failed' : 'pending';
                await db.syncQueue.update(op.id!, {
                    status,
                    attempts,
                    lastError: toError(err).message,
                });
                failed++;
                logger.error(`[Offline-Mastery] Sync failed for ${op.targetId}: ${err}`);
            }
        }

        ImmunityAuditLogger.logTechnicalEvent({
            eventType: 'power_restore',
            description: `Réconciliation terminée: ${synced} sync, ${failed} échoués sur ${pending.length}`,
            deviceId: this.getInstanceId(),
            tenantId,
        }).catch(() => {});

        return { synced, failed, chainValid: chainCheck.valid };
    },
};

import { logger } from '@/lib/logger';
import { empireAudit } from '@/lib/audit';
import { EmpireInstance, ProvisioningDNA } from '@/shared/types/empire';
import { fleetTelemetry } from '@/modules/intelligence';
import { TenantSeeder } from './TenantSeeder';
import { sovereignCreateWorkspace } from '@/modules/intelligence';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { injectBrandingVars } from '@/lib/branding/WhiteLabelBrandingInjector';
import { VerticalRegistry } from '@/shared/plugins/VerticalRegistry';
import { CoreContext } from '@/shared/plugins/CoreContext';
import { TenantRBACConfigSchema } from '@/modules/human';
import { toError } from "@/lib/toError";

/**
 * ProvisioningEngine - Orchestrates the Registry-based "Birth of a Client"
 * This service handles the infrastructure registration and DNA injection.
 */
export const ProvisioningEngine = {
    /**
     * Executes the registration of a new restaurant instance in the Master Registry.
     */
    async provisionNewInstance(dna: ProvisioningDNA): Promise<EmpireInstance> {
        logger.info('ProvisioningEngine: Initializing new Registry entry', { instanceKey: dna.key });

        let registeredInstanceId: string | null = null;

        empireAudit.log({
            module: 'system',
            action: 'REGISTRATION_STARTED',
            details: { name: dna.name, key: dna.key, tier: dna.tier },
            timestamp: new Date()
        });

        try {
            // 0. Slug unicité — collision = écrasement silencieux d'un tenant existant
            const slugExists = await Nexus.adapter.get(`tenants/${dna.key}/tenantConfig`);
            if (slugExists) {
                throw new Error(`SLUG_COLLISION: tenantId "${dna.key}" est déjà utilisé — choisissez un slug différent`);
            }

            // 1. Build the Multi-Tenant Empire Instance (Global Contract)
            const newInstance: EmpireInstance = {
                id: `node_${crypto.randomUUID().replace(/-/g, '').substring(0, 9)}`,
                key: dna.key,
                name: dna.name.toUpperCase(),
                status: 'ONLINE', // Ready for single-core bridge
                tier: dna.tier || 'STANDARD',
                version: '4.5.0-empire',
                createdAt: new Date().toISOString(),
                updatedAt: new Date().toISOString(),
                lastHeartbeat: new Date().toISOString(),

                metrics: {
                    activeUsers: 0,
                    dailyRevenue: 0,
                    revenue24h: 0,
                    aiUsageCost: 0,
                    healthScore: 100,
                    errorRate: 0,
                    uptime: 100,
                    alerts: 0,
                    lowStockAlerts: 0,
                    expiringItemsCount: 0,
                    complianceScore: 100
                },

                branding: {
                    primaryColor: dna.initialPrimaryColor || '#C5A059',
                    tagline: "Powered by Restaurant OS Empire"
                },

                // SaaS Control: Standard DNA Flags
                featureFlags: {
                    pos: true,
                    inventory: true,
                    analytics: dna.tier !== 'STANDARD',
                    bar: ['restaurant', 'hotel'].includes(dna.variant ?? 'restaurant'),
                    kitchen: true
                },

                security: {
                    twoFactorEnabled: true,
                    nf525Certified: true,
                    maintenanceAccessGranted: false,
                    supportAccessGranted: false // Confidentiality by default
                }
            };

            registeredInstanceId = newInstance.id;

            // 2. INDUSTRIAL WELD: Push to Master Registry (Shared Firebase)
            // This enables the "Single Core" to discover the client.
            await fleetTelemetry.pushSiteTelemetry(newInstance.id as import('@/shared/types/brands').TenantID, {
                ...newInstance,
                healthScore: newInstance.metrics.healthScore,
                complianceScore: newInstance.metrics.complianceScore,
                activeUsers: newInstance.metrics.activeUsers,
                lowStockAlerts: newInstance.metrics.lowStockAlerts,
                dailyRevenue: newInstance.metrics.dailyRevenue,
                status: newInstance.status
            });

            logger.info('ProvisioningEngine: Instance registered in Master Registry', {
                instanceId: newInstance.id,
                url: `https://${dna.key}.nexus-fleet.io`
            });

            // 3. TENANT SEED — PCG, users, fiscalSeals genesis, tables/floors/zones
            if (dna.copyBaseTemplates !== false) {
                const seedResult = await TenantSeeder.seed({
                    tenantId: dna.key,
                    name: dna.name,
                    adminEmail: dna.ownerEmail,
                    variant: dna.variant ?? 'restaurant',
                    primaryColor: dna.initialPrimaryColor,
                    trialDays: dna.trialDays,
                });
                if (!seedResult.success) {
                    logger.warn('ProvisioningEngine: TenantSeeder partial failure', { error: seedResult.error });
                }
            }

            // 3b. Seed RBAC defaults pour ce tenant
            try {
                const defaultRbac = TenantRBACConfigSchema.parse({});
                await Nexus.adapter.set(`tenants/${dna.key}/config/rbac`, defaultRbac);
                logger.info('ProvisioningEngine: RBAC defaults seeded', { tenantId: dna.key });
            } catch (rbacErr) {
                logger.warn('ProvisioningEngine: RBAC seed skipped', { tenantId: dna.key, error: String(rbacErr) });
            }

            // 4. Activer le vertical sectoriel
            const variant = dna.variant ?? 'restaurant';
            try {
                const plugin = VerticalRegistry.resolve(variant);
                const context = new CoreContext();
                await plugin.initialize(context);
                await Nexus.adapter.set(`tenants/${dna.key}/vertical-config`, {
                    variant,
                    registeredRoutes: context.getRegisteredRoutes(),
                    registeredAtoms: context.getRegisteredAtoms(),
                    activatedAt: new Date().toISOString(),
                    pluginVersion: plugin.version,
                });
                logger.info('ProvisioningEngine: vertical activated', { tenantId: dna.key, variant });
            } catch (vertErr) {
                logger.warn('ProvisioningEngine: vertical activation skipped (registry not ready)', {
                    tenantId: dna.key, variant, error: String(vertErr),
                });
            }

            // 5bis. White-Label Branding Injector
            // Si le MCC a fourni une charte custom, on l'injecte ; sinon, mode default.
            const brandingDna = dna.branding;
            await injectBrandingVars(dna.key, {
                mode:          brandingDna?.mode ?? 'default',
                primaryColor:  brandingDna?.accentColor ?? dna.initialPrimaryColor ?? '#C5A059',
                accentColor:   brandingDna?.accentColor,
                logoUrl:       brandingDna?.logoUrl ?? null,
                displayName:   dna.name,
                splashEnabled: brandingDna?.splashEnabled ?? false,
            }).catch(err => logger.warn('ProvisioningEngine: Branding injection skipped', toError(err).message));

            // 5. Initialiser le workspace Sovereign RAG pour ce nouveau tenant.
            // Non-bloquant : si le sidecar est indisponible au moment du provisionnement,
            // le workspace sera créé à la première réindexation manuelle depuis le MCC.
            try {
                await sovereignCreateWorkspace(dna.key, dna.name);
                logger.info('ProvisioningEngine: Sovereign RAG workspace initialized', { tenantId: dna.key });
            } catch (ragErr) {
                logger.warn('ProvisioningEngine: RAG workspace init skipped (sidecar unavailable)', {
                    tenantId: dna.key,
                    error: String(ragErr),
                });
            }

            empireAudit.log({
                module: 'system',
                action: 'REGISTRATION_SUCCESS',
                details: { instanceId: newInstance.id, key: dna.key },
                timestamp: new Date(),
                severity: 'medium'
            });

            return newInstance;

        } catch (error) {
            logger.error('ProvisioningEngine: Registry entry failed — rollback partiel', { key: dna.key, error });

            // Rollback best-effort : purge des fragments Firestore créés avant l'échec.
            // Ne jamais supprimer fiscalSeals (NF525 immuable) — ils ne sont créés qu'en fin de seed réussie.
            await Promise.allSettled([
                Nexus.adapter.delete(`tenants/${dna.key}/tenantConfig`).catch(() => {}),
                Nexus.adapter.delete(`tenants/${dna.key}/users/admin_${dna.key}`).catch(() => {}),
                // Marquer l'entrée fleet comme FAILED (évite les ghost entries ONLINE)
                registeredInstanceId
                    ? fleetTelemetry.pushSiteTelemetry(
                        registeredInstanceId as import('@/shared/types/brands').TenantID,
                        { status: 'PROVISIONING_FAILED' }
                      ).catch(() => {})
                    : Promise.resolve(),
            ]);

            empireAudit.log({
                module: 'system',
                action: 'PROVISIONING_ROLLBACK',
                details: { key: dna.key, error: toError(error).message },
                severity: 'critical',
                timestamp: new Date(),
            });

            throw new Error(`Provisioning échoué pour "${dna.key}" — fragments nettoyés. Détail: ${toError(error).message}`);
        }
    }
};

/**
 * 🐉 SLAYER - Grade VI
 * Moteur d'ingestion souverain pour la migration de données legacy (Zelty, Lightspeed, SumUp).
 * Raccordement complet à la chaîne de scellage NF525 et validation Zod.
 */

import { logger } from "@/lib/logger";
import { DataDigester } from "@modules/intelligence/services/DataDigester";
import { LegacyOrder, Order } from "@nexus/contracts";
import { toMicrounits } from "@/shared/schemas/primitives";
import { FinanceCore } from "@/modules/finance";
import { NexusTransaction } from "@/lib/adapters/NexusTransaction";
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { DEFAULT_TENANT_ID } from '@/config/instance';
import { toError } from "@/lib/toError";
import { JsonObject } from "@/shared/types/json";

export interface SlayerMappingConfig {
    source: string;
    fields: {
        id: string;
        total: string;
        date: string;
        items?: string;
        customerName?: string;
    };
}

export class Slayer {
    /**
     * Traduit un objet brut (CSV/JSON) en structure compatible Nexus via une config.
     */
    static mapLegacy(raw: Record<string, unknown>, config: SlayerMappingConfig): Partial<Order> {
        const legacyTotalInCents = typeof raw[config.fields.total] === 'number'
            ? raw[config.fields.total] as number
            : parseFloat(DataDigester.decontaminate(String(raw[config.fields.total])));
        return {
            id: String(raw[config.fields.id]),
            // Microunits Protocol: write the canonical µ total; keep the cents mirror in parity for legacy readers.
            totalInMicrounits: toMicrounits(Math.round(legacyTotalInCents * 10_000)),
            totalInCents: legacyTotalInCents,
            timestamp: new Date(String(raw[config.fields.date])).toISOString(),
            items: Array.isArray(raw[config.fields.items || 'items']) ? raw[config.fields.items || 'items'] as import('@nexus/contracts').OrderItem[] : [],
            customerName: config.fields.customerName ? String(raw[config.fields.customerName]) : undefined
        };
    }

    /**
     * Ingestion d'un flux massif avec scellage cryptographique à la volée.
     * GRADE VI: Isolation totale et compliance NF525.
     */
    static async ingestMassive(
        stream: LegacyOrder[], 
        tenantId: string = DEFAULT_TENANT_ID,
        onProgress?: (processed: number) => void
    ): Promise<{ ingested: number; errors: number }> {

        logger.info(`[Slayer] OMEGA INGESTION: Initiating phase for ${stream.length} entries on ${tenantId}`);

        let ingested = 0;
        let errors = 0;

        // 📦 CHUNKING INDUSTRIEL (Lots de 200 pour Firestore Batch)
        const CHUNK_SIZE = 200;

        for (let i = 0; i < stream.length; i += CHUNK_SIZE) {
            const chunk = stream.slice(i, i + CHUNK_SIZE);

            try {
                await NexusTransaction.run(
                    {}, 
                    async (batch) => {
                        for (const legacy of chunk) {
                            try {
                                // 1. NORMALISATION & DÉCONTAMINATION
                                const rawOrder: Record<string, unknown> = {
                                    ...legacy,
                                    source: (legacy as JsonObject).source || 'SLAYER_LEGACY',
                                    tenantId: (legacy as JsonObject).tenantId || tenantId,
                                    createdAt: legacy.timestamp || new Date().toISOString(),
                                    status: 'PAID', // Archives scellées par défaut
                                    customer: (legacy as JsonObject).customer || { firstName: 'Legacy', lastName: 'Customer' }
                                };

                                const nexusOrder = await DataDigester.digestOrder(rawOrder as import('@/shared/nexus-contract').SovereignMap, { isLegacy: true });
                                if (!nexusOrder) throw new Error("Validation Failed");

                                // 2. SCELLAGE FISCAL (SHA-256 Post-Quantum)
                                const seal = await FinanceCore.sealRecordWithHash(nexusOrder.id, nexusOrder);

                                // Extension du type pour inclure le scellage fiscal sans cast "unknown"
                                const sealedOrder = {
                                    ...nexusOrder,
                                    _fiscalSeal: seal
                                };

                                // 3. PERSISTANCE NEXUS
                                const path = `${Nexus.getTenantPath('orders', tenantId)}/${nexusOrder.id}`;
                                batch.set(path, sealedOrder);

                                ingested++;
                            } catch (itemError) {
                                errors++;
                                logger.warn(`[Slayer] Item skip: ${legacy.id}`, { error: toError(itemError).message });
                            }
                        }
                    }
                );

                if (onProgress) onProgress(ingested);

            } catch (batchError) {
                logger.error(`[Slayer] Batch Failure (i=${i})`, { error: toError(batchError).message });
            }
        }

        return { ingested, errors };
    }
}

import { randomBytes } from 'crypto';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/logger';
import { validatePin } from '@/lib/auth/validatePin';
import { hashPin } from '@/lib/shared-kernel';
import { resolveDNA } from '@/shared/seeds';
import { FiscalKeyService } from '@/modules/finance';
import { PCG_ACCOUNTS } from '@/shared/seeds/pcg-accounts';
import type { FiscalSeal } from '@/shared/nexus/contracts/finance.types';
