    if (stripeKey) {
        const stripe = new Stripe(stripeKey, { apiVersion: '2026-06-24.dahlia' });
        const customer = await stripe.customers.create({
            email: request.ownerEmail,
            name: request.companyName,
            metadata: { tenantId },
