import { Nexus } from '@/lib/nexus/NexusAdapter';
import { getDefaultStore } from 'jotai';

import { fiscalLedgerAtom } from '@/modules/compliance/qualite/haccp/store/complianceAtoms';
import { TelemetryPulse } from '@/shared/nexus-contract';
import { logger } from '@/lib/logger';

interface BatteryManager {
  level: number;
  charging: boolean;
  addEventListener(type: string, listener: EventListenerOrEventListenerObject): void;
}

interface NetworkInformation extends EventTarget {
  readonly effectiveType: string;
}

interface ExtendedNavigator extends Navigator {
  getBattery?: () => Promise<BatteryManager>;
  connection?: NetworkInformation;
  mozConnection?: NetworkInformation;
  webkitConnection?: NetworkInformation;
}

/**
 * 💓 TelemetryService - The Nexus Heartbeat (Phase 3: Le Miroir)
 * Periodically reports the health and status of the OS back to the Suzerain (MCC).
 */
export class TelemetryService {
  private static heartbeatInterval: NodeJS.Timeout | null = null;
  private static store = getDefaultStore();

  /**
   * Commence l'envoi périodique du heartbeat (chaque 5 minutes).
   */
  static start(tenantId: string) {
    this.stop(); // Cleanup previous if unknown

    logger.info(`[TelemetryService] Heartbeat démarré pour ${tenantId} (Intervalle: 5min).`);

    // Initial beat
    this.sendPulse(tenantId);

    // Set interval (5 minutes = 300,000ms)
    this.heartbeatInterval = setInterval(() => {
      this.sendPulse(tenantId);
    }, 300000);
  }

  /**
   * Envoie un signal unique de santé vers Firestore.
   */
  private static async sendPulse(tenantId: string) {
    try {
      const heartbeatPath = `tenants/${tenantId}/status/heartbeat`;

      // 1. Gather Battery Info
      let batteryInfo = { level: 1, charging: true, supported: false };
      const extendedNav = navigator as ExtendedNavigator;
      if (typeof extendedNav !== 'undefined' && extendedNav.getBattery) {
        try {
          const battery = await extendedNav.getBattery();
          batteryInfo = {
            level: battery.level,
            charging: battery.charging,
            supported: true
          };
        } catch (_e) { /* Fallback */ }
      }

      // 2. Gather NF525 Status
      const ledgerData: import('@nexus/contracts/finance.types').JournalEntry[] = this.store.get(fiscalLedgerAtom);
      const isSealed = Array.isArray(ledgerData) && ledgerData.some(e => e.fiscalSealHash);
      const lastHash = isSealed ? ledgerData.find(e => e.fiscalSealHash)?.fiscalSealHash : undefined;

      // Type-safe connection check
      const connection = extendedNav.connection || extendedNav.mozConnection || extendedNav.webkitConnection;
      const effectiveType = connection?.effectiveType || 'SOVEREIGN_UNKNOWN';


      const payload: TelemetryPulse = {
        version: '9.0.0-grade-ix',
        status: 'ACTIVE',
        lastPulse: Nexus.adapter.serverTimestamp(),
        health: {
          uptime: typeof process !== 'undefined' && process.uptime ? Math.floor(process.uptime()) : 0,
          battery: batteryInfo,
          network: {
            online: typeof navigator !== 'undefined' ? navigator.onLine : true,
            effectiveType
          }
        },
        security: {
          nf525Sealed: isSealed,
          lastSealHash: lastHash,
          integrityGrade: 'IX'
        }
      };

      await Nexus.adapter.set(heartbeatPath, payload, { merge: true });
      logger.debug(`[TelemetryService] Heartbeat envoyé à ${new Date().toLocaleTimeString()}`);
    } catch (error) {
      console.warn(`[TelemetryService] Échec du heartbeat:`, error);
    }
  }

  /**
   * 📢 Dénonce une anomalie TECHNIQUE au MCC (Anonymisation Totale).
   * INTERDICTION : Pas de montants, pas de noms, pas de PII.
   */
  static async reportIssue(code: 'FALLBACK_VALUE' | 'INTEGRITY_DRIFT' | 'AUTH_ANOMALY', source: string, techMetadata: { field: string, type?: string }) {
    try {
      const issueId = `INCIDENT-${Math.random().toString(36).substring(7).toUpperCase()}`;
      const issuePath = `system_alerts/${issueId}`;

      await Nexus.adapter.set(issuePath, {
        code,
        source,
        techMetadata,
        timestamp: Nexus.adapter.serverTimestamp(),
        version: '9.0.0-grade-ix',
        severity: code === 'INTEGRITY_DRIFT' ? 'CRITICAL' : 'WARNING'
      });

      console.warn(`[TelemetryService] TECHNICAL_SIGNAL_SENT: ${code} from ${source}`, techMetadata);
    } catch (_e) {
      // Échec silencieux pour ne pas perturber l'expérience locale
    }
  }

  /**
   * Arrête le heartbeat.
   */
  static stop() {
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval);
      this.heartbeatInterval = null;
      logger.info(`[TelemetryService] Heartbeat arrêté.`);
    }
  }
}

/* eslint-disable no-restricted-imports -- infrastructure/aggregator: deep path required */
import { INexusAdapter, INexusBatch, INexusTransaction, NexusContext } from "@/lib/nexus/types";
import type { SovereignData } from '@/shared/nexus-contract';

import { simulatorDb } from '@/modules/intelligence/ia/simulator/SimulatorDB';
import { logger } from '@/lib/logger';
import { IdGenerator } from '@/lib/utils/IdGenerator';
import { 
    IDocumentStore, 
    IQueryEngine, 
    IRealtimeSubscriber, 
    IQueryOptions 
} from '@/shared/nexus/contracts/infrastructure/storage.contracts';

/**
 * 🌀 SimulacraAdapter - Restaurant OS (Grade X - Pure I/O)
 * The Copy-on-Write Isolation Layer.
 * Reads from Real Adapter + Virtual Store. Writes ONLY to Virtual Store.
 */
export class SimulacraAdapter implements INexusAdapter, IDocumentStore, IQueryEngine, IRealtimeSubscriber {
    constructor(
        private realAdapter: INexusAdapter,
        private forkId: string = 'default_sim'
    ) {
        logger.info(`[Simulacra] Air-Gap Interface active for fork: ${forkId}`);
    }

    async get<T = SovereignData>(path: string, _context?: NexusContext): Promise<T | null> {
        // 1. Check Virtual Store first
        const virtual = await simulatorDb.virtualStore.get(path);

        if (virtual) {
            if (virtual.isDeleted) return null;
            return virtual.data as T;
        }

        // 2. Fallback to Real Adapter (Read-only source)
        return this.realAdapter.get<T>(path);
    }

    async query<T = SovereignData>(collectionPath: string, options?: IQueryOptions, _context?: NexusContext): Promise<T[]> {
        const realResults = await this.realAdapter.query<T>(collectionPath, options);
        const virtualResults = await simulatorDb.virtualStore
            .where('forkId').equals(this.forkId)
            .filter(doc => doc.path.startsWith(collectionPath))
            .toArray();

        // Merge logic: Virtual data overrides or filters out real data
        const merged = [...realResults] as Array<T & { id?: string }>;

        virtualResults.forEach(v => {
            const virtualData = v.data as T & { id?: string };
            const index = merged.findIndex(m => m.id === virtualData.id);
            if (v.isDeleted) {
                if (index !== -1) merged.splice(index, 1);
            } else {
                if (index !== -1) merged[index] = virtualData;
                else merged.push(virtualData);
            }
        });

        return merged as T[];
    }

    onSnapshot<T = SovereignData>(path: string, callback: (data: T) => void, _options?: IQueryOptions, _context?: NexusContext): () => void {
        logger.warn("[Simulacra] Real-time snapshots are simulated via polling in Grade X.");

        // Initial load
        this.get<T>(path).then((data) => callback(data as T));

        // Polling simulation (every 2s)
        const interval = setInterval(async () => {
            const data = await this.get<T>(path);
            callback(data as T);
        }, 2000);

        return () => clearInterval(interval);
    }

    batch(context?: NexusContext): INexusBatch {
        const ops: Array<() => Promise<void>> = [];
        return {
            set: (path: string, data: unknown) => {
                ops.push(() => this.set(path, data, undefined, context));
            },
            update: (path: string, data: unknown) => {
                ops.push(() => this.update(path, data as Partial<SovereignData>, context));
            },
            delete: (path: string) => {
                ops.push(() => this.delete(path, context));
            },
            increment: (path: string, field: string, amount: number) => {
                ops.push(() => this.increment(path, field, amount, context));
            },
            commit: async () => {
                for (const op of ops) await op();
            }
        };
    }

    async set<T = SovereignData>(path: string, data: T, options?: { merge?: boolean }, _context?: NexusContext): Promise<void> {
        let finalData = data;

        if (options?.merge) {
            const existing = await this.get<Record<string, unknown>>(path);
            finalData = { ...existing, ...data };
        }

        await simulatorDb.virtualStore.put({
            path,
            data: finalData as SovereignData,
            isDeleted: false,
            forkId: this.forkId,
            updatedAt: new Date().toISOString()
        });
    }

    async update<T = SovereignData>(path: string, data: Partial<T>, _context?: NexusContext): Promise<void> {
        const existing = await this.get<Record<string, unknown>>(path);
        const finalData = { ...existing, ...data };

        await simulatorDb.virtualStore.put({
            path,
            data: finalData as SovereignData,
            isDeleted: false,
            forkId: this.forkId,
            updatedAt: new Date().toISOString()
        });
    }

    async delete(path: string, _context?: NexusContext): Promise<void> {
        await simulatorDb.virtualStore.put({
            path,
            data: null,
            isDeleted: true,
            forkId: this.forkId,
            updatedAt: new Date().toISOString()
        });
    }

    async create<T = SovereignData>(path: string, data: T, context?: NexusContext): Promise<void> {
        await this.set(path, data, undefined, context);
    }

    generateId(_collectionPath: string): string {
        return IdGenerator.generateWithPrefix('sim');
    }

    serverTimestamp(): import('@/shared/nexus/contracts/infrastructure/storage.contracts').NexusTimestamp {
        return this.realAdapter.serverTimestamp();
    }

    async increment(path: string, field: string, amount: number, _context?: NexusContext): Promise<void> {
        const existing = await this.get<Record<string, number>>(path) || {} as Record<string, number>;
        existing[field] = (Number(existing[field]) || 0) + amount;
        await this.set(path, existing);
    }

    async runTransaction<T>(callback: (tx: INexusTransaction) => Promise<T>, context?: NexusContext): Promise<T> {
        const deferred: Array<() => Promise<void>> = [];
        const tx: INexusTransaction = {
            get: (path) => this.get(path, context),
            set: (path, data) => { deferred.push(() => this.set(path, data as SovereignData, undefined, context)); },
            update: (path, data) => { deferred.push(() => this.update(path, data as Partial<SovereignData>, context)); },
            delete: (path) => { deferred.push(() => this.delete(path, context)); },
        };
        const result = await callback(tx);
        for (const op of deferred) await op();
        return result;
    }
}

import { db, SyncOperation } from './offline-store';
import { checkOnlineStatus } from './connectivity-hooks';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/axiom';
import { toError } from "@/lib/toError";

/**
 * 🔄 SyncManager - Restaurant OS
 * Gère la file d'attente de synchronisation entre la base locale et Firestore.
 */
async function executeMutationOp(op: SyncOperation): Promise<void> {
    const fullPath = op.collection + (op.targetId ? `/${op.targetId}` : '');
    if (op.action === 'CREATE') {
        await Nexus.adapter.create(op.collection, op.payload);
    } else if (op.action === 'DELETE') {
        await Nexus.adapter.delete(fullPath);
    } else if (op.action === 'SET') {
        await Nexus.adapter.set(fullPath, op.payload);
    } else if (op.action === 'UPDATE') {
        await Nexus.adapter.update(fullPath, op.payload as Partial<import('@/shared/nexus-contract').SovereignData>);
    }
}

async function executeFallbackOp(op: SyncOperation): Promise<void> {
    const fullPath = `${op.collection}/${op.targetId}`;
    if (op.action === 'SET') await Nexus.adapter.set(fullPath, op.payload);
    if (op.action === 'UPDATE') await Nexus.adapter.update(fullPath, op.payload as Partial<import('@/shared/nexus-contract').SovereignData>);
}

export class SyncManager {
    private static isSyncing = false;

    /** Au-delà : on continue de retenter (jamais de drop fiscal) mais on loggue en critique. */
    private static readonly ALERT_ATTEMPTS = 10;

    /**
     * Ajoute une opération à la file d'attente et tente une synchro si possible.
     */
    static async enqueue(op: Omit<SyncOperation, 'status' | 'attempts' | 'timestamp'>) {
        const newOp: SyncOperation = {
            ...op,
            status: 'pending',
            attempts: 0,
            timestamp: new Date().toISOString(),
            // ⚠️ 'NF525_PAYMENT' ne contient pas « FISCAL » : l'ancien calcul
            // (op.type.includes('FISCAL')) classait les paiements en priorité 0.
            priority: op.priority ?? (
                op.type === 'NF525_PAYMENT' || op.type === 'NF525_JET' || op.type === 'FISCAL_SEAL' || op.type === 'JOURNAL_ENTRY' ? 1 : 0
            )
        };

        const id = await db.syncQueue.add(newOp);
        logger.info('SyncManager: Operation enqueued', { id, type: op.type });

        // Tenter une synchro immédiate si online
        if (checkOnlineStatus()) {
            this.processQueue();
        } else {
            // Tenter d'enregistrer le tag Background Sync pour quand le réseau reviendra
            if (typeof window !== 'undefined' && 'serviceWorker' in navigator) {
                navigator.serviceWorker.ready.then(registration => {
                        interface SyncManager {
                            register(tag: string): Promise<void>;
                        }
                        const swReg = registration as ServiceWorkerRegistration & { sync?: SyncManager };
                        if (swReg.sync) {
                            swReg.sync.register('restaurant-os-sync').catch(() => {});
                        }
                }).catch(() => {});
            }
        }
    }

    /**
     * Traite tous les éléments en attente dans la SyncQueue.
     */
    static async processQueue() {
        if (this.isSyncing) return;

        // ⚠️ Rejouer AUSSI les 'failed' : les laisser de côté = ticket NF525
        // perdu au premier échec. Une op fiscale n'est JAMAIS abandonnée.
        const pendingOps = (await db.syncQueue
            .where('status')
            .anyOf('pending', 'failed')
            .toArray())
            // Fiscal (priority 1) d'abord, puis ordre chronologique (chaîne de sceaux).
            .sort((a, b) => (b.priority - a.priority) || a.timestamp.localeCompare(b.timestamp));

        if (pendingOps.length === 0) return;

        this.isSyncing = true;
        logger.info('SyncManager: Starting synchronization process', { count: pendingOps.length });

        for (const op of pendingOps) {
            try {
                await this.executeOperation(op);
                // Mark as synced and delete from queue if successful
                await db.syncQueue.delete(op.id!);
                logger.info('SyncManager: Operation synced and removed', { id: op.id, type: op.type });
            } catch (error) {
                const err = error as Error;
                const errorMessage = err.message || toError(error).message;
                logger.error('SyncManager: Sync failed for operation', { id: op.id, error: errorMessage });

                await db.syncQueue.update(op.id!, {
                    status: 'failed',
                    attempts: op.attempts + 1,
                    lastError: errorMessage
                });

                if (op.attempts + 1 >= this.ALERT_ATTEMPTS) {
                    logger.error('SyncManager: CRITICAL — operation stuck after repeated attempts', {
                        id: op.id, type: op.type, attempts: op.attempts + 1
                    });
                }

                // Si c'est une erreur de connexion, on arrête la boucle
                if (!checkOnlineStatus()) break;
            }
        }

        this.isSyncing = false;

        // Relancer si de nouveaux items PENDING sont arrivés entre temps.
        // (Les 'failed' attendent le prochain déclencheur — online/boot/enqueue —
        // pour éviter une boucle chaude de retries.)
        const remaining = await db.syncQueue.where('status').equals('pending').count();
        if (remaining > 0 && checkOnlineStatus()) {
            this.processQueue();
        }
    }

    /**
     * Exécute une opération spécifique vers Firestore.
     */
    private static async executeOperation(op: SyncOperation) {
        if (op.type === 'NF525_PAYMENT') {
            const payload = op.payload as { instructions: Array<{ method: string; path: string; data: import('@/shared/nexus-contract').SovereignData }> };
            const instructions = payload.instructions;

            // Idempotence : si le JournalEntry existe déjà (écriture partielle avant
            // déconnexion), on ne rejoue pas le batch — sinon double-scellement NF525.
            const journalInstruction = instructions.find(i => i.path.includes('/journalEntries/'));
            if (journalInstruction) {
                const existing = await Nexus.adapter.get(journalInstruction.path);
                if (existing) {
                    logger.info('SyncManager: NF525_PAYMENT déjà commité — skip replay', { path: journalInstruction.path });
                    return;
                }
            }

            // Call the sync API instead of writing directly, to perform server-side atomic sealing
            const journalEntries = instructions
                .filter(ins => ins.path.includes('/journalEntries/') && ins.method === 'SET')
                .map(ins => ins.data);

            if (journalEntries.length > 0) {
                // Extract tenantId from path (e.g. 'tenants/tenant-1/journalEntries/JE-123')
                const pathParts = instructions[0].path.split('/');
                const tenantId = pathParts[1];

                const response = await fetch('/api/finance/sync', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        tenantId,
                        journalEntries,
                        isTrainingMode: false,
                    }),
                });

                if (!response.ok) {
                    throw new Error(`Sync API failed: ${response.status} ${response.statusText}`);
                }
            }
        } else if (op.type === 'NF525_JET') {
            const payload = op.payload as import('@/shared/nexus-contract').SovereignData;
            const tenantId = op.collection.split('/')[1] || 'default';

            const response = await fetch('/api/finance/jet/sync', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    tenantId,
                    entries: [payload],
                }),
            });

            if (!response.ok) {
                throw new Error(`JET Sync API failed: ${response.status} ${response.statusText}`);
            }
        } else if (op.type === 'MUTATION') {
            await executeMutationOp(op);
        } else {
            await executeFallbackOp(op);
        }
    }
}

// Lancement automatique du manager lors du chargement (si en ligne)
export function bootSyncManager() {
    if (typeof window !== 'undefined') {
        window.addEventListener('online', () => SyncManager.processQueue());

        // Listen to Service Worker Background Sync triggers
        if ('serviceWorker' in navigator) {
            navigator.serviceWorker.addEventListener('message', (event) => {
                if (event.data && event.data.type === 'PROCESS_SYNC_QUEUE') {
                    logger.info('SyncManager: Background Sync triggered by Service Worker');
                    SyncManager.processQueue();
                }
            });
            // Register Background Sync if queuing happens
            navigator.serviceWorker.ready.then(registration => {
                // Background Sync registration happens inside SyncManager.enqueue now
            }).catch(() => {});
        }

        // On lance immédiatement la synchro au chargement
        SyncManager.processQueue();
    }
}

import { z } from 'zod';
import { requireSession } from '@/lib/server/verifySession';
import { NexusError, NexusErrorCode } from '@/shared/nexus/errors';
import { assertPermission } from '@/shared/rbac/checkPermission';
import { ACTION_MAP } from '@/shared/rbac/actionPermissionMap';
import { PinHashService } from '@/lib/server/PinHashService';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import type { User } from '@/modules/human';

export function createSafeAction<TArgs extends any[], TOutput>(
    schema: z.ZodType<TArgs>,
    permission: { page: string; action: string },
    handler: (tenantId: string, ...args: TArgs) => Promise<TOutput>,
) {
    return async (tenantId: string, ...args: unknown[]): Promise<TOutput> => {
        // 1. Souveraineté - Lève si session invalide
        const session = await requireSession(tenantId);

        // 2. RBAC - Vérifie le rôle
        assertPermission(session.role, permission.page, permission.action);

        const config = ACTION_MAP[permission.page]?.[permission.action];

        // 3. Validation Zod (valide le tuple d'arguments)
        const parsed = schema.safeParse(args);
        if (!parsed.success) {
            throw new NexusError(
                NexusErrorCode.VALIDATION_ERROR,
                `Payload invalide : ${parsed.error.issues.map(i => `${i.path.join('.')} ${i.message}`).join(' · ')}`,
                parsed.error.issues,
            );
        }

        // 4. Vérification PIN côté serveur si exigé
        if (config?.requiresPin) {
            // Le PIN est attendu soit dans le dernier argument s'il s'agit d'un objet { pin: string },
            // soit explicitement défini par le client.
            const lastArg = args[args.length - 1];
            const pin = typeof lastArg === 'object' && lastArg !== null && 'pin' in lastArg 
                ? (lastArg as any).pin as string 
                : undefined;

            if (!pin) {
                throw new NexusError(NexusErrorCode.ACCESS_DENIED, 'Code PIN requis pour cette action');
            }

            const user = await Nexus.adapter.get<User & { pinHash?: string; pinSalt?: string; pin?: string }>(
                `tenants/${tenantId}/staff/${session.uid}`
            );

            if (!user) {
                throw new NexusError(NexusErrorCode.ACCESS_DENIED, 'Utilisateur introuvable');
            }

            let isValid = false;
            if (user.pinHash && user.pinSalt) {
                isValid = PinHashService.verify(pin, user.pinHash, user.pinSalt);
            } else if (user.pin === pin) {
                isValid = true;
            }

            if (!isValid) {
                throw new NexusError(NexusErrorCode.ACCESS_DENIED, 'Code PIN incorrect');
            }
        }

        // 5. Exécution métier
        return handler(tenantId, ...parsed.data);
    };
}

import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/logger';
import { NextResponse } from 'next/server';
import { toError } from "@/lib/toError";

export async function isPeriodLocked(tenantId: string, timestamp: number): Promise<boolean> {
  try {
    const date = new Date(timestamp);
    const periodId = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;

    const lockRef = await Nexus.adapter.query<{ isLocked: boolean; lockedAt: number; lockedBy: string }>('fiscalLedger/locks', {
        where: [
            { field: 'id', operator: '==', value: periodId },
            { field: 'tenantId', operator: '==', value: tenantId }
        ]
    });

    // In our DB structure, locks are at `tenants/${tenantId}/fiscalLedger/locks/${periodId}`
    // But since `Nexus.adapter.query` queries the collection across tenants (or with tenant prefix?),
    // wait, NexusAdapter query usually requires the full path if it's nested, or just the collection name if it's global.
    // Let's just fetch the document directly since we know the ID.
    const lockDoc = await Nexus.adapter.get<{ isLocked: boolean; lockedAt: number; lockedBy: string }>(`tenants/${tenantId}/fiscalLedger/locks/${periodId}`);

    return !!(lockDoc && lockDoc.isLocked);
  } catch (err) {
    logger.error(`[fiscalLockGuard] Error checking lock for tenant ${tenantId}`, toError(err).message);
    return false; // fail-open ou fail-closed? fail-open par défaut pour éviter de tout bloquer en cas d'erreur
  }
}

export async function requireUnlockedPeriod(tenantId: string, timestamp: number): Promise<NextResponse | null> {
    const locked = await isPeriodLocked(tenantId, timestamp);
    if (locked) {
        return new NextResponse(
            JSON.stringify({ error: 'La période comptable est clôturée et verrouillée (Sceau NF525).' }),
            { status: 403, headers: { 'Content-Type': 'application/json' } }
        );
    }
    return null;
}

import 'server-only';
import { createHmac, timingSafeEqual } from 'node:crypto';

/** HMAC-SHA256 hex du body brut avec le secret donné. */
export function computeHmacHex(secret: string, data: string): string {
  return createHmac('sha256', secret).update(data, 'utf8').digest('hex');
}

/**
 * Comparaison timing-safe de deux chaînes hex de même longueur.
 * Retourne false immédiatement si les longueurs diffèrent (pas de timing leak possible).
 */
export function timingSafeCompareHex(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  try {
    return timingSafeEqual(Buffer.from(a, 'hex'), Buffer.from(b, 'hex'));
  } catch {
    return false;
  }
}

const CONNECTORS_WEBHOOK_SECRET = process.env.CONNECTORS_WEBHOOK_SECRET;

/**
 * Fallback pour les providers sans HMAC propre.
 * Vérifie `Authorization: Bearer <CONNECTORS_WEBHOOK_SECRET>`.
 *
 * - Secret configuré + header correct → true
 * - Secret configuré + header incorrect → false (401)
 * - Secret non configuré → true avec warning (backward compat, migration progressive)
 */
export function checkFallbackWebhookSecret(headers: Headers, providerId: string): boolean {
  if (!CONNECTORS_WEBHOOK_SECRET) {
    // Intentionnel pendant la migration — loggé par la route appelante
    return true;
  }
  const auth = headers.get('authorization');
  return auth === `Bearer ${CONNECTORS_WEBHOOK_SECRET}`;
}

import { ZodSchema } from 'zod';
import { UserSchema } from '@/modules/human';
import { OrderSchema } from '@/modules/ops';
import { StockItemSchema } from '@/modules/ops';
import { TableSchema, ReservationSchema, FloorSchema, ZoneSchema } from '@/modules/ops';
import { ModuleSchema } from '@/modules/system';
import { 
  JournalEntrySchema, 
  AccountSchema, 
  BankTransactionSchema, 
  ExpenseClaimSchema 
} from '@/modules/finance';
import { NexusError, NexusErrorCode } from '@/shared/nexus/errors';
import { logger } from '@/lib/axiom';

type AnyRecord = Record<string, unknown>;

/**
 * 🏛️ FirestoreHydrator - Grade X
 * Assure la validation runtime et la transformation des données Firestore.
 */
export class FirestoreHydrator {
  static hydrateJournalEntry(raw: AnyRecord) {
    const parsed = JournalEntrySchema.safeParse(raw);
    if (!parsed.success) {
      throw new NexusError(
        NexusErrorCode.HYDRATION_FAILURE,
        'JournalEntry document is malformed in Firestore',
        { issues: parsed.error.issues.map(i => i.message) }
      );
    }

    const data = parsed.data;
    return {
      ...data,
      date: data.date || data.serverTimestamp,
      pieceNumber: data.pieceNumber || data.receiptNumber,
      description: data.description || `Transaction ${data.receiptNumber}`,
      amountInCents: Math.round(data.amountInMicrounits / 10_000),
      isValidated: data.status === 'validated',
      isSystemGenerated: true,
      updatedAt: data.serverTimestamp,
      lines: [] as import('@nexus/contracts').JournalLine[],
    };
  }

  static hydrateAccount(raw: AnyRecord) {
    const parsed = AccountSchema.safeParse(raw);
    if (!parsed.success) {
      throw new NexusError(
        NexusErrorCode.HYDRATION_FAILURE,
        'Account document is malformed in Firestore',
        { issues: parsed.error.issues.map(i => i.message) }
      );
    }
    const data = parsed.data;
    return {
      ...data,
      balanceInCents: Math.round(data.balanceInMicrounits / 10_000),
      updatedAt: data.updatedAt,
      class: data.class as '1' | '2' | '3' | '4' | '5' | '6' | '7',
    };
  }

  static hydrateBankTransaction(raw: AnyRecord) {
    const parsed = BankTransactionSchema.safeParse(raw);
    if (!parsed.success) {
      throw new NexusError(
        NexusErrorCode.HYDRATION_FAILURE,
        'BankTransaction document is malformed in Firestore',
        { issues: parsed.error.issues.map(i => i.message) }
      );
    }
    const data = parsed.data;
    return {
      ...data,
      date: data.date || data.executedAt,
      label: data.label || data.description,
      amountInCents: Math.round(data.amountInMicrounits / 10_000),
      type: (data.type || data.direction) as 'credit' | 'debit',
      isReconciled: !!data.reconciledAt,
      updatedAt: data.executedAt,
    };
  }

  static hydrateExpenseClaim(raw: AnyRecord) {
    const parsed = ExpenseClaimSchema.safeParse(raw);
    if (!parsed.success) {
      throw new NexusError(
        NexusErrorCode.HYDRATION_FAILURE,
        'ExpenseClaim document is malformed in Firestore',
        { issues: parsed.error.issues.map(i => i.message) }
      );
    }
    const data = parsed.data;
    return {
      ...data,
      date: data.date || data.submittedAt,
      userId: data.userId || data.submittedBy,
      userName: data.userName || 'Unknown',
      userRole: data.userRole || 'employee',
      amountInCents: Math.round(data.amountInMicrounits / 10_000),
      updatedAt: data.submittedAt,
    };
  }

  // --- Legacy Compatibility & Helpers ---

  static hydrateUser(data: AnyRecord) { return this.hydrate(data, UserSchema, 'users'); }
  static hydrateOrder(data: AnyRecord) { return this.hydrate(data, OrderSchema, 'orders'); }
  static hydrateStockItem(data: AnyRecord) { return this.hydrate(data, StockItemSchema, 'inventory'); }
  static hydrateTable(data: AnyRecord) { return this.hydrate(data, TableSchema, 'tables'); }
  static hydrateReservation(data: AnyRecord) { return this.hydrate(data, ReservationSchema, 'reservations'); }
  static hydrateFloor(data: AnyRecord) { return this.hydrate(data, FloorSchema, 'floors'); }
  static hydrateZone(data: AnyRecord) { return this.hydrate(data, ZoneSchema, 'zones'); }
  static hydrateModule(data: AnyRecord) { return this.hydrate(data, ModuleSchema, 'modules'); }

  private static hydrate<T>(data: AnyRecord, schema: ZodSchema<T>, collection: string): T | null {
    const result = schema.safeParse(data);
    if (result.success) return result.data;
    logger.error(`[FirestoreHydrator] Data corruption in ${collection}`, {
      errors: result.error.issues.map(i => `${i.path.join('.')}: ${i.message}`),
    });
    return null;
  }

  static hydrateCollection<T>(
    docs: AnyRecord[],
    hydrator: (raw: AnyRecord) => T
  ): T[] {
    return docs.map(doc => {
        try {
            return hydrator(doc);
        } catch (e) {
            logger.warn(`[FirestoreHydrator] Skipping corrupted document: ${e instanceof Error ? e.message : 'Unknown error'}`);
            return null;
        }
    }).filter((r): r is T => r !== null);
  }
}

import { logger } from '@/lib/logger';
import { Nexus } from '@/lib/nexus/NexusAdapter';

export interface FiscalTransaction {
  id: string;
  tenantId: string;
  amount: number;
  currency: string;
  vatAmounts: Record<string, number>;
  timestamp: number;
  type: 'SALE' | 'REFUND';
  signature?: string; 
  previousSignature?: string; 
}

export interface FiscalArchiveZ {
  id: string;
  tenantId: string;
  date: string;
  totalSales: number;
  totalVat: number;
  transactionCount: number;
  startSignature: string;
  endSignature: string;
  archiveSignature: string;
  timestamp: number;
}

/**
 * FiscalLedger (Grade X)
 * Moteur cryptographique NF525 pour l'inaltérabilité des données de caisse.
 * Utilise l'API Web Crypto native (compatible Edge, Node 18+, Browser).
 */
export class FiscalLedger {

  /**
   * Hashes a string using SHA-256
   */
  private static async hashSHA256(data: string): Promise<string> {
    const encoder = new TextEncoder();
    const dataBuffer = encoder.encode(data);
    const hashBuffer = await crypto.subtle.digest('SHA-256', dataBuffer);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
  }

  /**
   * Scelle une transaction fiscale en la chaînant avec la précédente.
   * C'est l'exigence technique principale de la NF525.
   */
  static async sealTransaction(tx: Omit<FiscalTransaction, 'signature' | 'previousSignature'>): Promise<FiscalTransaction> {
    logger.info(`[FiscalLedger] Sealing transaction ${tx.id} for tenant ${tx.tenantId}`);

    // 1. Récupérer la signature de la TOUTE DERNIÈRE transaction de ce tenant
    // Note: Dans une vraie DB, on fait une requête triée par timestamp descendant LIMIT 1
    let previousSignature = 'GENESIS_BLOCK_00000000000000000000000000000000';
    try {
      const lastTx = await Nexus.adapter.query<FiscalTransaction>(`tenants/${tx.tenantId}/fiscal_ledger`, { 
        limit: 1, 
        orderBy: { field: 'timestamp', direction: 'desc' } 
      });
      if (lastTx && lastTx.length > 0 && lastTx[0].signature) {
        previousSignature = lastTx[0].signature;
      }
    } catch (err) {
      logger.warn(`[FiscalLedger] Could not fetch previous transaction for ${tx.tenantId}. Using Genesis block if new tenant.`);
    }

    // 2. Préparer la chaîne de données (Ordre strict)
    // [ID] + [MONTANT] + [DATE] + [PREVIOUS_HASH]
    const dataString = `${tx.id}|${tx.amount}|${tx.timestamp}|${previousSignature}`;

    // 3. Hachage SHA-256
    const signature = await this.hashSHA256(dataString);

    const sealedTx: FiscalTransaction = {
      ...tx,
      previousSignature,
      signature
    };

    // 4. Sauvegarde inaltérable
    await Nexus.adapter.set(`tenants/${tx.tenantId}/fiscal_ledger/${tx.id}`, sealedTx);

    return sealedTx;
  }

  /**
   * Génère l'Archive Z (Clôture journalière)
   * Cette archive est elle-même signée et fige la journée.
   */
  static async generateZArchive(tenantId: string, dateYYYYMMDD: string): Promise<FiscalArchiveZ> {
    logger.info(`[FiscalLedger] Generating Z-Archive for ${tenantId} on ${dateYYYYMMDD}`);

    // 1. Récupérer toutes les transactions de la journée
    const transactions = await Nexus.adapter.query<FiscalTransaction>(`tenants/${tenantId}/fiscal_ledger`);
    // Note: Simulation d'un filtre par date
    const dayTxs = transactions.filter(t => new Date(t.timestamp).toISOString().startsWith(dateYYYYMMDD));

    if (dayTxs.length === 0) {
      throw new Error(`Aucune transaction trouvée pour la clôture du ${dateYYYYMMDD}`);
    }

    // Tri chronologique strict
    dayTxs.sort((a, b) => a.timestamp - b.timestamp);

    const startSignature = dayTxs[0].signature!;
    const endSignature = dayTxs[dayTxs.length - 1].signature!;

    let totalSales = 0;
    let totalVat = 0;

    for (const t of dayTxs) {
      if (t.type === 'SALE') totalSales += t.amount;
      if (t.type === 'REFUND') totalSales -= t.amount;
      totalVat += Object.values(t.vatAmounts).reduce((acc: number, val: number) => acc + val, 0);
    }

    // 2. Chiffrement de l'archive Z
    const archiveData = `${tenantId}|${dateYYYYMMDD}|${totalSales}|${startSignature}|${endSignature}`;
    const archiveSignature = await this.hashSHA256(archiveData);

    const archive: FiscalArchiveZ = {
      id: `Z-${dateYYYYMMDD}`,
      tenantId,
      date: dateYYYYMMDD,
      totalSales,
      totalVat,
      transactionCount: dayTxs.length,
      startSignature,
      endSignature,
      archiveSignature,
      timestamp: Date.now()
    };

    // 3. Sauvegarde (Grand Livre d'Archive)
    await Nexus.adapter.set(`tenants/${tenantId}/fiscal_archives/${archive.id}`, archive);

    return archive;
  }
}

/* eslint-disable no-restricted-imports -- aggregator: must use deep paths for cycle prevention */
import { getDefaultStore } from 'jotai';
import { shouldEagerLoad, type ICMImportanceMap } from '@/lib/icm/TaskContext';
import { TimeSync } from '@/lib/TimeSync';

// Sous-services de synchronisation : un par pilier métier + l'horloge (TimeSync).
import { OpsSyncService as SyncOrders } from '@/modules/ops/workflow/engine/ops.sync';
import { InventorySyncService as SyncStocks } from '@/modules/logistics/stock/inventory/inventory.sync';
import { FinanceSyncService as SyncFinance } from '@/modules/finance/finance.sync';
import { HACCPSyncService as SyncHACCP } from '@/modules/compliance/qualite/haccp/haccp.sync';
import { MarketingSyncService as SyncMarketing } from '@/modules/commerce/acquisition/marketing/marketing.sync';
import { HRSyncService as SyncStaff } from '@/modules/human/effectifs/hr/hr.sync';

type Store = ReturnType<typeof getDefaultStore>;

/**
 * 🧩 Registre des sous-systèmes de synchronisation temps réel.
 *
 * Extrait de NexusSyncService pour réduire son fan-out (god file) : les 6 sous-services
 * de pilier + TimeSync (horloge) vivent ici ; NexusSyncService n'importe qu'un seul
 * point d'entrée init/stop au lieu de 7 modules.
 *
 * ICM-lite : seuls les piliers marqués HIGH/MEDIUM (`shouldEagerLoad`) sont initialisés.
 * TimeSync est toujours initialisé (l'horloge ne dépend pas de la route).
 * L'initialisation reste parallèle (Promise.all) pour tenir la cible < 180 ms.
 */
export async function initPillarSyncs(
  imp: ICMImportanceMap,
  tenantId: string,
  store: Store
): Promise<void> {
  await Promise.all([
    TimeSync.init(),
    shouldEagerLoad(imp.orders)     ? SyncOrders.init(tenantId, store)    : Promise.resolve(),
    // SyncStocks gère aussi les catégories et produits (catalog) :
    // on l'active dès que stocks OU categories OU products est HIGH/MEDIUM.
    (shouldEagerLoad(imp.stocks) || shouldEagerLoad(imp.categories) || shouldEagerLoad(imp.products))
                                    ? SyncStocks.init(tenantId, store)    : Promise.resolve(),
    shouldEagerLoad(imp.finance)    ? SyncFinance.init(tenantId, store)   : Promise.resolve(),
    shouldEagerLoad(imp.compliance) ? SyncHACCP.init(tenantId, store)     : Promise.resolve(),
    shouldEagerLoad(imp.marketing)  ? SyncMarketing.init(tenantId, store) : Promise.resolve(),
    shouldEagerLoad(imp.staff)      ? SyncStaff.init(tenantId, store)     : Promise.resolve(),
  ]);
}

/**
 * Arrête tous les sous-systèmes de synchronisation (Zero Leak Policy).
 * TimeSync est stoppé en premier, comme dans l'orchestrateur d'origine.
 */
export function stopPillarSyncs(): void {
  TimeSync.stop();
  SyncOrders.stop();
  SyncStocks.stop();
  SyncFinance.stop();
  SyncHACCP.stop();
  SyncMarketing.stop();
  SyncStaff.stop();
}

import { getDefaultStore } from 'jotai';
import { logger } from '@/lib/logger';
import { ordersNodeAtom } from '@/store/pillars/ops';
import { stockItemsNodeAtom } from '@/store/pillars/logistics';
import { fiscalLedgerNodeAtom } from '@/store/pillars/compliance';
import { updateNexusNode } from '@/store/pillars/core';
import { genomeValidator } from '@/lib/GenomeValidator';
import { ImmunityAuditLogger } from '@/modules/compliance/securite/ImmunityAuditLogger';
import { DEFAULT_TENANT_ID } from '@/config/instance';

type Store = ReturnType<typeof getDefaultStore>;

const PRIVILEGED_TENANTS = new Set(['restaurant-os', DEFAULT_TENANT_ID, 'vanguard']);

/**
 * Réinitialise les nœuds d'état critiques (orders / stocks / fiscalLedger) à vide.
 * Utilisé quand un gate bloque la synchronisation.
 */
function clearCoreNodes(store: Store, patch: { error?: string } = {}): void {
  store.set(ordersNodeAtom,       (prev) => updateNexusNode(prev, { data: [], loading: false, ...patch }));
  store.set(stockItemsNodeAtom,   (prev) => updateNexusNode(prev, { data: [], loading: false, ...patch }));
  store.set(fiscalLedgerNodeAtom, (prev) => updateNexusNode(prev, { data: [], loading: false, ...patch }));
}

/**
 * 🛡️ Privacy Shield (Grade X).
 * Bloque la synchronisation si le tenant n'a pas l'accès support accordé.
 * @returns true si l'init peut continuer, false si l'accès est restreint (init abandonné).
 */
export async function evaluatePrivacyGate(tenantId: string, store: Store): Promise<boolean> {
  const { fleetSnapshotAtom } = await import('@/store/pillars/sovereign');
  const instances = (store.get(fleetSnapshotAtom) || []) as import('@/shared/types/empire').EmpireInstance[];
  const instance = instances.find(i => i.key === tenantId);

  const isRestricted = !PRIVILEGED_TENANTS.has(tenantId) &&
                       !!instance &&
                       !instance.security?.supportAccessGranted;

  if (isRestricted) {
    logger.warn(`[NexusSyncService] ACCESS RESTRICTED for tenant ${tenantId}.`);
    clearCoreNodes(store);
    return false;
  }
  return true;
}

/**
 * 🧬 Genome Health Gate (Grade IX).
 * Bloque la synchronisation si l'ADN du module n'autorise pas SYNC_STATE.
 * @returns true si l'init peut continuer, false si l'intégrité génome échoue.
 */
export async function evaluateGenomeGate(tenantId: string, store: Store): Promise<boolean> {
  const genomeCheck = genomeValidator.validatePower('DASHBOARD', 'SYNC_STATE');
  if (genomeCheck.allowed) return true;

  logger.error(`[NexusSyncService] GENOME HEALTH GATE FAILED: ${genomeCheck.reason}`);
  await ImmunityAuditLogger.log({
    moduleId: genomeCheck.moduleId,
    attemptedPower: genomeCheck.action,
    reason: genomeCheck.reason === 'AUTHORIZED' ? 'UNKNOWN' : genomeCheck.reason,
    blockedDependency: genomeCheck.blockedDependency,
    tenantId
  });
  clearCoreNodes(store, { error: 'GENOME_INTEGRITY_FAILURE' });
  return false;
}

