}

export function getGuidesForConnector(connectorId: ConnectorId): ExportGuide[] {
  return EXPORT_GUIDES.filter(g => g.connectorId === connectorId);
}

/**
 * imageParser — OCR via LLMManager.generateFromImage (provider agnostique).
 * Supporte JPEG, PNG, WebP, GIF.
 * Retourne le JSON structuré selon la catégorie d'import.
 */

import { LLMManager } from '@/modules/intelligence/ia/ai/LLMManager';
import { AI_MODELS } from '@/modules/intelligence/ia/ai/LLMProviderFactory';
import { getOcrPrompt } from './ocrPrompts';
import type { ImportCategory } from '../types';

export interface OcrResult {
    raw: string;
    parsed: unknown;
    confidence: 'high' | 'medium' | 'low';
}

/**
 * Encode un File/Blob en base64.
 */
async function fileToBase64(file: File | Blob): Promise<string> {
    const buf = await file.arrayBuffer();
    const bytes = new Uint8Array(buf);
    let binary = '';
    for (const b of bytes) binary += String.fromCharCode(b);
    return btoa(binary);
}

/**
 * Détecte le mimeType à partir du fichier.
 */
function detectMimeType(file: File): 'image/jpeg' | 'image/png' | 'image/webp' | 'image/gif' {
    const lower = file.name.toLowerCase();
    if (lower.endsWith('.png')) return 'image/png';
    if (lower.endsWith('.webp')) return 'image/webp';
    if (lower.endsWith('.gif')) return 'image/gif';
    return 'image/jpeg';
}

/**
 * Extrait du JSON depuis la réponse brute du LLM.
 * Robuste aux balises ```json … ``` et au texte parasite.
 */
function extractJSON(raw: string): unknown {
    let text = raw.trim();
    // Supprime les balises markdown code
    text = text.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
    // Essaie de trouver le premier objet JSON
    const start = text.indexOf('{');
    const end = text.lastIndexOf('}');
    if (start !== -1 && end !== -1 && end > start) {
        text = text.slice(start, end + 1);
    }
    return JSON.parse(text);
}

export async function parseImageWithOCR(
    file: File,
    category: ImportCategory,
    additionalContext?: string,
): Promise<OcrResult> {
    const [base64, mimeType] = await Promise.all([
        fileToBase64(file),
        Promise.resolve(detectMimeType(file)),
    ]);

    const prompt = getOcrPrompt(category, additionalContext);

    const response = await LLMManager.provider.generateFromImage({
        model: AI_MODELS.visionFast,
        userPrompt: prompt,
        image: { base64, mimeType },
        temperature: 0.1,
        maxTokens: 4096,
        responseMimeType: 'application/json',
    });

    try {
        const parsed = extractJSON(response.text);
        return { raw: response.text, parsed, confidence: 'high' };
    } catch {
        // JSON invalide — retour en mode low-confidence avec le texte brut
        return { raw: response.text, parsed: null, confidence: 'low' };
    }
}

/**
 * pdfParser — extraction de texte PDF + OCR via LLM agnostique.
 *
 * Stratégie :
 *  1. Essaie d'extraire le texte brut du PDF (PDFs natifs/textuels).
 *  2. Si le texte extrait est trop court (<50 chars), envoie la première page
 *     comme image via LLMManager.generateFromImage (PDF scanné).
 */

import { LLMManager } from '@/modules/intelligence/ia/ai/LLMManager';
import { AI_MODELS } from '@/modules/intelligence/ia/ai/LLMProviderFactory';
import { getOcrPrompt } from './ocrPrompts';
import type { ImportCategory } from '../types';
import type { OcrResult } from './imageParser';

/**
 * Tente d'extraire le texte brut d'un PDF sans dépendance externe.
 * Utilise une regex basique pour lire les streams texte PDF.
 * Fiable pour les PDFs textuels, nul pour les PDFs scannés.
 */
async function extractRawTextFromPDF(file: File): Promise<string> {
    const text = await file.text();
    const matches = text.match(/BT[\s\S]*?ET/g) ?? [];
    const extracted = matches
        .join(' ')
        .replace(/\(([^)]+)\)\s*Tj/g, '$1 ')
        .replace(/[^\x20-\x7EÀ-ɏ]/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
    return extracted;
}

/**
 * Encode le premier "chunk" d'un PDF en base64 pour envoi vision.
 * On envoie les 200 Ko (suffisant pour une page d'un PDF image).
 */
async function pdfFirstPageAsBase64(file: File): Promise<string> {
    const chunk = file.slice(0, 200_000);
    const buf = await chunk.arrayBuffer();
    const bytes = new Uint8Array(buf);
    let binary = '';
    for (const b of bytes) binary += String.fromCharCode(b);
    return btoa(binary);
}

function extractJSON(raw: string): unknown {
    let text = raw.trim();
    text = text.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
    const start = text.indexOf('{');
    const end = text.lastIndexOf('}');
    if (start !== -1 && end !== -1 && end > start) text = text.slice(start, end + 1);
    return JSON.parse(text);
}

export async function parsePDFWithOCR(
    file: File,
    category: ImportCategory,
    additionalContext?: string,
): Promise<OcrResult> {
    const prompt = getOcrPrompt(category, additionalContext);

    // Étape 1 : extraction texte natif
    const rawText = await extractRawTextFromPDF(file);

    if (rawText.length >= 50) {
        // PDF textuel → on envoie le texte directement
        const response = await LLMManager.provider.generateText({
            model: AI_MODELS.fast,
            userPrompt: `${prompt}\n\nContenu du PDF:\n${rawText.slice(0, 15_000)}`,
            temperature: 0.1,
            maxTokens: 4096,
        });
        try {
            const parsed = extractJSON(response.text);
            return { raw: response.text, parsed, confidence: 'high' };
        } catch {
            return { raw: response.text, parsed: null, confidence: 'low' };
        }
    }

    // Étape 2 : PDF scanné → vision LLM
    const base64 = await pdfFirstPageAsBase64(file);
    const response = await LLMManager.provider.generateFromImage({
        model: AI_MODELS.visionFast,
        userPrompt: prompt,
        image: { base64, mimeType: 'application/pdf' },
        temperature: 0.1,
        maxTokens: 4096,
    });

    try {
        const parsed = extractJSON(response.text);
        return { raw: response.text, parsed, confidence: 'medium' };
    } catch {
        return { raw: response.text, parsed: null, confidence: 'low' };
    }
}

'use client';
import React, { useState } from 'react';
import type { ConnectorId, ConnectorCredentials } from '@/modules/commerce/acquisition/onboarding/migration/connectors/types';
import { ConnectorRegistry } from '@/modules/commerce/acquisition/onboarding/migration/connectors';
import { ExportGuidePanel } from '@/modules/commerce/acquisition/onboarding/guides';

interface ConnectorOAuthPanelProps {
  connectorId: ConnectorId;
  onConnected: (credentials: ConnectorCredentials, accountInfo?: Record<string, unknown>) => void;
}

export function ConnectorOAuthPanel({ connectorId, onConnected }: ConnectorOAuthPanelProps) {
  const meta = ConnectorRegistry.get(connectorId).meta;
  const [creds, setCreds] = useState<ConnectorCredentials>({});
  const [testing, setTesting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  const handleTest = async () => {
    setTesting(true);
    setError(null);
    setSuccess(false);
    try {
      const res = await fetch('/api/tenant/onboarding/connector/test', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ provider: connectorId, credentials: creds }),
      });
      const json = await res.json() as { ok?: boolean; error?: string; accountInfo?: Record<string, unknown> };
      if (json.ok) {
        setSuccess(true);
        onConnected(creds, json.accountInfo);
      } else {
        setError(json.error ?? 'Connexion échouée');
      }
    } catch {
      setError('Erreur réseau');
    } finally {
      setTesting(false);
    }
  };

  return (
    <div className="bg-white rounded-xl border border-gray-200 p-6 space-y-5">
      <div className="flex items-center gap-3">
        <span className="text-3xl">{meta.logo}</span>
        <div>
          <h3 className="font-semibold text-gray-900">{meta.displayName}</h3>
          <p className="text-xs text-gray-500">
            {meta.authMethod === 'api_key' ? 'Clé API requise' : 'Authentification OAuth2'}
          </p>
        </div>
      </div>

      {meta.exportGuide && (
        <div className="bg-amber-50 border border-amber-200 rounded-lg p-3 text-xs text-amber-800">
          💡 {meta.exportGuide}
        </div>
      )}

      <div className="space-y-3">
        {meta.authMethod === 'api_key' && (
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Clé API</label>
            <input
              type="password"
              placeholder="sk-..."
              className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-400"
              value={creds.apiKey ?? ''}
              onChange={(e) => setCreds({ ...creds, apiKey: e.target.value })}
            />
          </div>
        )}

        {meta.authMethod === 'oauth2' && meta.oauthUrl && (
          <a
            href={meta.oauthUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="block w-full text-center px-4 py-2 bg-indigo-600 text-white rounded-lg text-sm hover:bg-indigo-700 transition-colors"
          >
            Connecter via OAuth →
          </a>
        )}

        {meta.authMethod === 'basic' && (
          <>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Identifiant</label>
              <input
                type="text"
                className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-400"
                value={creds.clientId ?? ''}
                onChange={(e) => setCreds({ ...creds, clientId: e.target.value })}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Mot de passe</label>
              <input
                type="password"
                className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-400"
                value={creds.clientSecret ?? ''}
                onChange={(e) => setCreds({ ...creds, clientSecret: e.target.value })}
              />
            </div>
          </>
        )}
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 rounded-lg p-3 text-sm text-red-700">
          ❌ {error}
        </div>
      )}

      {success && (
        <div className="bg-emerald-50 border border-emerald-200 rounded-lg p-3 text-sm text-emerald-700">
          ✅ Connexion établie avec succès
        </div>
      )}

      {meta.authMethod !== 'oauth2' && (
        <button
          onClick={handleTest}
          disabled={testing}
          className="w-full py-2 bg-indigo-600 text-white rounded-lg text-sm font-medium hover:bg-indigo-700 transition-colors disabled:opacity-60"
        >
          {testing ? 'Test en cours…' : 'Tester la connexion'}
        </button>
      )}

      <ExportGuidePanel connectorId={connectorId} />

      {meta.guideUrl && (
        <a
          href={meta.guideUrl}
          target="_blank"
          rel="noopener noreferrer"
          className="block text-center text-xs text-indigo-500 hover:underline"
        >
          Comment trouver ma clé API ?
        </a>
      )}
    </div>
  );
}

'use client';
