  category: ImportCategory;
  categoryLabel: string;
  categoryIcon: string;
  connectorId?: ConnectorId;
  connectorCredentials?: ConnectorCredentials;
  onImported: (result: { created: number; snapshotId?: string }) => void;
}

type PanelState = 'idle' | 'preview' | 'importing' | 'done' | 'error';

interface PreviewData {
  rows: Record<string, string>[];
  confidence: 'high' | 'medium' | 'low';
  source: 'ocr' | 'api';
  fileName?: string;
}

export function ImportCategoryPanel({
  category,
  categoryLabel,
  categoryIcon,
  connectorId,
  connectorCredentials,
  onImported,
}: ImportCategoryPanelProps) {
  const [state, setState] = useState<PanelState>('idle');
  const [preview, setPreview] = useState<PreviewData | null>(null);
  const [progress, setProgress] = useState(0);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [rows, setRows] = useState<Record<string, string>[]>([]);

  const handleOcrResult = useCallback((result: { rows: Record<string, string>[]; confidence: 'high' | 'medium' | 'low'; fileName: string }) => {
    setRows(result.rows);
    setPreview({ rows: result.rows, confidence: result.confidence, source: 'ocr', fileName: result.fileName });
    setState('preview');
  }, []);

  const pullFromConnector = useCallback(async () => {
    if (!connectorId || !connectorCredentials) return;
    setState('importing');
    setProgress(10);
    try {
      const res = await fetch('/api/tenant/onboarding/connector/pull', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ provider: connectorId, category, credentials: connectorCredentials, autoImport: false }),
      });
      const json = await res.json() as { preview?: Record<string, string>[]; error?: string };
      if (!res.ok) throw new Error(json.error ?? 'Erreur API');
      setRows(json.preview ?? []);
      setPreview({ rows: json.preview ?? [], confidence: 'high', source: 'api' });
      setProgress(40);
      setState('preview');
    } catch (err) {
      setErrorMsg(toError(err).message);
      setState('error');
    }
  }, [connectorId, connectorCredentials, category]);

  const confirmImport = useCallback(async () => {
    setState('importing');
    setProgress(0);
    try {
      const formData = new FormData();
      const csvContent = [
        Object.keys(rows[0] ?? {}).join(','),
        ...rows.map(r => Object.values(r).map(v => `"${v}"`).join(',')),
      ].join('\n');
      const blob = new Blob([csvContent], { type: 'text/csv' });
      formData.append('file', blob, `${category}_import.csv`);
      formData.append('category', category);

      const interval = setInterval(() => setProgress(p => Math.min(p + 5, 85)), 500);
      const res = await fetch('/api/tenant/onboarding/ocr', { method: 'POST', body: formData });
      clearInterval(interval);

      const json = await res.json() as { snapshotId?: string; created?: number; error?: string };
      if (!res.ok) throw new Error(json.error ?? 'Erreur import');

      setProgress(100);
      setState('done');
      onImported({ created: json.created ?? rows.length, snapshotId: json.snapshotId });
    } catch (err) {
      setErrorMsg(toError(err).message);
      setState('error');
    }
  }, [rows, category, onImported]);

  const confidenceColor = {
    high: 'text-emerald-600',
    medium: 'text-amber-600',
    low: 'text-red-500',
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2">
        <span className="text-xl">{categoryIcon}</span>
        <h3 className="font-semibold text-gray-900">{categoryLabel}</h3>
      </div>

      {state === 'idle' && (
        <div className="space-y-4">
          {connectorId && connectorCredentials && (
            <button
              onClick={pullFromConnector}
              className="w-full py-3 px-4 bg-indigo-600 text-white rounded-xl font-medium text-sm hover:bg-indigo-700 transition-colors flex items-center justify-center gap-2"
            >
              <span>🔗</span> Importer depuis le connecteur
            </button>
          )}
          <div className="relative">
            {connectorId && <div className="text-xs text-center text-gray-400 mb-3">— ou glissez un fichier —</div>}
            <OCRUploadZone
              category={category}
              onResult={handleOcrResult}
              onError={(msg) => { setErrorMsg(msg); setState('error'); }}
            />
          </div>
        </div>
      )}

      {state === 'preview' && preview && (
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <div className="text-sm text-gray-600">
              <span className="font-medium">{rows.length} lignes</span> détectées —{' '}
              <span className={`font-medium ${confidenceColor[preview.confidence]}`}>
                confiance {preview.confidence === 'high' ? 'haute' : preview.confidence === 'medium' ? 'moyenne' : 'faible'}
              </span>
            </div>
            {preview.confidence === 'low' && (
              <span className="text-xs bg-red-50 text-red-600 px-2 py-1 rounded">Vérifiez les données</span>
            )}
          </div>

          <PreviewTable
            rows={rows}
            onRowChange={(idx, updated) => {
              setRows(r => r.map((row, i) => i === idx ? updated : row));
            }}
          />

          <div className="flex gap-3">
            <button
              onClick={() => { setState('idle'); setPreview(null); }}
              className="flex-1 py-2 border border-gray-300 text-gray-700 rounded-xl text-sm hover:bg-gray-50 transition-colors"
            >
              ← Recommencer
            </button>
            <button
              onClick={confirmImport}
              className="flex-1 py-2 bg-emerald-600 text-white rounded-xl text-sm font-medium hover:bg-emerald-700 transition-colors"
            >
              ✓ Confirmer et importer
            </button>
          </div>
        </div>
      )}

      {state === 'importing' && (
        <div className="space-y-3 py-4">
          <div className="w-full bg-gray-200 rounded-full h-2">
            <div
              className="bg-indigo-500 h-2 rounded-full transition-all duration-500"
              style={{ width: `${progress}%` }}
            />
          </div>
          <p className="text-sm text-center text-gray-500">Import en cours… {progress}%</p>
        </div>
      )}

      {state === 'done' && (
        <div className="bg-emerald-50 border border-emerald-200 rounded-xl p-4 text-center">
          <div className="text-2xl mb-1">✅</div>
          <p className="font-medium text-emerald-800">Import terminé</p>
          <p className="text-sm text-emerald-600 mt-1">{rows.length} enregistrements importés</p>
          <button
            onClick={() => setState('idle')}
            className="mt-3 text-xs text-emerald-700 underline"
          >
            Importer d&apos;autres données
          </button>
        </div>
      )}

      {state === 'error' && (
        <div className="bg-red-50 border border-red-200 rounded-xl p-4 text-center space-y-3">
          <div className="text-2xl">❌</div>
          <p className="text-sm text-red-700">{errorMsg}</p>
          <button
            onClick={() => { setState('idle'); setErrorMsg(null); }}
            className="px-4 py-2 bg-red-600 text-white rounded-lg text-sm hover:bg-red-700 transition-colors"
          >
            Réessayer
          </button>
        </div>
      )}
    </div>
  );
}

'use client';
import React, { useCallback, useRef, useState } from 'react';
import type { ImportCategory } from '@/modules/commerce/acquisition/onboarding/migration/types';
import { toError } from "@/lib/toError";

interface OcrResult {
  rows: Record<string, string>[];
  confidence: 'high' | 'medium' | 'low';
  rawText?: string;
}

interface OCRUploadZoneProps {
  category: ImportCategory;
  onResult: (result: OcrResult & { fileName: string }) => void;
  onError?: (msg: string) => void;
}

export function OCRUploadZone({ category, onResult, onError }: OCRUploadZoneProps) {
  const [dragging, setDragging] = useState(false);
  const [loading, setLoading] = useState(false);
  const [fileName, setFileName] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const upload = useCallback(async (file: File) => {
    setFileName(file.name);
    setLoading(true);
    try {
      const fd = new FormData();
      fd.append('file', file);
      fd.append('category', category);

      const res = await fetch('/api/tenant/onboarding/ocr', { method: 'POST', body: fd });
      const json = await res.json() as { rows?: Record<string, string>[]; confidence?: string; rawText?: string; error?: string };
      if (!res.ok) throw new Error(json.error ?? 'Erreur OCR');
      onResult({
        rows: json.rows ?? [],
        confidence: (json.confidence ?? 'low') as OcrResult['confidence'],
        rawText: json.rawText,
        fileName: file.name,
      });
    } catch (err) {
      onError?.(toError(err).message);
    } finally {
      setLoading(false);
    }
  }, [category, onResult, onError]);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setDragging(false);
    const file = e.dataTransfer.files[0];
    if (file) upload(file);
  }, [upload]);

  const handleChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) upload(file);
  }, [upload]);

  const confidenceBadge = (c: 'high' | 'medium' | 'low') => ({
    high: 'bg-emerald-100 text-emerald-700',
    medium: 'bg-amber-100 text-amber-700',
    low: 'bg-red-100 text-red-700',
  }[c]);

  return (
    <div
      onDragOver={(e) => { e.preventDefault(); setDragging(true); }}
      onDragLeave={() => setDragging(false)}
      onDrop={handleDrop}
      className={[
        'relative border-2 border-dashed rounded-xl p-8 text-center cursor-pointer transition-all',
        dragging ? 'border-indigo-400 bg-indigo-50' : 'border-gray-300 hover:border-indigo-300 hover:bg-gray-50',
      ].join(' ')}
      onClick={() => inputRef.current?.click()}
    >
      <input
        ref={inputRef}
        type="file"
        className="hidden"
        accept=".pdf,.png,.jpg,.jpeg,.webp,.csv,.xlsx,.xls"
        onChange={handleChange}
      />

      {loading ? (
        <div className="flex flex-col items-center gap-3">
          <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin" />
          <p className="text-sm text-gray-500">Analyse OCR en cours…</p>
        </div>
      ) : (
        <div className="flex flex-col items-center gap-3">
          <div className="text-4xl">📄</div>
          <div>
            <p className="font-medium text-gray-700">
              {fileName ? `✓ ${fileName}` : 'Déposez un fichier ici'}
            </p>
            <p className="text-xs text-gray-400 mt-1">PDF, image (JPG/PNG), CSV ou Excel — max 10 Mo</p>
          </div>
          {!fileName && (
            <button className="px-4 py-2 bg-indigo-600 text-white text-sm rounded-lg hover:bg-indigo-700 transition-colors">
              Parcourir
            </button>
          )}
        </div>
      )}
    </div>
  );
}

'use client';
import React, { useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import type { ConnectorId, ConnectorCredentials } from '@/modules/commerce/acquisition/onboarding/migration/connectors/types';
import type { ImportCategory } from '@/modules/commerce/acquisition/onboarding/migration/types';
import type { OnboardingMode } from '@/shared/nexus/contracts/onboarding.types';
import { ProgressStepper, type WizardStep } from './ProgressStepper';
import { SourceSystemSelector } from './SourceSystemSelector';
import { ConnectorOAuthPanel } from './ConnectorOAuthPanel';
import { ImportCategoryPanel } from './ImportCategoryPanel';
import { SimpleFloorPlanEditor, type SimpleTable, type SimpleZone } from './SimpleFloorPlanEditor';
import { OnboardingHelpButton } from './OnboardingHelpButton';

interface ImportEntry {
  category: ImportCategory;
  label: string;
  icon: string;
  requiredForZero: boolean;
  requiredForMigration: boolean;
}

const IMPORT_ENTRIES: ImportEntry[] = [
  { category: 'menu',         label: 'Menu & Produits',     icon: '🍽️',  requiredForZero: true,  requiredForMigration: true },
  { category: 'floorplan',    label: 'Plan de salle',       icon: '🪑',  requiredForZero: true,  requiredForMigration: false },
  { category: 'staff',        label: 'Équipe',              icon: '👥',  requiredForZero: true,  requiredForMigration: true },
  { category: 'suppliers',    label: 'Fournisseurs',        icon: '🏭',  requiredForZero: false, requiredForMigration: true },
  { category: 'inventory',    label: 'Stocks initiaux',     icon: '📦',  requiredForZero: false, requiredForMigration: true },
  { category: 'crm',          label: 'Clients CRM',        icon: '👤',  requiredForZero: false, requiredForMigration: true },
  { category: 'reservations', label: 'Historique résa',    icon: '📅',  requiredForZero: false, requiredForMigration: true },
  { category: 'fec',          label: 'FEC Comptable',       icon: '📊',  requiredForZero: false, requiredForMigration: true },
  { category: 'statements',   label: 'Relevés bancaires',   icon: '🏦',  requiredForZero: false, requiredForMigration: false },
  { category: 'recipes',      label: 'Recettes',            icon: '📋',  requiredForZero: false, requiredForMigration: false },
];

type WizardStepId = 'mode' | 'source' | 'connect' | 'import' | 'done';

const WIZARD_STEPS: WizardStep[] = [
  { id: 'mode',    label: 'Profil',    icon: '🏪' },
  { id: 'source',  label: 'Source',   icon: '🔌' },
  { id: 'connect', label: 'Connexion', icon: '🔑' },
  { id: 'import',  label: 'Import',   icon: '📥' },
  { id: 'done',    label: 'Prêt',     icon: '🚀' },
];

export function OnboardingWizard() {
  const router = useRouter();
  const [currentStep, setCurrentStep] = useState<WizardStepId>('mode');
  const [completedSteps, setCompletedSteps] = useState<WizardStepId[]>([]);
  const [mode, setMode] = useState<OnboardingMode | null>(null);
  const [connectorId, setConnectorId] = useState<ConnectorId | null>(null);
  const [credentials, setCredentials] = useState<ConnectorCredentials | null>(null);
  const [importedCategories, setImportedCategories] = useState<ImportCategory[]>([]);
  const [activeCategory, setActiveCategory] = useState<ImportCategory | null>(null);

  const complete = (step: WizardStepId, next: WizardStepId) => {
    setCompletedSteps(s => [...s, step]);
    setCurrentStep(next);
  };

  const handleModeSelect = (m: OnboardingMode) => {
    setMode(m);
    if (m === 'from_zero') {
      complete('mode', 'import');
    } else {
      complete('mode', 'source');
    }
    void fetch('/api/tenant/onboarding/status', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ mode: m }),
    });
  };

  const handleSourceSelect = (id: ConnectorId) => {
    setConnectorId(id);
    complete('source', 'connect');
  };

  const handleConnected = (creds: ConnectorCredentials) => {
    setCredentials(creds);
    complete('connect', 'import');
  };

  const handleImported = useCallback((cat: ImportCategory) => {
    setImportedCategories(prev => prev.includes(cat) ? prev : [...prev, cat]);
  }, []);

  const handleDone = () => {
    complete('import', 'done');
    void fetch('/api/tenant/onboarding/status', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ completedAt: new Date().toISOString() }),
    });
  };

  const relevantEntries = IMPORT_ENTRIES.filter(e =>
    mode === 'from_zero' ? e.requiredForZero : e.requiredForMigration
  );

  const requiredDone = relevantEntries
    .filter(e => mode === 'from_zero' ? e.requiredForZero : e.requiredForMigration)
    .every(e => importedCategories.includes(e.category));

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-3xl mx-auto px-4 py-8">
        {/* Header */}
        <div className="mb-8 text-center">
          <div className="text-4xl mb-2">🚀</div>
          <h1 className="text-2xl font-bold text-gray-900">Bienvenue sur Restaurant OS</h1>
          <p className="text-gray-500 mt-1">Quelques étapes pour être prêt à ouvrir</p>
        </div>

        {/* Stepper */}
        <div className="bg-white rounded-2xl shadow-sm border border-gray-200 p-6 mb-6">
          <ProgressStepper
            steps={WIZARD_STEPS.filter(s =>
              mode !== 'from_zero' || !['source', 'connect'].includes(s.id)
            )}
            currentStep={currentStep}
            completedSteps={completedSteps}
          />
        </div>

        {/* Step content */}
        <div className="bg-white rounded-2xl shadow-sm border border-gray-200 p-6">
          {/* STEP: MODE */}
          {currentStep === 'mode' && (
            <div className="space-y-4">
              <h2 className="text-lg font-semibold text-gray-900">Comment souhaitez-vous démarrer ?</h2>
              <p className="text-sm text-gray-500">Votre choix détermine le parcours d&apos;installation</p>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mt-4">
                <button
                  onClick={() => handleModeSelect('from_zero')}
                  className="p-5 rounded-xl border-2 border-gray-200 hover:border-indigo-400 hover:bg-indigo-50 text-left transition-all group"
                >
                  <div className="text-3xl mb-2">✨</div>
                  <div className="font-semibold text-gray-800 group-hover:text-indigo-700">Démarrer de zéro</div>
                  <p className="text-sm text-gray-500 mt-1">Nouveau restaurant ou nouvelle activité</p>
                  <ul className="mt-3 space-y-1 text-xs text-gray-400">
                    <li>✓ Menu à créer</li>
                    <li>✓ Plan de salle à configurer</li>
                    <li>✓ Équipe à ajouter</li>
                  </ul>
                </button>
                <button
                  onClick={() => handleModeSelect('migration')}
                  className="p-5 rounded-xl border-2 border-gray-200 hover:border-indigo-400 hover:bg-indigo-50 text-left transition-all group"
                >
                  <div className="text-3xl mb-2">🔄</div>
                  <div className="font-semibold text-gray-800 group-hover:text-indigo-700">Migrer depuis un autre logiciel</div>
                  <p className="text-sm text-gray-500 mt-1">Importer vos données existantes</p>
                  <ul className="mt-3 space-y-1 text-xs text-gray-400">
                    <li>✓ Menu & produits</li>
                    <li>✓ Clients & historique</li>
                    <li>✓ Comptabilité</li>
                  </ul>
                </button>
              </div>
            </div>
          )}

          {/* STEP: SOURCE */}
          {currentStep === 'source' && (
            <div className="space-y-4">
              <h2 className="text-lg font-semibold text-gray-900">Quel logiciel utilisez-vous actuellement ?</h2>
              <p className="text-sm text-gray-500">
                Sélectionnez votre caisse, logiciel de réservation ou de comptabilité
              </p>
              <SourceSystemSelector selected={connectorId} onSelect={handleSourceSelect} />
            </div>
          )}

          {/* STEP: CONNECT */}
          {currentStep === 'connect' && connectorId && (
            <div className="space-y-4">
              <h2 className="text-lg font-semibold text-gray-900">Connectez votre compte</h2>
              <ConnectorOAuthPanel
                connectorId={connectorId}
                onConnected={handleConnected}
              />
              <button
                onClick={() => { setCurrentStep('import'); setCompletedSteps(s => [...s, 'connect']); }}
                className="w-full text-center text-sm text-gray-400 hover:text-gray-600 mt-2"
              >
                Je préfère importer des fichiers manuellement →
              </button>
            </div>
          )}

          {/* STEP: IMPORT */}
          {currentStep === 'import' && (
            <div className="space-y-6">
              <div className="flex items-center justify-between">
                <h2 className="text-lg font-semibold text-gray-900">Import des données</h2>
                <span className="text-sm text-gray-500">
                  {importedCategories.length}/{relevantEntries.length} catégories
                </span>
              </div>

              {/* Category tabs */}
              <div className="flex flex-wrap gap-2">
                {relevantEntries.map(entry => {
                  const done = importedCategories.includes(entry.category);
                  const active = activeCategory === entry.category;
                  return (
                    <button
                      key={entry.category}
                      onClick={() => setActiveCategory(active ? null : entry.category)}
                      className={[
                        'px-3 py-1.5 rounded-lg text-sm font-medium transition-all flex items-center gap-1.5',
                        done ? 'bg-emerald-100 text-emerald-700' :
                          active ? 'bg-indigo-100 text-indigo-700' :
                          'bg-gray-100 text-gray-600 hover:bg-gray-200',
                      ].join(' ')}
                    >
                      <span>{entry.icon}</span>
                      <span>{entry.label}</span>
                      {done && <span className="text-xs">✓</span>}
                    </button>
                  );
                })}
              </div>

              {/* Active category panel */}
              {activeCategory && activeCategory !== 'floorplan' && (
                <div className="border border-gray-200 rounded-xl p-4">
                  <ImportCategoryPanel
                    category={activeCategory}
                    categoryLabel={relevantEntries.find(e => e.category === activeCategory)?.label ?? activeCategory}
                    categoryIcon={relevantEntries.find(e => e.category === activeCategory)?.icon ?? '📄'}
                    connectorId={connectorId ?? undefined}
                    connectorCredentials={credentials ?? undefined}
                    onImported={() => {
                      handleImported(activeCategory);
                      setActiveCategory(null);
                    }}
                  />
                </div>
              )}

              {/* Floor plan editor — special case */}
              {activeCategory === 'floorplan' && (
                <div className="border border-gray-200 rounded-xl p-4">
                  <div className="flex items-center gap-2 mb-4">
                    <span className="text-xl">🪑</span>
                    <h3 className="font-semibold text-gray-900">Plan de salle</h3>
                  </div>
                  <SimpleFloorPlanEditor
                    onSave={async (tables: SimpleTable[], zones: SimpleZone[]) => {
                      await fetch('/api/tenant/onboarding/status', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ steps: { floorplan: { status: 'completed', source: 'manual', importResult: { created: tables.length, updated: 0, skipped: 0, errors: 0 } } } }),
                      });
                      handleImported('floorplan');
                      setActiveCategory(null);
                    }}
                  />
                </div>
              )}

              {!activeCategory && (
                <div className="text-center py-4 text-sm text-gray-400">
                  Cliquez sur une catégorie pour importer ses données
                </div>
              )}

              <div className="flex items-center justify-between pt-4 border-t border-gray-100">
                <p className="text-xs text-gray-400">
                  Les catégories facultatives peuvent être complétées plus tard
                </p>
                <button
                  onClick={handleDone}
                  disabled={!requiredDone && importedCategories.length === 0}
                  className="px-6 py-2 bg-indigo-600 text-white rounded-xl text-sm font-medium hover:bg-indigo-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  Continuer →
                </button>
              </div>
            </div>
          )}

          {/* STEP: DONE */}
          {currentStep === 'done' && (
            <div className="text-center py-8 space-y-4">
              <div className="text-5xl">🎉</div>
              <h2 className="text-xl font-bold text-gray-900">Vous êtes prêt à ouvrir !</h2>
              <p className="text-gray-500 text-sm max-w-sm mx-auto">
                {importedCategories.length} catégorie{importedCategories.length > 1 ? 's' : ''} importée{importedCategories.length > 1 ? 's' : ''}.
                Vous pouvez compléter le reste depuis les paramètres à tout moment.
              </p>
              <div className="flex flex-col sm:flex-row gap-3 justify-center mt-6">
                <button
                  onClick={() => router.push('/pos')}
                  className="px-6 py-3 bg-indigo-600 text-white rounded-xl font-semibold hover:bg-indigo-700 transition-colors"
                >
                  Ouvrir la caisse
                </button>
                <button
                  onClick={() => router.push('/dashboard')}
                  className="px-6 py-3 border border-gray-300 text-gray-700 rounded-xl font-medium hover:bg-gray-50 transition-colors"
                >
                  Aller au tableau de bord
                </button>
              </div>
            </div>
          )}
        </div>

        {/* Footer: aide + rollback hint */}
        {currentStep !== 'done' && (
          <div className="flex items-center justify-between mt-4">
            <OnboardingHelpButton currentStep={currentStep} category={activeCategory ?? undefined} />
            {importedCategories.length > 0 && (
              <p className="text-xs text-gray-400">
                Chaque import est sauvegardé — annulation possible depuis les paramètres
              </p>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

'use client';
import React from 'react';
import type { ConnectorId } from '@/modules/commerce/acquisition/onboarding/migration/connectors/types';
import { ConnectorRegistry } from '@/modules/commerce/acquisition/onboarding/migration/connectors';

interface SourceSystemSelectorProps {
  selected: ConnectorId | null;
  onSelect: (id: ConnectorId) => void;
}

const CONNECTOR_GROUPS = [
  {
    label: 'Logiciels de caisse',
    ids: ['zelty', 'laddition', 'lightspeed', 'tiller', 'cashpad', 'popina'] as ConnectorId[],
  },
  {
    label: 'Réservations & gestion de salle',
    ids: ['zenchef', 'thefork'] as ConnectorId[],
  },
  {
    label: 'Comptabilité',
    ids: ['pennylane', 'sage'] as ConnectorId[],
  },
];

export function SourceSystemSelector({ selected, onSelect }: SourceSystemSelectorProps) {
  return (
    <div className="space-y-6">
      {CONNECTOR_GROUPS.map(group => {
        const connectors = group.ids
          .map(id => {
            try { return ConnectorRegistry.get(id); } catch { return null; }
          })
          .filter(Boolean);

        if (!connectors.length) return null;

        return (
          <div key={group.label}>
            <h4 className="text-xs font-semibold uppercase tracking-wider text-gray-400 mb-3">
              {group.label}
            </h4>
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
              {connectors.map(connector => {
                if (!connector) return null;
                const { meta } = connector;
                const isSelected = selected === meta.id;
                return (
                  <button
                    key={meta.id}
                    onClick={() => onSelect(meta.id)}
                    className={[
                      'flex items-center gap-3 p-3 rounded-xl border-2 text-left transition-all',
                      isSelected
                        ? 'border-indigo-500 bg-indigo-50'
                        : 'border-gray-200 hover:border-indigo-200 hover:bg-gray-50',
                    ].join(' ')}
                  >
                    <span className="text-2xl shrink-0">{meta.logo}</span>
                    <div>
                      <div className="text-sm font-medium text-gray-800">{meta.displayName}</div>
                      <div className="text-xs text-gray-400">
                        {meta.availableCategories.length} catégorie{meta.availableCategories.length > 1 ? 's' : ''}
                      </div>
                    </div>
                    {isSelected && (
                      <div className="ml-auto text-indigo-500 text-sm font-bold">✓</div>
                    )}
                  </button>
                );
              })}
            </div>
          </div>
        );
      })}

      <div>
        <h4 className="text-xs font-semibold uppercase tracking-wider text-gray-400 mb-3">
          Autre / Import manuel
        </h4>
        <button
          onClick={() => onSelect('zelty')}
          className={[
            'w-full flex items-center gap-3 p-3 rounded-xl border-2 text-left transition-all',
            !selected ? 'border-gray-300 bg-gray-50' : 'border-gray-200 hover:border-gray-300',
          ].join(' ')}
        >
          <span className="text-2xl">📁</span>
          <div>
            <div className="text-sm font-medium text-gray-700">CSV / Excel / PDF</div>
            <div className="text-xs text-gray-400">Import direct ou OCR si fichier scanné</div>
          </div>
        </button>
      </div>
    </div>
  );
}

