import { Nexus } from '@/lib/nexus/NexusAdapter';
import { GiftCardSchema, GiftCardTransactionSchema, type GiftCard, type GiftCardTransaction } from '@/modules/commerce/domain/schemas/giftcard';
import { toMicrounits, type Microunits } from '@/shared/schemas/primitives';

function generateCode(): string {
    const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    let code = '';
    const arr = new Uint8Array(16);
    crypto.getRandomValues(arr);
    for (let i = 0; i < 16; i++) {
        code += chars[arr[i] % chars.length];
        if (i === 3 || i === 7 || i === 11) code += '-';
    }
    return code;
}

export const GiftCardService = {
    async issue(
        tenantId: string,
        amountInMicrounits: Microunits,
        operatorId: string,
        opts?: { recipientName?: string; recipientEmail?: string; expiresAt?: string }
    ): Promise<GiftCard> {
        const id = Nexus.adapter.generateId(`tenants/${tenantId}/giftCards`);
        const code = generateCode();

        const card: GiftCard = {
            id,
            tenantId,
            code,
            balanceInMicrounits: amountInMicrounits,
            initialAmountInMicrounits: amountInMicrounits,
            status: 'active',
            recipientName: opts?.recipientName,
            recipientEmail: opts?.recipientEmail,
            issuedAt: Date.now(),
            expiresAt: opts?.expiresAt,
        };

        GiftCardSchema.parse(card);

        await Nexus.adapter.set(
            `tenants/${tenantId}/giftCards/${id}`,
            card
        );

        await this._logTransaction(tenantId, {
            giftCardId: id,
            type: 'issue',
            amountInMicrounits,
            balanceAfterInMicrounits: amountInMicrounits,
            operatorId,
        });

        return card;
    },

    async redeem(
        tenantId: string,
        code: string,
        amountInMicrounits: Microunits,
        operatorId: string,
        orderId?: string
    ): Promise<{ card: GiftCard; redeemed: Microunits }> {
        const cards = await Nexus.adapter.query<GiftCard>(
            `tenants/${tenantId}/giftCards`,
            { where: [{ field: 'code', operator: '==', value: code }] }
        );

        const card = cards[0];
        if (!card) throw new Error('Carte cadeau introuvable');
        if (card.status !== 'active') throw new Error(`Carte ${card.status}`);
        if (card.expiresAt && new Date(card.expiresAt) < new Date()) throw new Error('Carte expirée');

        const redeemed = toMicrounits(Math.min(amountInMicrounits, card.balanceInMicrounits));
        const newBalance = toMicrounits(card.balanceInMicrounits - redeemed);
        const newStatus = newBalance === 0 ? 'depleted' : 'active';

        await Nexus.adapter.update(
            `tenants/${tenantId}/giftCards/${card.id}`,
            {
                balanceInMicrounits: newBalance,
                status: newStatus,
                lastUsedAt: new Date().toISOString(),
            }
        );

        await this._logTransaction(tenantId, {
            giftCardId: card.id,
            type: 'redeem',
            amountInMicrounits: redeemed,
            balanceAfterInMicrounits: newBalance,
            operatorId,
            orderId,
        });

        return { card: { ...card, balanceInMicrounits: newBalance, status: newStatus as GiftCard['status'] }, redeemed };
    },

    async getByCode(tenantId: string, code: string): Promise<GiftCard | null> {
        const cards = await Nexus.adapter.query<GiftCard>(
            `tenants/${tenantId}/giftCards`,
            { where: [{ field: 'code', operator: '==', value: code }] }
        );
        return cards[0] ?? null;
    },

    async _logTransaction(
        tenantId: string,
        data: Omit<GiftCardTransaction, 'id' | 'tenantId' | 'timestamp'>
    ): Promise<void> {
        const id = Nexus.adapter.generateId(`tenants/${tenantId}/giftCardTransactions`);
        const tx: GiftCardTransaction = {
            id,
            tenantId,
            ...data,
            timestamp: Date.now(),
        };
        GiftCardTransactionSchema.parse(tx);
        await Nexus.adapter.set(
            `tenants/${tenantId}/giftCardTransactions/${id}`,
            tx
        );
    },
};

import { Nexus } from '@/lib/nexus/NexusAdapter';
import {
    LoyaltyAccountSchema,
    LoyaltyTransactionSchema,
    TIER_THRESHOLDS,
    type LoyaltyAccount,
    type LoyaltyTransaction,
    type LoyaltyTier,
} from '@/modules/commerce/domain/schemas/loyalty';
import type { Microunits } from '@/shared/schemas/primitives';

function resolveTier(lifetimePoints: number): LoyaltyTier {
    if (lifetimePoints >= TIER_THRESHOLDS.platinum) return 'platinum';
    if (lifetimePoints >= TIER_THRESHOLDS.gold) return 'gold';
    if (lifetimePoints >= TIER_THRESHOLDS.silver) return 'silver';
    return 'bronze';
}

const POINTS_PER_EURO = 1;

export const LoyaltyEngine = {
    async getOrCreate(tenantId: string, subjectId: string): Promise<LoyaltyAccount> {
        const existing = await Nexus.adapter.query<LoyaltyAccount>(
            `tenants/${tenantId}/loyaltyAccounts`,
            { where: [{ field: 'subjectId', operator: '==', value: subjectId }] }
        );
        if (existing[0]) return existing[0];

        const id = Nexus.adapter.generateId(`tenants/${tenantId}/loyaltyAccounts`);
        const account: LoyaltyAccount = {
            id,
            tenantId,
            subjectId,
            points: 0,
            lifetimePoints: 0,
            tier: 'bronze',
            createdAt: Date.now(),
        };
        LoyaltyAccountSchema.parse(account);
        await Nexus.adapter.set(
            `tenants/${tenantId}/loyaltyAccounts/${id}`,
            account
        );
        return account;
    },

    async earn(
        tenantId: string,
        subjectId: string,
        totalInMicrounits: Microunits,
        orderId?: string
    ): Promise<{ pointsEarned: number; newBalance: number; tier: LoyaltyTier }> {
        const account = await this.getOrCreate(tenantId, subjectId);
        const euros = totalInMicrounits / 1_000_000;
        const pointsEarned = Math.floor(euros * POINTS_PER_EURO);

        if (pointsEarned <= 0) return { pointsEarned: 0, newBalance: account.points, tier: account.tier };

        const newBalance = account.points + pointsEarned;
        const newLifetime = account.lifetimePoints + pointsEarned;
        const tier = resolveTier(newLifetime);

        await Nexus.adapter.update(
            `tenants/${tenantId}/loyaltyAccounts/${account.id}`,
            { points: newBalance, lifetimePoints: newLifetime, tier, lastEarnedAt: new Date().toISOString() }
        );

        await this._logTx(tenantId, {
            subjectId,
            type: 'earn',
            points: pointsEarned,
            balanceAfter: newBalance,
            orderId,
        });

        return { pointsEarned, newBalance, tier };
    },

    async redeem(
        tenantId: string,
        subjectId: string,
        points: number,
        operatorId: string,
        orderId?: string
    ): Promise<{ redeemed: number; newBalance: number }> {
        const account = await this.getOrCreate(tenantId, subjectId);
        if (account.points < points) throw new Error('Solde de points insuffisant');

        const newBalance = account.points - points;
        await Nexus.adapter.update(
            `tenants/${tenantId}/loyaltyAccounts/${account.id}`,
            { points: newBalance, lastRedeemedAt: new Date().toISOString() }
        );

        await this._logTx(tenantId, {
            subjectId,
            type: 'redeem',
            points: -points,
            balanceAfter: newBalance,
            orderId,
            operatorId,
        });

        return { redeemed: points, newBalance };
    },

    async _logTx(
        tenantId: string,
        data: Omit<LoyaltyTransaction, 'id' | 'tenantId' | 'timestamp'>
    ): Promise<void> {
        const id = Nexus.adapter.generateId(`tenants/${tenantId}/loyaltyTransactions`);
        const tx: LoyaltyTransaction = { id, tenantId, ...data, timestamp: Date.now() };
        LoyaltyTransactionSchema.parse(tx);
        await Nexus.adapter.set(
            `tenants/${tenantId}/loyaltyTransactions/${id}`,
            tx
        );
    },
};

'use client';

import { useState, useEffect } from 'react';
import { Loader2, Globe, WifiOff } from 'lucide-react';
import { TableSchema } from '@/modules/ops';
import { toast } from 'sonner';
import { z } from 'zod';
import { toggleOnlineBookingAction } from '../../actions/marketing.action';

type Table = z.infer<typeof TableSchema> & { onlineBookable?: boolean };

interface Props {
  tenantId: string;
}

export default function OnlineBookingToggle({ tenantId }: Props) {
  const [tables, setTables] = useState<Table[]>([]);
  const [loading, setLoading] = useState(true);
  const [updating, setUpdating] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);

    const loadTables = async () => {
        try {
            const { Nexus } = await import('@/lib/nexus/NexusAdapter');
            const path = tenantId ? `tenants/${tenantId}/tables` : 'tables';
            const data = await Nexus.adapter.query<Table>(path);
            if (!cancelled) {
                setTables(data);
                setLoading(false);
            }
        } catch {
            if (!cancelled) setLoading(false);
        }
    };
    loadTables();

    // Timeout safety: if onSnapshot hasn't fired after 5s, clear loading.
    const safetyTimeout = setTimeout(() => {
      if (!cancelled && loading) setLoading(false);
      });

    return () => {
      cancelled = true;
      clearTimeout(safetyTimeout);
    };
  }, [tenantId]);

  const toggle = async (table: Table) => {
    const next = !table.onlineBookable;
    setUpdating(table.id);
    try {
      await toggleOnlineBookingAction(tenantId, table.id, next);
      setTables((prev) =>
        prev.map((t) => (t.id === table.id ? { ...t, onlineBookable: next } : t))
      );
      toast.success(
        next
          ? `Table ${table.number} activee en ligne`
          : `Table ${table.number} desactivee en ligne`
      );
    } catch {
      toast.error('Echec de la mise a jour');
    } finally {
      setUpdating(null);
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center py-8">
        <Loader2 className="w-6 h-6 animate-spin text-accent" />
      </div>
    );
  }

  if (tables.length === 0) {
    return (
      <p className="text-sm text-text-muted text-center py-6">
        Aucune table trouvee. Configurez vos tables dans les parametres Salle.
      </p>
    );
  }

  return (
    <div className="space-y-2">
      {tables.map((table) => {
        const isOn = !!table.onlineBookable;
        const busy = updating === table.id;
        return (
          <div
            key={table.id}
            className="flex items-center justify-between rounded-2xl border border-border bg-bg-primary px-4 py-3 hover:bg-bg-secondary transition"
          >
            <div className="flex items-center gap-3">
              <div className={`w-8 h-8 rounded-xl flex items-center justify-center text-xs font-bold border ${isOn ? 'bg-green-50 border-green-200 text-green-700' : 'bg-bg-tertiary border-border text-text-muted'}`}>
                {table.number}
              </div>
              <div>
                <p className="text-sm font-medium text-text-primary">Table {table.number}</p>
                <p className="text-xs text-text-muted">{table.seats} place{table.seats > 1 ? 's' : ''}</p>
              </div>
            </div>
            <button
              onClick={() => toggle(table)}
              disabled={busy}
              aria-label={isOn ? 'Desactiver la reservation en ligne' : 'Activer la reservation en ligne'}
              className={`relative flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold border transition-all ${
                busy
                  ? 'opacity-50 cursor-not-allowed border-border text-text-muted'
                  : isOn
                  ? 'bg-green-50 border-green-300 text-green-700 hover:bg-green-100'
                  : 'bg-bg-secondary border-border text-text-muted hover:border-accent hover:text-accent'
              }`}
            >
              {busy ? (
                <Loader2 className="w-3.5 h-3.5 animate-spin" />
              ) : isOn ? (
                <Globe className="w-3.5 h-3.5" />
              ) : (
                <WifiOff className="w-3.5 h-3.5" />
              )}
              {isOn ? 'En ligne' : 'Hors ligne'}
            </button>
          </div>
        );
      })}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Customer, Reservation } from "@nexus/contracts";
import { Order } from "@/modules/ops";
import { Button } from "@ui/button";
import { ScrollArea } from "@ui/scroll-area";
import { Phone, Mail, Star, Calendar, Clock, ShoppingBag, TrendingUp, History } from "lucide-react";
import { Nexus } from "@/lib/nexus/NexusAdapter";
import { LoyaltyCard } from '../../../acquisition/marketing/components/crm/LoyaltyCard';

interface CustomerDetailPanelProps {
    customer: Customer;
    onClose: () => void;
    onNewReservation: () => void;
}

type DetailTab = "profil" | "historique" | "fidelite";

interface CustomerHistory {
    reservations: Reservation[];
    orders: Order[];
    avgSpend: number;
    topProducts: { name: string; count: number }[];
}

function useCustomerHistory(customer: Customer): { data: CustomerHistory | null; loading: boolean } {
    const [data, setData] = useState<CustomerHistory | null>(null);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        let cancelled = false;
        async function load() {
            setLoading(true);
            try {
                // Query reservations by customerId
                const reservations = await Nexus.adapter.query<Reservation>("reservations", {
                    where: [{ field: "customerId", operator: "==", value: customer.id }],
                    orderBy: { field: "date", direction: "desc" },
                    limit: 20,
                }).catch(() => [] as Reservation[]);

                // Query orders by customerId
                const orders = await Nexus.adapter.query<Order>("orders", {
                    where: [{ field: "customerId", operator: "==", value: customer.id }],
                    orderBy: { field: "createdAt", direction: "desc" },
                    limit: 50,
                }).catch(() => [] as Order[]);

                if (cancelled) return;

                // Average spend in euros
                const paidOrders = orders.filter((o) => o.status === "paid" || o.status === "served");
                const totalMicrounits = paidOrders.reduce((sum, o) => {
                    const mu = o.totalInMicrounits ?? (o.totalInCents ? o.totalInCents * 10_000 : 0);
                    return sum + mu;
                }, 0);
                const avgSpend = paidOrders.length > 0
                    ? totalMicrounits / paidOrders.length / 1_000_000
                    : (customer.averageSpendInMicrounits ?? (customer.averageSpendInCents ? customer.averageSpendInCents * 10_000 : 0)) / 1_000_000;

                // Top products from order items
                const productCount: Record<string, { name: string; count: number }> = {};
                for (const order of orders) {
                    for (const item of order.items) {
                        const key = item.productId;
                        productCount[key] = productCount[key]
                            ? { name: item.name, count: productCount[key].count + item.quantity }
                            : { name: item.name, count: item.quantity };
                    }
                }
                const topProducts = Object.values(productCount)
                    .sort((a, b) => b.count - a.count)
                    .slice(0, 3);

                setData({ reservations, orders, avgSpend, topProducts });
            } finally {
                if (!cancelled) setLoading(false);
            }
        }
        load();
        return () => { cancelled = true; };
    }, [customer.id, customer.averageSpendInMicrounits, customer.averageSpendInCents]);

    return { data, loading };
}

function HistoriqueTab({ customer }: { customer: Customer }) {
    const { data, loading } = useCustomerHistory(customer);

    if (loading) {
        return (
            <div className="flex items-center justify-center py-16 text-text-primary/30">
                <Clock className="w-5 h-5 animate-pulse mr-2" />
                <span className="text-sm">Chargement...</span>
            </div>
        );
    }

    if (!data) return null;

    const totalVisits = data.reservations.length || customer.visitCount;

    return (
        <div className="p-8 space-y-10">
            {/* KPI Row */}
            <div className="grid grid-cols-3 gap-4">
                <div className="p-5 rounded-2xl bg-surface-card/5 border border-subtle text-center">
                    <p className="text-2xl font-mono font-light text-accent italic">{totalVisits}</p>
                    <p className="text-[9px] font-black text-text-primary/40 uppercase tracking-widest mt-1">Visites</p>
