            await NexusEventBus.emitDurable('haccp.cooling_cycle_logged', {
                v: 1,
                tenantId,
                batchId,
                productId,
                productName,
                startTempCelsius,
                endTempCelsius,
                durationMinutes,
                operatorId,
                compliant,
                loggedAt: Date.now(),
            });
            return { success: true, compliant };
        } catch (err) {
            return { success: false, error: toError(err).message };
        }
    }
);

