import type { Policy, ThresholdRule } from '@/modules/compliance/domain/schemas/policy';
import { operationalFlags, type PolicyMode } from '@/config/features';
import { PERMISSION_ROLE_LEVELS, type PermissionRole } from '@/shared/nexus/contracts/permissions.types';
import { logger } from '@/lib/logger';

export interface PolicyCheckResult {
    allowed: boolean;
    reason?: string;
    requiresElevation?: boolean;
    requiredRoleLevel?: number;
}

// Default SoD matrix for procurement: reception ⊗ invoiceApproval ⊗ payment
const DEFAULT_SOD_MATRIX: Array<{ incompatibleActions: string[]; description: string }> = [
    {
        incompatibleActions: ['procurement.reception', 'procurement.invoiceApproval'],
        description: 'Le réceptionneur ne peut pas approuver la facture',
    },
    {
        incompatibleActions: ['procurement.invoiceApproval', 'procurement.payment'],
        description: "L'approbateur ne peut pas exécuter le paiement",
    },
    {
        incompatibleActions: ['procurement.reception', 'procurement.payment'],
        description: 'Le réceptionneur ne peut pas exécuter le paiement',
    },
];

export class PolicyEngine {
    private policies: Policy[] = [];

    loadPolicies(policies: Policy[]) {
        this.policies = policies.filter(p => p.enabled);
    }

    private get mode(): PolicyMode {
        return operationalFlags.policyEnforce;
    }

    checkSod(actorId: string, actorRole: PermissionRole, action: string, priorActions: Array<{ actorId: string; action: string }>): PolicyCheckResult {
        if (this.mode === 'off') return { allowed: true };

        const actorPriorActions = priorActions
            .filter(a => a.actorId === actorId)
            .map(a => a.action);

        // Check custom SoD policies
        const sodPolicies = this.policies.filter(p => p.type === 'sod' && p.sodRule);
        const allRules = [
            ...sodPolicies.map(p => p.sodRule!),
            ...DEFAULT_SOD_MATRIX,
        ];

        for (const rule of allRules) {
            if (!rule.incompatibleActions.includes(action)) continue;
            const conflict = rule.incompatibleActions.find(
                a => a !== action && actorPriorActions.includes(a)
            );
            if (conflict) {
                const msg = `SoD violation: ${actorRole} (${actorId}) cannot perform "${action}" — already did "${conflict}". ${rule.description ?? ''}`;
                if (this.mode === 'warn') {
                    logger.warn(`[PolicyEngine] ${msg}`);
                    return { allowed: true, reason: msg };
                }
                return { allowed: false, reason: msg };
            }
        }

        return { allowed: true };
    }

    checkThreshold(actorRole: PermissionRole, action: string, field: 'amount' | 'discountPct' | 'quantity', value: number): PolicyCheckResult {
        if (this.mode === 'off') return { allowed: true };

        const actorLevel = PERMISSION_ROLE_LEVELS[actorRole] ?? 0;

        // Check custom threshold policies
        const thresholdPolicies = this.policies
            .filter(p => p.type === 'threshold' && p.thresholdRule)
            .map(p => p.thresholdRule!);

        for (const rule of thresholdPolicies) {
            if (rule.action !== action || rule.field !== field) continue;
            if (value > rule.maxValue && actorLevel < rule.requiredRoleLevel) {
                const msg = `Seuil dépassé: ${field}=${value} > max ${rule.maxValue}, rôle ${actorRole} (lvl ${actorLevel}) < requis (lvl ${rule.requiredRoleLevel})`;
                if (this.mode === 'warn') {
                    logger.warn(`[PolicyEngine] ${msg}`);
                    return { allowed: true, reason: msg, requiresElevation: true, requiredRoleLevel: rule.requiredRoleLevel };
                }
                return { allowed: false, reason: msg, requiresElevation: true, requiredRoleLevel: rule.requiredRoleLevel };
            }
        }

        return { allowed: true };
    }

    getApplicableThresholds(action: string): ThresholdRule[] {
        return this.policies
            .filter(p => p.type === 'threshold' && p.thresholdRule?.action === action)
            .map(p => p.thresholdRule!);
    }
}

export const policyEngine = new PolicyEngine();

import { CryptoService } from '@/lib/CryptoService';
import { AuditEventSchema, AUDITED_COLLECTIONS, type AuditAction, type AuditEvent } from '@/modules/compliance/domain/schemas/audit';
import { operationalFlags } from '@/config/features';
import { logger } from '@/lib/logger';
import { JsonObject } from "@/shared/types/json";

const GENESIS_HASH = 'AUDIT_GENESIS_0000000000000000';

interface AuditPayload {
    tenantId: string;
    actorId: string;
    actorRole: string;
    action: AuditAction;
    collection: string;
    entityId?: string;
    subjectId?: string;
    before?: Record<string, unknown>;
    after?: Record<string, unknown>;
    metadata?: Record<string, unknown>;
}

type NexusWriter = {
    set<T>(path: string, data: T): Promise<void>;
    query<T>(collectionPath: string, options?: { orderBy?: string; orderDirection?: 'asc' | 'desc'; limit?: number }): Promise<T[]>;
    generateId(collectionPath: string): string;
};

export class AuditService {
    private previousHash: string = GENESIS_HASH;
    private initialized = false;
    private nexus: NexusWriter | null = null;

    setNexus(nexus: NexusWriter) {
        this.nexus = nexus;
    }

    async init(tenantId: string) {
        if (!this.nexus) return;
        if (this.initialized) return;

        const path = `tenants/${tenantId}/auditLog`;
        const lastEvents = await this.nexus.query<AuditEvent>(path, {
            orderBy: 'ts',
            orderDirection: 'desc',
            limit: 1,
        });

        if (lastEvents.length > 0 && lastEvents[0]!.hash) {
            this.previousHash = lastEvents[0]!.hash;
        }

        this.initialized = true;
    }

    isAuditedCollection(collection: string): boolean {
        return (AUDITED_COLLECTIONS as readonly string[]).includes(collection);
    }

    stripPii(data: Record<string, unknown> | undefined): Record<string, unknown> | undefined {
        if (!data) return undefined;
        const PII_KEYS = ['email', 'phone', 'firstName', 'lastName', 'address', 'iban', 'bankAccount', 'ssn'];
        const stripped: Record<string, unknown> = {};
        for (const [key, value] of Object.entries(data)) {
            if (PII_KEYS.includes(key)) {
                stripped[key] = '[REDACTED]';
            } else {
                stripped[key] = value;
            }
        }
        return stripped;
    }

    async record(payload: AuditPayload): Promise<AuditEvent | null> {
        const mode = operationalFlags.auditIntercept;
        if (mode === 'off') return null;

        if (!this.nexus) {
            logger.warn('[AuditService] No Nexus writer — skipping audit event');
            return null;
        }

        const { tenantId, before, after, ...rest } = payload;

        if (!this.initialized && tenantId) {
            await this.init(tenantId);
        }
        const sanitizedBefore = this.stripPii(before);
        const sanitizedAfter = this.stripPii(after);

        const collectionPath = `tenants/${tenantId}/auditLog`;
        const id = this.nexus.generateId(collectionPath);
        const ts = Date.now();

        const dataForHash = CryptoService.canonicalStringify({
            ...rest,
            tenantId,
            entityId: rest.entityId ?? '',
            ts,
        });

        const hash = await CryptoService.generateHash(dataForHash, this.previousHash);

        const event: AuditEvent = {
            id,
            tenantId,
            ...rest,
            before: sanitizedBefore,
            after: sanitizedAfter,
            ts,
            hash,
            previousHash: this.previousHash,
        };

        const parsed = AuditEventSchema.parse(event);

        if (mode === 'warn') {
            logger.info(`[AuditService] WARN mode — would record: ${parsed.action} on ${parsed.collection}/${parsed.entityId ?? '?'}`);
        }

        await this.nexus.set(`${collectionPath}/${id}`, parsed);
        this.previousHash = hash;

        return parsed;
    }

    /**
     * Exports tenant-scoped audit logs in CSV format.
     */
    async exportAuditLogs(tenantId: string): Promise<string> {
        if (!this.nexus) throw new Error('[AuditService] Nexus adapter not initialized');
        const collectionPath = `tenants/${tenantId}/auditLog`;
        const events = await this.nexus.query<AuditEvent>(collectionPath, {
            orderBy: { field: 'ts', direction: 'asc' } as never
        });

        const header = 'id,ts,action,collection,entityId,userId,hash,previousHash\n';
        const rows = (events || []).map(e => 
            `"${e.id}","${new Date(e.ts).toISOString()}","${e.action}","${e.collection}","${e.entityId || ''}","${(e as JsonObject).actorId || (e as JsonObject).userId || ''}","${e.hash}","${e.previousHash}"`
        ).join('\n');

        return header + rows;
    }
}

