import { Nexus } from '@/lib/nexus/NexusAdapter';
import { NexusEventBus } from '@/shared/eventBus/NexusEventBus';
import { logger } from '@/lib/logger';
import type { EmployeeDocument } from '@/modules/human';
import type { License } from '@/modules/compliance/domain/schemas/license';
import { toError } from "@/lib/toError";

interface RegisterDoc {
  id: string;
  title: string;
  status: string;
  expiresAt?: string;
  nextReview?: string;
  type?: string;
}

type CalendarEventType = 'audit' | 'renewal' | 'inspection' | 'training';

function daysUntil(dateStr: string): number {
  const target = new Date(dateStr);
  const now = new Date();
  return Math.floor((target.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
}

function inferEventType(item: { type?: string; name?: string }): CalendarEventType {
  const t = (item.type ?? item.name ?? '').toLowerCase();
  if (t.includes('audit') || t.includes('inspection')) return 'audit';
  if (t.includes('training') || t.includes('formation')) return 'training';
  if (t.includes('inspection') || t.includes('contrôle')) return 'inspection';
  return 'renewal';
}

export class ComplianceWatcherService {
  static async scanExpirations(tenantId: string): Promise<{
    expired: number;
    upcoming: number;
  }> {
    let expired = 0;
    let upcoming = 0;

    try {
      const [docs, licenses, registerDocs] = await Promise.all([
        Nexus.adapter.query<EmployeeDocument>(`tenants/${tenantId}/employeeDocuments`),
        Nexus.adapter.query<License>(`tenants/${tenantId}/licenses`),
        Nexus.adapter.query<RegisterDoc>(`tenants/${tenantId}/documents`),
      ]);

      for (const doc of docs) {
        if (!doc.expiresAt) continue;
        const days = daysUntil(doc.expiresAt);

        if (days < 0) {
          expired++;
          await NexusEventBus.emitDurable('cert.expired', {
            v: 1,
            tenantId,
            certId: doc.id,
            certType: doc.type ?? 'employee_document',
            entityName: doc.name ?? doc.id,
            expiredAt: doc.expiresAt,
          });
        } else if (days <= 30) {
          upcoming++;
          await NexusEventBus.emitDurable('compliance.calendar', {
            v: 1,
            tenantId,
            eventType: inferEventType(doc),
            title: `Renouvellement : ${doc.name ?? doc.type ?? doc.id}`,
            dueDate: doc.expiresAt,
            daysUntilDue: days,
          });
        }
      }

      for (const lic of licenses) {
        if (!lic.expiresAt) continue;
        const days = daysUntil(lic.expiresAt);

        if (days < 0) {
          expired++;
          await NexusEventBus.emitDurable('cert.expired', {
            v: 1,
            tenantId,
            certId: lic.id,
            certType: lic.type ?? 'license',
            entityName: lic.name ?? lic.id,
            expiredAt: lic.expiresAt,
          });
        } else if (days <= 30) {
          upcoming++;
          await NexusEventBus.emitDurable('compliance.calendar', {
            v: 1,
            tenantId,
            eventType: 'renewal',
            title: `Renouvellement licence : ${lic.name ?? lic.id}`,
            dueDate: lic.expiresAt,
            daysUntilDue: days,
          });
        }
      }

      for (const reg of registerDocs) {
        const expiryDate = reg.expiresAt ?? reg.nextReview;
        if (!expiryDate) continue;
        const days = daysUntil(expiryDate);

        if (days < 0) {
          expired++;
          await NexusEventBus.emitDurable('cert.expired', {
            v: 1,
            tenantId,
            certId: reg.id,
            certType: reg.type ?? 'register_document',
            entityName: reg.title ?? reg.id,
            expiredAt: expiryDate,
          });
        } else if (days <= 30) {
          upcoming++;
          await NexusEventBus.emitDurable('compliance.calendar', {
            v: 1,
            tenantId,
            eventType: inferEventType(reg),
            title: `Échéance : ${reg.title ?? reg.id}`,
            dueDate: expiryDate,
            daysUntilDue: days,
          });
        }
      }

      logger.info(`[ComplianceWatcher] Scan tenant ${tenantId}: ${expired} expired, ${upcoming} upcoming`);
    } catch (err) {
      logger.error('[ComplianceWatcher] Scan failed', toError(err).message);
    }

    return { expired, upcoming };
  }
}

import type { Policy, ThresholdRule } from '@/modules/compliance/domain/schemas/policy';
import { operationalFlags, type PolicyMode } from '@/config/features';
import { PERMISSION_ROLE_LEVELS, type PermissionRole } from '@/shared/nexus/contracts/permissions.types';
import { logger } from '@/lib/logger';

export interface PolicyCheckResult {
    allowed: boolean;
    reason?: string;
    requiresElevation?: boolean;
    requiredRoleLevel?: number;
}

// Default SoD matrix for procurement: reception ⊗ invoiceApproval ⊗ payment
const DEFAULT_SOD_MATRIX: Array<{ incompatibleActions: string[]; description: string }> = [
    {
        incompatibleActions: ['procurement.reception', 'procurement.invoiceApproval'],
        description: 'Le réceptionneur ne peut pas approuver la facture',
    },
    {
        incompatibleActions: ['procurement.invoiceApproval', 'procurement.payment'],
        description: "L'approbateur ne peut pas exécuter le paiement",
    },
    {
        incompatibleActions: ['procurement.reception', 'procurement.payment'],
        description: 'Le réceptionneur ne peut pas exécuter le paiement',
    },
];

export class PolicyEngine {
    private policies: Policy[] = [];

    loadPolicies(policies: Policy[]) {
        this.policies = policies.filter(p => p.enabled);
    }

    private get mode(): PolicyMode {
        return operationalFlags.policyEnforce;
    }

    checkSod(actorId: string, actorRole: PermissionRole, action: string, priorActions: Array<{ actorId: string; action: string }>): PolicyCheckResult {
        if (this.mode === 'off') return { allowed: true };

        const actorPriorActions = priorActions
            .filter(a => a.actorId === actorId)
            .map(a => a.action);

        // Check custom SoD policies
        const sodPolicies = this.policies.filter(p => p.type === 'sod' && p.sodRule);
        const allRules = [
            ...sodPolicies.map(p => p.sodRule!),
            ...DEFAULT_SOD_MATRIX,
        ];

        for (const rule of allRules) {
            if (!rule.incompatibleActions.includes(action)) continue;
            const conflict = rule.incompatibleActions.find(
                a => a !== action && actorPriorActions.includes(a)
            );
            if (conflict) {
                const msg = `SoD violation: ${actorRole} (${actorId}) cannot perform "${action}" — already did "${conflict}". ${rule.description ?? ''}`;
                if (this.mode === 'warn') {
                    logger.warn(`[PolicyEngine] ${msg}`);
                    return { allowed: true, reason: msg };
                }
                return { allowed: false, reason: msg };
            }
        }

        return { allowed: true };
    }

    checkThreshold(actorRole: PermissionRole, action: string, field: 'amount' | 'discountPct' | 'quantity', value: number): PolicyCheckResult {
        if (this.mode === 'off') return { allowed: true };

        const actorLevel = PERMISSION_ROLE_LEVELS[actorRole] ?? 0;

        // Check custom threshold policies
        const thresholdPolicies = this.policies
            .filter(p => p.type === 'threshold' && p.thresholdRule)
            .map(p => p.thresholdRule!);

        for (const rule of thresholdPolicies) {
            if (rule.action !== action || rule.field !== field) continue;
            if (value > rule.maxValue && actorLevel < rule.requiredRoleLevel) {
                const msg = `Seuil dépassé: ${field}=${value} > max ${rule.maxValue}, rôle ${actorRole} (lvl ${actorLevel}) < requis (lvl ${rule.requiredRoleLevel})`;
                if (this.mode === 'warn') {
                    logger.warn(`[PolicyEngine] ${msg}`);
                    return { allowed: true, reason: msg, requiresElevation: true, requiredRoleLevel: rule.requiredRoleLevel };
                }
                return { allowed: false, reason: msg, requiresElevation: true, requiredRoleLevel: rule.requiredRoleLevel };
            }
        }

        return { allowed: true };
    }

    getApplicableThresholds(action: string): ThresholdRule[] {
        return this.policies
            .filter(p => p.type === 'threshold' && p.thresholdRule?.action === action)
            .map(p => p.thresholdRule!);
    }
}

export const policyEngine = new PolicyEngine();

import { NexusTransaction } from '@/lib/adapters/NexusTransaction';
