"use client";

import React, { useState, useEffect } from "react";
import { useAuth } from "@/shared/providers/NexusCoreProvider";
import { Loader2, Save } from "lucide-react";
import { useAtom } from "jotai";
import { rbacConfigAtom, fetchRbacConfigAtom } from "@/store/pillars/rbac";

export function RolesPermissionsPanel() {
    const { currentUser } = useAuth();
    const [config, setConfig] = useAtom(rbacConfigAtom);
    const [, fetchConfig] = useAtom(fetchRbacConfigAtom);
    const [isLoading, setIsLoading] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    useEffect(() => {
        if (currentUser?.tenantId) {
            setIsLoading(true);
            fetchConfig(currentUser.tenantId).finally(() => setIsLoading(false));
        }
    }, [currentUser?.tenantId, fetchConfig]);

    const handleSave = async () => {
        if (!currentUser?.tenantId || !config) return;

        setIsSaving(true);
        try {
            const res = await fetch(`/api/admin/rbac?tenantId=${currentUser.tenantId}`, {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                },
                body: JSON.stringify(config),
            });

            if (!res.ok) {
                throw new Error("Failed to save RBAC config");
            }

            // Reload config
            await fetchConfig(currentUser.tenantId);
        } catch (error) {
            console.error("Error saving RBAC config:", error);
        } finally {
            setIsSaving(false);
        }
    };

    if (isLoading) {
        return (
            <div className="flex h-32 w-full items-center justify-center">
                <Loader2 className="w-6 h-6 animate-spin text-brand-primary" />
            </div>
        );
    }

    return (
        <div className="bg-surface-card rounded-2xl border border-border p-6 space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-xl font-bold text-text-primary">Roles & Permissions (RBAC)</h2>
                    <p className="text-sm text-text-muted mt-1">
                        Configure page and tab access overrides for this tenant.
                    </p>
                </div>
                <button 
                    onClick={handleSave}
                    disabled={isSaving}
                    className="flex items-center gap-2 px-4 py-2 bg-brand-primary text-white rounded-xl hover:bg-brand-secondary transition-colors disabled:opacity-50"
                >
                    {isSaving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                    Sauvegarder
                </button>
            </div>

            <div className="p-4 bg-bg-tertiary rounded-xl border border-border/50 text-sm text-text-secondary">
                <p>
                    <strong>Note:</strong> L'interface détaillée (matrice visuelle) est en cours de développement. 
                    Actuellement, la configuration (Delta JSON) est stockée dans Sovereign Nexus et chargée dynamiquement.
                </p>
                <pre className="mt-4 p-4 bg-black/50 rounded-lg overflow-auto max-h-[400px] text-xs">
                    {JSON.stringify(config, null, 2)}
                </pre>
            </div>
        </div>
    );
}

import type { JournalLine } from '@nexus/contracts';
import type { CartItem } from '@/modules/ops/workflow/engine/types';
import type { BridgePayload, PaymentMode } from './FinancialNexusBridge';

export const PCG_PAYMENT_ACCOUNTS: Record<PaymentMode, { code: string; name: string }> = {
  cash:         { code: '531000', name: 'Caisse' },
  card:         { code: '512000', name: 'Banque (CB)' },
  check:        { code: '511200', name: 'Chèques à encaisser' },
  ticket_resto: { code: '511500', name: 'Titres-restaurant à encaisser' },
  transfer:     { code: '512000', name: 'Banque (virement)' },
  comp:         { code: '658000', name: 'Charges diverses (Offerts)' },
};

export const microToCents = (mu: number): number => Math.round(mu / 10_000);

export function computeTtcByRateAndAxis(
  items: (CartItem & { taxRate: string; analyticalAxis: string })[]
): Record<string, { ttcMu: number; tvaMu: number }> {
  const result: Record<string, { ttcMu: number; tvaMu: number }> = {};
  for (const item of items) {
    const key = `${item.taxRate}_${item.analyticalAxis}`;
    const lineTTC = item.unitPriceInMicrounits * item.quantity - (item.discountInMicrounits ?? 0);
    const rateNum = parseFloat(String(item.taxRate ?? '0.10'));
    const lineTVA = lineTTC - Math.round(lineTTC / (1 + rateNum));

    if (!result[key]) {
      result[key] = { ttcMu: 0, tvaMu: 0 };
    }
    result[key].ttcMu += lineTTC;
    result[key].tvaMu += lineTVA;
  }
  return result;
}

export function makeLine(
  accountCode: string,
  accountName: string,
  side: 'debit' | 'credit',
  cents: number,
  description: string,
  pieceNumber: string,
  now: string,
  analyticalAxis?: string,
): JournalLine {
  return {
    accountId: accountCode,
    accountCode,
    accountName,
    description,
    side,
    amountInCents: cents,
    amountInMicrounits: cents * 10_000,
    date: now,
    pieceNumber,
    debitInCents: side === 'debit' ? cents : 0,
    debitInMicrounits: side === 'debit' ? cents * 10_000 : 0,
    creditInCents: side === 'credit' ? cents : 0,
    creditInMicrounits: side === 'credit' ? cents * 10_000 : 0,
    runningBalanceInCents: 0,
    runningBalanceInMicrounits: 0,
    ...(analyticalAxis ? { analyticalAxis } : {}),
  };
}

export function buildJournalLines(
  ttcByRateAndAxis: Record<string, { ttcMu: number; tvaMu: number }>,
  payload: BridgePayload,
  pieceNumber: string,
  now: string
): JournalLine[] {
  const credits: JournalLine[] = [];
  let totalCreditCents = 0;

  for (const [rateAndAxis, { ttcMu, tvaMu }] of Object.entries(ttcByRateAndAxis)) {
    const [rateStr, axis] = rateAndAxis.split('_');
    const ratePercent = (parseFloat(rateStr) * 100).toFixed(1).replace('.0', '');
    const htMu = ttcMu - tvaMu;
    const htCents = microToCents(htMu);
    const tvaCents = microToCents(tvaMu);

    credits.push(
      makeLine(
        '707000',
        `Ventes de marchandises (${axis.toUpperCase()})`,
        'credit',
        htCents,
        `Vente POS — Axe ${axis}`,
        pieceNumber,
        now,
        axis
      )
    );

    credits.push(
      makeLine(
        '445710',
        `TVA collectée (${ratePercent}%)`,
        'credit',
        tvaCents,
        `TVA ${ratePercent}% sur vente POS`,
        pieceNumber,
        now,
        axis
      )
    );

    totalCreditCents += htCents + tvaCents;
  }

  const debits: JournalLine[] = [];

  if (payload.partialPayments && payload.partialPayments.length > 0) {
    for (const p of payload.partialPayments) {
      const modeKey = (p.method as PaymentMode) || payload.paymentMode || 'card';
      const acct = PCG_PAYMENT_ACCOUNTS[modeKey] ?? PCG_PAYMENT_ACCOUNTS.card;
      debits.push(
        makeLine(
          acct.code,
          acct.name,
          'debit',
          p.amount,
          `Paiement partiel (${modeKey}) — Convive ${p.guest}`,
          pieceNumber,
          now
        )
      );
    }
  } else {
    const modeKey = payload.paymentMode || 'card';
    const acct = PCG_PAYMENT_ACCOUNTS[modeKey] ?? PCG_PAYMENT_ACCOUNTS.card;
    debits.push(
      makeLine(
        acct.code,
        acct.name,
        'debit',
        totalCreditCents,
        `Règlement POS (${acct.name})`,
        pieceNumber,
        now
      )
    );
  }

  return [...debits, ...credits];
}

import { CryptoService } from '@/lib/CryptoService';
import { SharedKernel } from '@/lib/shared-kernel';
import { empireAudit } from '@/lib/audit';
import type { JournalEntry, FiscalSeal, JournalEntryStatus } from '@nexus/contracts';
import type { CartItem } from '@/modules/ops/workflow/engine/types';
import { NexusEventBus } from '@/shared/eventBus/NexusEventBus';
import { TaxCalculator } from '../fiscalite/TaxCalculator';
import { FiscalSealer } from '../fiscalite/FiscalSealer';
import { resolveVatRate } from '../fiscalite/tax/vatResolver';
import { inferCategory } from '../fiscalite/tax/vatResolver';
import type { ConsumptionMode } from '@/modules/ops';

export type PaymentMode = 'cash' | 'card' | 'check' | 'ticket_resto' | 'transfer' | 'comp';

export interface BridgePayload {
  cartItems: CartItem[];
  operatorId: string;
  tableId: string | null;
  tenantId: string;
  consumptionMode?: ConsumptionMode;
  paymentMode?: PaymentMode;
  covers?: number;
  isTrainingMode?: boolean;
  partialPayments?: { amount: number; guest: number; method?: string }[];
}

export interface BridgeResult {
  journalEntry: JournalEntry;
  seal: FiscalSeal;
}

import {
  microToCents,
  computeTtcByRateAndAxis,
  buildJournalLines,
} from './FinancialJournalBuilder';

function emitPaymentEvents(
  entryId: string,
  payload: BridgePayload,
  totalTTCInMicrounits: number,
  cartItems: CartItem[],
  paymentMode: PaymentMode
): void {
  const { tableId, tenantId, operatorId } = payload;
  NexusEventBus.emitDurable('order.paid', {
    v: 1,
    orderId: entryId,
    tableId,
    tenantId,
    operatorId,
    items: cartItems,
    totalInMicrounits: totalTTCInMicrounits,
    paymentMode: (payload.partialPayments && payload.partialPayments.length > 0) ? 'split' : paymentMode,
  }).catch(() => {});

  if (payload.partialPayments && payload.partialPayments.length > 0) {
    NexusEventBus.emitDurable('order.split', {
      v: 1,
      orderId: entryId,
      tableId,
      tenantId,
      operatorId,
      totalInMicrounits: totalTTCInMicrounits,
      payments: payload.partialPayments.map(p => ({ amount: p.amount, guest: p.guest, method: p.method ?? 'card' })),
    }).catch(() => {});
  } else if (paymentMode === 'comp' || totalTTCInMicrounits === 0) {
    NexusEventBus.emitDurable('order.comp', {
      v: 1,
      orderId: entryId,
      tenantId,
      operatorId,
      items: cartItems,
      totalValueInMicrounits: totalTTCInMicrounits,
      reason: 'Offert par la direction',
    }).catch(() => {});
  } else if (totalTTCInMicrounits < 0) {
    NexusEventBus.emitDurable('order.refunded', {
      v: 1,
      orderId: entryId,
      tenantId,
      operatorId,
      amountInMicrounits: Math.abs(totalTTCInMicrounits),
      originalPaymentMode: paymentMode,
    }).catch(() => {});
  }
}

export interface RefundPayload {
  original: JournalEntry;
  operatorId: string;
  tenantId: string;
  reason: string;
}

/**
 * FinancialNexusBridge — Grade X "NF525 Suture"
 */
export const FinancialNexusBridge = {
  async processOrder(payload: BridgePayload): Promise<BridgeResult> {
    const {
      cartItems,
      operatorId,
      tableId,
      tenantId,
      consumptionMode = 'dine_in',
      isTrainingMode = false,
      paymentMode = 'card',
    } = payload;

    if (cartItems.length === 0) {
      throw new Error('FinancialNexusBridge: panier vide');
    }

    const resolvedItems = cartItems.map(item => {
      const lineMode = (item as { consumptionMode?: ConsumptionMode }).consumptionMode ?? consumptionMode;
      const category = inferCategory(item.categoryId ?? '', item.name);
      const taxRate = isTrainingMode ? '0.00' : resolveVatRate({ category, consumptionMode: lineMode }) as "0.055" | "0.10" | "0.20";
      const analyticalAxis = (category === 'beverage_soft' || category === 'alcohol') ? 'Beverage' : 'Food';
      return { ...item, taxRate, analyticalAxis };
    }) as (import('@/modules/ops').CartItem & { taxRate: "0.055" | "0.10" | "0.20", analyticalAxis: string })[];

    const { totalTTCInMicrounits, tvaBreakdown } = TaxCalculator.calculateTotals(resolvedItems);
    const ttcByRateAndAxis = computeTtcByRateAndAxis(resolvedItems);

    const entryId = SharedKernel.generateId('JE');
    const now = new Date().toISOString();

    const buildSnapshot = (pieceNumber: string): string =>
      CryptoService.canonicalStringify({
        id: entryId,
        receiptNumber: pieceNumber,
        operatorId,
        tableId,
        totalTTCInMicrounits,
        tvaBreakdown,
        timestamp: now,
      } as import('@/shared/nexus-contract').SovereignData);

    // L7 Pattern C: `updatedAt` inclus dans la base — le type inféré a `id: string` explicite,
    // ce qui rend l'objet assignable à `Record<string, unknown> & { id: string }` sans cast.
    // `Omit<JournalEntry, ...>` était impossible : SovereignNode a `[key: string]: SovereignField`
    // → TypeScript perd les propriétés nommées après un Omit sur un type indexé.
    const buildEntryBase = (pieceNumber: string, status: JournalEntryStatus) => ({
      id: entryId,
      date: now,
      pieceNumber,
      description: `Vente POS — Table ${tableId ?? 'Emporté'} — ${pieceNumber}`,
      referenceId: tableId ?? undefined,
      referenceType: 'order' as const,
      isSystemGenerated: true,
      isValidated: status === 'validated',
      type: 'revenue' as const,
      amountInCents: microToCents(totalTTCInMicrounits),
      amountInMicrounits: totalTTCInMicrounits,
      status,
      updatedAt: now,
      lines: buildJournalLines(ttcByRateAndAxis, payload, pieceNumber, now),
    });

    let hash: string, signature: string, sealId: string, previousHash: string;
    let finalJournalEntry: JournalEntry;
    let finalReceiptNumber: string;
    let finalSnapshot: string;

    const isOnline = typeof navigator !== 'undefined' ? navigator.onLine : true;

    if (isOnline) {
      const receiptNumber = await FiscalSealer.generateSequentialReceiptNumber(tenantId);
      const journalEntryBase = buildEntryBase(receiptNumber, 'validated');
      const dataSnapshot = buildSnapshot(receiptNumber);

      const sealResult = await FiscalSealer.sealDataAtomically(
        dataSnapshot,
        tenantId,
        isTrainingMode,
        journalEntryBase,
      );
      hash = sealResult.hash;
      signature = sealResult.signature;
      sealId = sealResult.sealId;
      previousHash = sealResult.previousHash;

      finalJournalEntry = { ...journalEntryBase, fiscalSealHash: hash, sealedAt: now, updatedAt: now };
      finalReceiptNumber = receiptNumber;
      finalSnapshot = dataSnapshot;
    } else {
      const provisional = `OFFLINE-${entryId}`;
      const journalEntryBase = buildEntryBase(provisional, 'draft');

      hash = 'PENDING_OFFLINE_SEAL';
      signature = 'PENDING_OFFLINE_SEAL';
      sealId = SharedKernel.generateId('seal_pending');
      previousHash = 'PENDING_OFFLINE';

      finalJournalEntry = { ...journalEntryBase, updatedAt: now };
      finalReceiptNumber = provisional;
      finalSnapshot = buildSnapshot(provisional);

      const { SyncManager } = await import('@/lib/offline/sync-manager');
      await SyncManager.enqueue({
        type: 'NF525_PAYMENT',
        priority: 1,
        collection: `tenants/${tenantId}/journalEntries`,
        targetId: entryId,
        action: 'COMMIT_BATCH',
        payload: {
          instructions: [
            { method: 'SET', path: `tenants/${tenantId}/journalEntries/${entryId}`, data: finalJournalEntry },
          ],
        },
      });
    }

    const seal: FiscalSeal = {
      id: sealId,
      transactionId: entryId,
      timestamp: now,
      dataSnapshot: finalSnapshot,
      hash,
      previousHash,
      signature,
      updatedAt: now,
    };

    emitPaymentEvents(entryId, payload, totalTTCInMicrounits, cartItems, paymentMode);

    empireAudit.log({
      module: 'accounting',
      action: 'POS_PAYMENT_SEALED',
      details: {
        entryId,
        sealId,
        hash: hash.substring(0, 8),
        totalTTC: totalTTCInMicrounits,
        receiptNumber: finalReceiptNumber,
        isTrainingMode,
        offline: !isOnline,
      },
      severity: 'low',
      timestamp: new Date(),
    });

    return { journalEntry: finalJournalEntry, seal };
  },

  async processRefund(payload: RefundPayload): Promise<BridgeResult> {
    const { original, operatorId, tenantId, reason } = payload;

    // Extourne: montants inversés
    const refundAmountInCents = -Math.abs(original.amountInCents ?? 0);
    const refundAmountInMicrounits = -Math.abs(original.amountInMicrounits ?? 0);

    const lines = original.lines.map(line => ({
      ...line,
      amountInCents: -(line.amountInCents ?? 0),
      amountInMicrounits: -(line.amountInMicrounits ?? 0),
      debitInCents: line.creditInCents,
      debitInMicrounits: line.creditInMicrounits,
      creditInCents: line.debitInCents,
      creditInMicrounits: line.debitInMicrounits,
      description: `[EXTOURNE] ${line.description}`,
    }));

    const entryId = SharedKernel.generateId('JE');
    const now = new Date().toISOString();
    const isOnline = typeof navigator !== 'undefined' ? navigator.onLine : true;
    const isTrainingMode = false; // Par défaut pour le remboursement

    let hash: string, signature: string, sealId: string, previousHash: string;
    let finalJournalEntry: JournalEntry;
    let finalReceiptNumber: string;
    let finalSnapshot: string;

    const buildSnapshot = (pieceNumber: string): string =>
      CryptoService.canonicalStringify({
        id: entryId,
        receiptNumber: pieceNumber,
        operatorId,
        totalTTCInMicrounits: refundAmountInMicrounits,
        timestamp: now,
        reason,
        extourneFor: original.id,
      } as import('@/shared/nexus-contract').SovereignData);

    const buildEntryBase = (pieceNumber: string, status: string) => ({
      id: entryId,
      date: now,
      pieceNumber,
      description: `Remboursement POS — Réf ${original.pieceNumber} — ${pieceNumber}`,
      referenceId: original.id,
      referenceType: 'refund' as const,
      isSystemGenerated: true,
      isValidated: status === 'validated',
      type: 'EXTOURNE' as never, // type: 'EXTOURNE' bypass type checking if needed
      amountInCents: refundAmountInCents,
      amountInMicrounits: refundAmountInMicrounits,
      status,
      lines,
    });

    if (isOnline) {
      const receiptNumber = await FiscalSealer.generateSequentialReceiptNumber(tenantId);
      const journalEntryBase = buildEntryBase(receiptNumber, 'validated');
      const dataSnapshot = buildSnapshot(receiptNumber);

      const sealResult = await FiscalSealer.sealDataAtomically(
        dataSnapshot,
        tenantId,
        isTrainingMode,
        journalEntryBase,
      );
      hash = sealResult.hash;
      signature = sealResult.signature;
      sealId = sealResult.sealId;
      previousHash = sealResult.previousHash;

      finalJournalEntry = { ...journalEntryBase, fiscalSealHash: hash, sealedAt: now, updatedAt: now } as unknown as JournalEntry; // as unknown as: referenceType:'refund' et type:'EXTOURNE' hors union JournalEntry — frontière NF525 extourne
      finalReceiptNumber = receiptNumber;
      finalSnapshot = dataSnapshot;
    } else {
      const provisional = `OFFLINE-REFUND-${entryId}`;
      const journalEntryBase = buildEntryBase(provisional, 'draft');

      hash = 'PENDING_OFFLINE_SEAL';
      signature = 'PENDING_OFFLINE_SEAL';
      sealId = SharedKernel.generateId('seal_pending');
      previousHash = 'PENDING_OFFLINE';

      finalJournalEntry = { ...journalEntryBase, updatedAt: now } as unknown as JournalEntry; // as unknown as: idem extourne offline — types non-standard légitimes NF525
      finalReceiptNumber = provisional;
      finalSnapshot = buildSnapshot(provisional);

      const { SyncManager } = await import('@/lib/offline/sync-manager');
      await SyncManager.enqueue({
        type: 'NF525_PAYMENT',
        priority: 1,
        collection: `tenants/${tenantId}/journalEntries`,
        targetId: entryId,
        action: 'COMMIT_BATCH',
        payload: {
          instructions: [
            { method: 'SET', path: `tenants/${tenantId}/journalEntries/${entryId}`, data: finalJournalEntry },
          ],
        },
      });
    }

    const seal: FiscalSeal = {
      id: sealId,
      transactionId: entryId,
      timestamp: now,
      dataSnapshot: finalSnapshot,
      hash,
      previousHash,
      signature,
      updatedAt: now,
    };

    empireAudit.log({
      module: 'accounting',
      action: 'POS_REFUND_SEALED',
      details: {
        entryId,
        sealId,
        hash: hash.substring(0, 8),
        totalTTC: refundAmountInMicrounits,
        receiptNumber: finalReceiptNumber,
        offline: !isOnline,
        reason,
      },
      severity: 'high',
      timestamp: new Date(),
    });

    return { journalEntry: finalJournalEntry, seal };
  }
};

import { Nexus } from '@/lib/nexus/NexusAdapter';
import { FiscalEngine, FiscalizableRecord } from '@/modules/finance/fiscalite/FiscalAdapter';
import { checkOnlineStatus } from '@/lib/offline/status';
import { FiscalSeal } from '@nexus/contracts';
import { db } from '@/lib/offline/offline-store';
import { logger } from '@/lib/logger';
import { toError } from "@/lib/toError";

/**
 * ⛓️ BlockchainLedgerService - Restaurant OS
 * Assure l'immuabilité du Grand Livre en chaînant cryptographiquement
 * chaque nouvelle écriture à la précédente (Blockchain Fiscal NF525).
 * 
 * GRADE VI: Implémente une "Task Queue" séquentielle pour garantir l'atomicité
 * sous stress (Black Friday Mode).
 */
export class BlockchainLedgerService {

    // 🔒 Sequential Lock Queue
    private static sealQueue: Promise<void | FiscalSeal> = Promise.resolve();

    // 🧊 Local cache for high-speed chaining
    private static lastSealCache: FiscalSeal | undefined = undefined;

    /**
     * Récupère le dernier sceau fiscal pour servir de lien à la chaîne.
     */
    static async getLastSeal(): Promise<FiscalSeal | undefined> {
        if (this.lastSealCache) return this.lastSealCache;

        // Mode Offline ou récupération locale prioritaire pour rapidité
        if (!checkOnlineStatus()) {
            const localSeal = await db.fiscalSeals.orderBy('timestamp').reverse().first();
            this.lastSealCache = localSeal;
            return localSeal;
        }

        try {
            const sealsPath = Nexus.getTenantPath('fiscalSeals');
            const results = await Nexus.adapter.query(sealsPath, {
                orderBy: { field: 'timestamp', direction: 'desc' },
                limit: 1
            });

            this.lastSealCache = results.length > 0 ? (results[0] as FiscalSeal) : undefined;
            return this.lastSealCache;
        } catch (error) {
            logger.warn('BlockchainLedgerService: Remote fetch failed, falling back to local', { error: toError(error).message });
            const fallback = await db.fiscalSeals.orderBy('timestamp').reverse().first();
            this.lastSealCache = fallback;
            return fallback;
        }
    }

    /**
     * Scelle une écriture en la liant à la chaîne existante.
     * GARANTIE D'ATOMICITÉ: Utilise une file d'attente de promesses.
     */
    static async sealWithChain(entryId: string, entryData: FiscalizableRecord, isTrainingMode: boolean = false): Promise<FiscalSeal> {
        // We chain the next seal to the previous one to avoid concurrency forks
        this.sealQueue = this.sealQueue.then(async () => {
            const lastSeal = await this.getLastSeal();
            const newSeal = await FiscalEngine.sealEntry(entryId, entryData, { 
                lastSeal, 
                isTrainingMode 
            });

            // Update cache and persist (Local optimization)
            this.lastSealCache = newSeal;

            // Note: Nexus.adapter handled persistence of the audit log elsewhere, 
            // but we ensure the chain is strictly linear here.
            return newSeal;
        });

        return this.sealQueue as Promise<FiscalSeal>;
    }

    /**
     * Vérifie l'intégralité de la chaîne (Audit de confiance).
     */
    static async auditFullChain(): Promise<boolean> {
        const sealsPath = Nexus.getTenantPath('fiscalSeals');
        const results = await Nexus.adapter.query(sealsPath, {
            orderBy: { field: 'timestamp', direction: 'asc' }
        });

        const seals = results as FiscalSeal[];
        return await FiscalEngine.verifyChain(seals);
    }

    /**
     * Clear context (Reset for testing or tenant swap)
     */
    static reset() {
        this.lastSealCache = undefined;
        this.sealQueue = Promise.resolve();
    }
}

