import { FiscalSeal } from '@nexus/contracts';
export type { FiscalSeal };
import { empireAudit } from '@/lib/audit';
import { CryptoService } from '@/lib/CryptoService';
import { FiscalKeyService } from '@modules/finance/services/FiscalKeyService';
import { SharedKernel } from '@/lib/shared-kernel';

/**
 * ⚖️ Fiscal Domain Constants (LNE / NF525 Standards)
 */
export const FISCAL_CONSTANTS = {
  GENESIS_ROOT: 'GENESIS_ROOT_0000000000000000',
  TRAINING_MODE_HASH: 'TRAINING_MODE_UNSIGNED_HASH',
  SIGNATURE_PREFIX: 'EMP_NF525_',
} as const;


export type FiscalizableRecord = Record<string, string | number | boolean | null | undefined | object>;

/** Première rupture détectée dans une chaîne de sceaux NF525. */
export interface ChainBreach {
  /** Écriture de journal concernée (transactionId, sinon id du sceau). */
  journalId: string;
  expectedHash: string;
  actualHash: string;
  /** `continuity` : maillon détaché. `content` : snapshot altéré. */
  kind: 'continuity' | 'content';
}

/**
 * 🏛️ FiscalEngine - Grade X "Industrial Titan"
 * Logic for Transaction Inalterability and Securization.
 * Compliant with NF525 Requirements.
 */
export const FiscalEngine = {
  /**
   * Seals a journal entry by creating a fiscal chain link
   */
  async sealEntry(
    transactionId: string, 
    data: FiscalizableRecord, 
    options: { lastSeal?: FiscalSeal, isTrainingMode?: boolean, instanceId?: string } = {}
  ): Promise<FiscalSeal> {
    const timestamp = new Date().toISOString();
    const dataSnapshot = CryptoService.canonicalStringify(data as import('@/shared/nexus-contract').SovereignData); 
    const id = SharedKernel.generateId('SEAL');

    const previousHash = options.lastSeal ? options.lastSeal.hash : FISCAL_CONSTANTS.GENESIS_ROOT;

    if (options.isTrainingMode) {
        return {
            id, transactionId, timestamp, dataSnapshot,
            hash: FISCAL_CONSTANTS.TRAINING_MODE_HASH,
            previousHash,
            signature: 'VTC_SCHOOL_TRAINING_SIGNATURE',
            updatedAt: new Date().toISOString()
        };
    }

    const hash = await CryptoService.generateHash(dataSnapshot, previousHash);
    // instanceId = index de lookup de la clé provisionnée — jamais le secret lui-même.
    const signature = await CryptoService.signFiscalData(hash, FiscalKeyService.requireKey(options.instanceId));

    const seal: FiscalSeal = { id, transactionId, previousHash, hash, dataSnapshot, timestamp, signature, updatedAt: new Date().toISOString() };

    empireAudit.log({
        module: 'accounting',
        action: 'TRANSACTION_SEALED',
        details: { sealId: id, hash: hash.substring(0, 8), transactionId },
        severity: 'low',
        timestamp: new Date()
    });

    return seal;
  },

  /**
   * 🛡️ NF525: Chain Integrity Verification (Grade X Suture)
   *
   * Localise la PREMIÈRE rupture et la décrit. `verifyChain` conserve l'API
   * booléenne ; `runAudit` s'appuie sur le détail pour produire la preuve légale.
   */
  async inspectChain(seals: FiscalSeal[]): Promise<ChainBreach | null> {
      for (let i = 0; i < seals.length; i++) {
          const current = seals[i];

          // Continuité de chaîne : le maillon ne référence pas son prédécesseur.
          if (i > 0 && current.previousHash !== seals[i - 1].hash) {
              return {
                  journalId: current.transactionId ?? current.id ?? "unknown",
                  expectedHash: seals[i - 1].hash,
                  actualHash: current.previousHash ?? '',
                  kind: 'continuity',
              };
          }

          // Intégrité de contenu : le snapshot ne produit plus le hash scellé.
          const computedHash = await CryptoService.generateHash(
              current.dataSnapshot ?? "",
              current.previousHash ?? FISCAL_CONSTANTS.GENESIS_ROOT
          );
          if (computedHash !== current.hash) {
              return {
                  journalId: current.transactionId ?? current.id ?? "unknown",
                  expectedHash: current.hash,
                  actualHash: computedHash,
                  kind: 'content',
              };
          }
      }
      return null;
  },

  async verifyChain(seals: FiscalSeal[]): Promise<boolean> {
      return (await this.inspectChain(seals)) === null;
  },

  /**
   * 🛡️ Comprehensive Audit (Grade X)
   *
   * Une rupture détectée émet `crypto.integrity_failed` : CryptoIntegrityHandler
   * persiste alors la preuve dans `fiscalIntegrityBreaches` (tenant) et
   * `mccFiscalBreaches` (super admin) pour l'administration fiscale. Sans cette
   * émission, le handler était abonné à un événement que personne ne produisait —
   * une rupture NF525 restait donc totalement silencieuse.
   */
  async runAudit(seals: FiscalSeal[], instanceId: string = 'default'): Promise<{
      success: boolean;
      integrity: boolean;
      sealedCount: number;
      timestamp: string;
  }> {
      const breach = await this.inspectChain(seals);

      if (breach) {
          const detectedAt = Date.now();
          empireAudit.log({
              module: 'accounting',
              action: 'FISCAL_CHAIN_BREACH',
              details: { ...breach, tenantId: instanceId },
              severity: 'critical',
              timestamp: new Date(),
          });
          // Import dynamique : le bus ne doit pas entrer dans le graphe
          // d'initialisation du domaine fiscal.
          try {
              const { NexusEventBus } = await import('@/shared/eventBus/NexusEventBus');
              await NexusEventBus.emitDurable('crypto.integrity_failed', {
                  v: 1,
                  tenantId: instanceId,
                  journalId: breach.journalId,
                  expectedHash: breach.expectedHash,
                  actualHash: breach.actualHash,
                  detectedAt,
              });
          } catch (emitError) {
              // L'échec d'alerte ne doit pas masquer le verdict d'intégrité.
              empireAudit.log({
                  module: 'accounting',
                  action: 'FISCAL_CHAIN_BREACH_ALERT_FAILED',
                  details: { reason: String(emitError) },
                  severity: 'critical',
                  timestamp: new Date(),
              });
          }
      }

      return {
          success: !breach,
          integrity: !breach,
          sealedCount: seals.length,
          timestamp: new Date().toISOString()
      };
  }
};

import { Nexus } from '@/lib/nexus/NexusAdapter';
import { FISCAL_CONSTANTS } from './FiscalAdapter';
import { CryptoService } from '@/lib/CryptoService';
import { FiscalKeyService } from '@modules/finance/services/FiscalKeyService';
import type { FiscalSeal } from '@nexus/contracts';
import { IdGenerator } from '@/lib/utils/IdGenerator';
import type { INexusTransaction } from '@/lib/nexus/types';

export class FiscalSealer {
  /**
   * 🏛️ NF525 Sequential Receipt Numbering (Grade X)
   *
   * Uses an atomic Firestore transaction to guarantee strictly sequential
   * receipt numbers per tenant per year. The counter document lives at
   * `tenants/{tenantId}/fiscalMeta/receiptCounter`.
   *
   * Format: {YEAR}-{COUNTER} (e.g. 2026-000042)
   *
   * Replaces the previous timestamp+random approach which did not guarantee
   * sequential ordering as required by the NF525 certification standard.
   */
  static async generateSequentialReceiptNumber(tenantId: string): Promise<string> {
    const year = new Date().getFullYear().toString();
    const counterPath = `tenants/${tenantId}/fiscalMeta/receiptCounter`;

    let nextNumber: number = 1;
    await Nexus.adapter.runTransaction(async (tx) => {
      const doc = await tx.get<{ year: string; counter: number }>(counterPath);
      if (doc && doc.year === year) {
        nextNumber = (doc.counter ?? 0) + 1;
      } else {
        // New year or first receipt ever — reset counter
        nextNumber = 1;
      }
      tx.set(counterPath, { year, counter: nextNumber, updatedAt: new Date().toISOString() });
    });

    return `${year}-${String(nextNumber).padStart(6, '0')}`;
  }

  /**
   * @deprecated Use generateSequentialReceiptNumber(tenantId) for NF525 compliance.
   * Kept for offline/training fallback only.
   */
  static generateReceiptNumberFallback(): string {
    const year = new Date().getFullYear().toString();
    const ts = Date.now().toString(36).toUpperCase();
    const rnd = Math.random().toString(36).slice(2, 6).toUpperCase();
    return `${year}-${ts}-${rnd}`;
  }

  static async getLastSeal(tenantId: string): Promise<FiscalSeal | undefined> {
    try {
      const seals = await Nexus.adapter.query<FiscalSeal>(
        `tenants/${tenantId}/fiscalSeals`,
        { orderBy: { field: 'timestamp', direction: 'desc' }, limit: 1 }
      );
      return seals[0];
    } catch {
      return undefined;
    }
  }

  static async sealData(dataSnapshot: string, tenantId: string, isTrainingMode: boolean, previousHash: string) {
    let hash: string;
    let signature: string;

    if (isTrainingMode) {
      hash = FISCAL_CONSTANTS.TRAINING_MODE_HASH;
      signature = 'VTC_SCHOOL_TRAINING_SIGNATURE';
    } else {
      hash = await CryptoService.generateHash(dataSnapshot, previousHash);
      // Le tenantId sert d'index de lookup — la clé vient de FiscalKeyService.
      signature = await CryptoService.signFiscalData(hash, FiscalKeyService.requireKey(tenantId));
    }

    return { hash, signature, isTrainingMode, ...(isTrainingMode ? { taxExempt: true } : {}) };
  }

  /**
   * Atomic NF525 seal — reads previousHash and writes the new seal inside a
   * single adapter transaction (auto-retries on conflict in Firestore, sequential
   * in Simulacra/Mock). Works across all adapters (agnostic).
   *
   * Pattern: a fixed-path `chainHead` document carries the current chain tip.
   * The transaction reads chainHead → computes hash → writes new seal + updates
   * chainHead, all atomically. Prevents hash-chain forks under concurrent sealing.
   *
   * chainHead path: tenants/{tenantId}/fiscalMeta/chainHead
   */
  static async sealDataAtomically(
    dataSnapshot: string,
    tenantId: string,
    isTrainingMode: boolean,
    journalEntry?: Record<string, unknown> & { id: string },
    additionalMutations?: (tx: INexusTransaction, sealId: string) => void
  ): Promise<{ hash: string; signature: string; sealId: string; previousHash: string }> {
    const sealId = IdGenerator.generateWithPrefix('seal');
    const sealPath = `tenants/${tenantId}/fiscalSeals/${sealId}`;
    const chainHeadPath = `tenants/${tenantId}/fiscalMeta/chainHead`;

    let hash: string;
    let signature: string;
    let prevHash: string;

    // Horodatage déclaré (entre dans le hash/snapshot — compatibilité chaîne).
    const timestamp = new Date().toISOString();
    // Horodatage AUTORITAIRE serveur : Firestore résout serverTimestamp() côté
    // serveur au moment de l'écriture — même émis depuis le client, il est donc
    // immunisé contre une horloge locale falsifiée. C'est la référence probante
    // NF525 pour dater la pièce (l'horloge client n'est plus la seule source).
    const serverRecordedAt = Nexus.adapter.serverTimestamp();

    if (isTrainingMode) {
      hash = FISCAL_CONSTANTS.TRAINING_MODE_HASH;
      signature = 'VTC_SCHOOL_TRAINING_SIGNATURE';
      prevHash = FISCAL_CONSTANTS.GENESIS_ROOT;
      await Nexus.adapter.runTransaction(async (tx) => {
        tx.set(sealPath, {
          id: sealId, hash, signature,
          previousHash: FISCAL_CONSTANTS.GENESIS_ROOT,
          dataSnapshot,
          timestamp,
          serverRecordedAt,
          isTrainingMode: true,
        } as unknown);
        tx.set(chainHeadPath, { hash, sealId, updatedAt: timestamp });
        if (journalEntry) {
           tx.set(`tenants/${tenantId}/journalEntries/${journalEntry.id}`, {
             ...journalEntry,
             fiscalSealHash: hash,
             sealedAt: timestamp,
             serverRecordedAt,
             updatedAt: timestamp
           });
        }
        if (additionalMutations) additionalMutations(tx, sealId);
      });
    } else {
      await Nexus.adapter.runTransaction(async (tx) => {
        const head = await tx.get<{ hash?: string }>(chainHeadPath);
        const previousHash = head?.hash ?? FISCAL_CONSTANTS.GENESIS_ROOT;
        prevHash = previousHash;

        hash = await CryptoService.generateHash(dataSnapshot, previousHash);
        signature = await CryptoService.signFiscalData(hash, FiscalKeyService.requireKey(tenantId));

        tx.set(sealPath, {
          id: sealId, hash, signature, previousHash,
          dataSnapshot,
          timestamp,
          serverRecordedAt,
          isTrainingMode: false,
        } as unknown);
        tx.set(chainHeadPath, { hash, sealId, updatedAt: timestamp });
        if (journalEntry) {
           tx.set(`tenants/${tenantId}/journalEntries/${journalEntry.id}`, {
             ...journalEntry,
             fiscalSealHash: hash,
             sealedAt: timestamp,
             serverRecordedAt,
             updatedAt: timestamp
           });
        }
        if (additionalMutations) additionalMutations(tx, sealId);
      });
    }

    return { hash: hash!, signature: signature!, sealId, previousHash: prevHash! };
  }
}

import { CA3Declaration, EDISubmissionResult, TaxBreakdown } from './types';
import { EDIMapper } from './EDIMapper';
import { DocumentVault } from '@/modules/compliance/securite/DocumentVault';
import { QuantumCrypto } from '@/lib/QuantumCrypto';
import { NexusTelemetryService } from '@/lib/NexusTelemetryService';
import { SovereignLedger } from '../../services/SovereignLedger';

/**
 * 🏛️ FiscalTransmitter - Grade X+++
 * Déclarations TVA EDI et transmission DGFiP via partenaire EDI.
 */
export class FiscalTransmitter {

    /**
     * Génère, transmet et archive la déclaration TVA (CA3)
     */
    static async transmitCA3(tenantId: string, siren: string, period: string): Promise<EDISubmissionResult> {
        NexusTelemetryService.emitAuditPulse('COMPLIANCE', 'CA3_TRANSMISSION_STARTED', { period });

        // 1. Extraction de la breakdown (Simulation via le Ledger)
        const breakdown = await this.extractTaxBreakdown();

        const declaration: CA3Declaration = {
            period,
            siren,
            breakdown,
            generatedAt: new Date().toISOString()
        };

        // 2. Transformation XML (Format TDFC)
        const xmlContent = EDIMapper.toTDFC(declaration);

        // 3. Transmission EDI via Provider (Simulation Jedéclare)
        const submissionResult = await this.transmitToEDIProvider(xmlContent);

        if (submissionResult.success && submissionResult.status === 'ACCEPTED') {
            // 4. Scellage et archivage WORM du récépissé
            const receiptHash = await QuantumCrypto.sign(xmlContent);
            submissionResult.dgfipReceiptHash = receiptHash;

            await DocumentVault.archive(`CA3_RECEIPT_${period}.xml`, xmlContent, {
                tenantId,
                type: 'TAX_DECLARATION',
                period,
                hash: receiptHash
            });

            // 5. Suture Financière: Provisionnement de la TVA à décaisser
            await SovereignLedger.getInstance(tenantId).recordTransfer({
                debitAccount: 'TAX_COLLECTED_4457',
                creditAccount: 'TAX_TO_PAY_4455',
                amountInCents: breakdown.netTaxToPayInCents,
                referenceId: `TVA-${period}`,
                description: `Liquidation TVA Période ${period}`
            });

            NexusTelemetryService.emitAuditPulse('COMPLIANCE', 'CA3_TRANSMISSION_SUCCESS', { 
                period, 
                receiptHash 
            });
        } else {
            NexusTelemetryService.emitAuditPulse('COMPLIANCE', 'CA3_TRANSMISSION_FAILED', { 
                period, 
                errors: submissionResult.errors 
            });
        }

        return submissionResult;
    }

    /**
     * Extrait les données fiscales du Ledger (Stub pour le module)
     */
    private static async extractTaxBreakdown(): Promise<TaxBreakdown> {
        // En conditions réelles, cette méthode interroge le SovereignLedger
        // pour calculer la base HT et la TVA collectée/déductible.
        return {
            totalRevenueInCents: 5000000,
            totalRevenueInMicrounits: 5000000 * 10_000,
            taxBaseByRate: { "20.0": 4000000, "10.0": 1000000 },
            taxCollectedByRate: { "20.0": 800000, "10.0": 100000 },
            totalTaxCollectedInCents: 900000,
            totalTaxCollectedInMicrounits: 900000 * 10_000,
            deductibleTaxInCents: 200000,
            deductibleTaxInMicrounits: 200000 * 10_000,
            netTaxToPayInCents: 700000,
            netTaxToPayInMicrounits: 700000 * 10_000,
        };
    }

    /**
     * Transmission vers le partenaire EDI (ex: Jedéclare)
     */
    private static async transmitToEDIProvider(_xmlContent: string): Promise<EDISubmissionResult> {
        // Stub: Simulation de réponse du partenaire EDI
        return {
            success: true,
            submissionId: `EDI_${Date.now()}`,
            status: 'ACCEPTED'
        };
    }
}

import type { TaxRate } from '@/modules/finance/domain/schemas/finance';
