export interface NexusFiscalState {
    accounting: {
        entries: JournalEntry[];
        accounts: Account[];
        bankTransactions: BankTransaction[];
        expenseClaims: ExpenseClaim[];
        isLoading: boolean;
        metrics: { netProfitInMicrounits: number };
