function startAuthAwarePolling(
  refreshFleet: (bg?: boolean) => Promise<void>,
  onCleanup: (cleanup: () => void) => void
) {
  let cancelled = false;
  let intervalId: ReturnType<typeof setInterval> | null = null;

  const startPolling = () => {
    if (cancelled || intervalId) return;
    refreshFleet();
    intervalId = setInterval(() => refreshFleet(true), 120000);
  };

  import('@/lib/firebase').then(({ auth }) => {
    if (cancelled) return;
    const unsub = auth.onAuthStateChanged(user => {
      if (cancelled) return;
      const devBypass = MCC_DEV_MODE_CLIENT;
      if (user || devBypass) {
        startPolling();
      } else if (intervalId) {
        clearInterval(intervalId);
        intervalId = null;
      }
    });
    onCleanup(() => unsub());
  }).catch(() => { /* firebase absent — skip polling */ });

  return () => {
    cancelled = true;
    if (intervalId) clearInterval(intervalId);
  };
}

