                                    </>
                                )}
                            </button>
                        </div>
                    )}
                </motion.div>
            </motion.div>
        </AnimatePresence>
    );
}

"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { ChefHat, Clock, CheckCircle2, UtensilsCrossed } from "lucide-react";
import { cn } from "@/lib/ui.foundations";
// FIXME (Modular Monolith): Remove cross-module import. Use domain/ or NexusEventBus.

import { CartItem, CourseType } from "@modules/ops/workflow/engine/types";
import { formatCurrency } from "@/lib/formatters";
import { SovereignMath } from "@/shared/services/SovereignMath";

// ─── Types ────────────────────────────────────────────────────────────────────

interface CourseManagerProps {
    items: CartItem[];
    onSetCourse: (cartId: string, course: CourseType | undefined) => void;
    onSendCourse: (course: CourseType) => Promise<void>;
    isLoading?: boolean;
}

// ─── Course meta ──────────────────────────────────────────────────────────────

const COURSE_ORDER: CourseType[] = ["entree", "plat", "dessert"];

const COURSE_META: Record<CourseType, { label: string; icon: React.ElementType; color: string }> = {
    entree:  { label: "Entrées",  icon: UtensilsCrossed, color: "text-status-success bg-emerald-400/10 border-emerald-400/30" },
    plat:    { label: "Plats",    icon: ChefHat,         color: "text-accent-gold bg-accent-gold/10 border-accent-gold/30" },
    dessert: { label: "Desserts", icon: UtensilsCrossed, color: "text-purple-400 bg-purple-400/10 border-purple-400/30" },
};

// ─── CourseChip ───────────────────────────────────────────────────────────────

function CourseChip({
    active,
    course,
    onClick,
}: {
    active: boolean;
    course: CourseType;
    onClick: () => void;
}) {
    const meta = COURSE_META[course];
    return (
        <button
            onClick={onClick}
            className={cn(
                "px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border transition-all",
                active
                    ? meta.color
                    : "border-border text-text-muted bg-bg-tertiary hover:border-border/80"
            )}
        >
            {meta.label}
        </button>
    );
}

// ─── CourseSection ────────────────────────────────────────────────────────────

function CourseSection({
    course,
    items,
    onSendCourse,
    isSending,
}: {
    course: CourseType;
    items: CartItem[];
    onSendCourse: () => void;
    isSending: boolean;
}) {
    const meta = COURSE_META[course];
    const Icon = meta.icon;

    const sentItems    = items.filter((i) => i.sentAt);
    const pendingItems = items.filter((i) => !i.sentAt);
    const allSent      = items.length > 0 && pendingItems.length === 0;

    if (items.length === 0) return null;

    return (
        <div className="rounded-2xl border border-border/60 overflow-hidden">
            {/* Section header */}
            <div className={cn("flex items-center justify-between px-4 py-3 border-b border-border/40 bg-bg-tertiary/50")}>
                <div className="flex items-center gap-2">
                    <Icon className={cn("w-4 h-4", meta.color.split(" ")[0])} />
                    <span className="text-[10px] font-black uppercase tracking-widest text-text-primary">
                        {meta.label}
                    </span>
                    <span className="text-[9px] text-text-muted">
                        ({items.length} article{items.length > 1 ? "s" : ""})
                    </span>
                </div>

                {allSent ? (
                    <div className="flex items-center gap-1.5 text-status-success">
                        <CheckCircle2 className="w-3.5 h-3.5" />
                        <span className="text-[9px] font-black uppercase tracking-wider">Envoyé</span>
                    </div>
                ) : pendingItems.length > 0 ? (
                    <button
                        onClick={onSendCourse}
                        disabled={isSending}
                        className="flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-accent-gold text-text-primary text-[9px] font-black uppercase tracking-widest hover:bg-accent-gold/90 active:scale-95 transition-all disabled:opacity-50"
                    >
                        <ChefHat className="w-3 h-3" />
                        Envoyer
                    </button>
                ) : null}
            </div>

            {/* Items */}
            <div className="divide-y divide-border/30">
                {items.map((item) => (
                    <div key={item.cartId} className="flex items-center gap-3 px-4 py-2.5">
                        {/* Sent indicator */}
                        <div className={cn(
                            "w-1.5 h-1.5 rounded-full shrink-0",
                            item.sentAt ? "bg-status-success" : "bg-border"
                        )} />

                        <span className={cn(
                            "flex-1 text-[12px] font-medium",
                            item.sentAt ? "text-text-muted line-through" : "text-text-primary"
                        )}>
                            {item.name}
                        </span>

                        <span className="text-[10px] text-text-muted tabular-nums">
                            x{item.quantity}
                        </span>

                        <span className="text-[11px] font-mono text-text-muted tabular-nums">
                            {formatCurrency(SovereignMath.toCents(BigInt(item.unitPriceInMicrounits * item.quantity)))}
                        </span>

                        {item.sentAt && (
                            <div className="flex items-center gap-1 text-text-muted">
                                <Clock className="w-3 h-3" />
                                <span className="text-[9px]">
                                    {new Date(item.sentAt).toLocaleTimeString("fr-FR", { hour: "2-digit", minute: "2-digit" })}
                                </span>
                            </div>
                        )}
                    </div>
                ))}
            </div>

            {sentItems.length > 0 && pendingItems.length > 0 && (
                <div className="px-4 py-1.5 bg-status-success/5 border-t border-status-success/10">
                    <span className="text-[9px] text-status-success font-bold">
                        {sentItems.length} envoyé{sentItems.length > 1 ? "s" : ""} · {pendingItems.length} en attente
                    </span>
                </div>
            )}
        </div>
    );
}

// ─── CourseManager ────────────────────────────────────────────────────────────

export function CourseManager({ items, onSetCourse, onSendCourse, isLoading }: CourseManagerProps) {
    const [sending, setSending] = useState<CourseType | null>(null);

    const unassigned = items.filter((i) => !i.course);

    async function fireCourse(course: CourseType) {
        setSending(course);
        try {
            await onSendCourse(course);
        } finally {
            setSending(null);
        }
    }

    if (items.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center py-12 text-text-muted gap-3">
                <UtensilsCrossed className="w-8 h-8 opacity-30" />
                <p className="text-[11px] uppercase tracking-widest font-bold">Panier vide</p>
            </div>
        );
    }

    return (
        <div className="flex flex-col gap-4 p-4">
            {/* ── Unassigned items ──── */}
            <AnimatePresence>
                {unassigned.length > 0 && (
                    <motion.div
                        key="unassigned"
                        initial={{ opacity: 0, y: 8 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0 }}
                        className="rounded-2xl border border-dashed border-border/60 overflow-hidden"
                    >
                        <div className="px-4 py-2.5 bg-bg-tertiary/30 border-b border-border/30">
                            <span className="text-[9px] font-black uppercase tracking-widest text-text-muted">
                                Sans cours ({unassigned.length})
                            </span>
                        </div>
                        <div className="divide-y divide-border/30">
                            {unassigned.map((item) => (
                                <div key={item.cartId} className="px-4 py-2.5">
                                    <div className="flex items-center gap-2 mb-2">
                                        <span className="text-[12px] font-medium text-text-primary flex-1">{item.name}</span>
                                        <span className="text-[10px] text-text-muted">x{item.quantity}</span>
                                    </div>
                                    <div className="flex gap-1.5 flex-wrap">
                                        {COURSE_ORDER.map((course) => (
                                            <CourseChip
                                                key={course}
                                                course={course}
                                                active={false}
                                                onClick={() => onSetCourse(item.cartId, course)}
                                            />
                                        ))}
                                    </div>
                                </div>
                            ))}
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* ── Course sections ──── */}
            {COURSE_ORDER.map((course) => {
                const courseItems = items.filter((i) => i.course === course);
                return (
                    <AnimatePresence key={course}>
                        {courseItems.length > 0 && (
                            <motion.div
                                key={`course-${course}`}
                                initial={{ opacity: 0, y: 8 }}
                                animate={{ opacity: 1, y: 0 }}
                                exit={{ opacity: 0 }}
                            >
                                <CourseSection
                                    course={course}
                                    items={courseItems}
                                    onSendCourse={() => fireCourse(course)}
                                    isSending={sending === course || !!isLoading}
                                />
                            </motion.div>
                        )}
                    </AnimatePresence>
                );
            })}
        </div>
    );
}

"use client";

import { useState, useRef } from "react";
import { CreditCard, Banknote, Smartphone, CheckCircle, Loader2, Sparkles, Receipt, X, ArrowRight, AlertCircle, Terminal } from "lucide-react";
import { cn } from "@/lib/ui.foundations";;
import { Modal } from "@ui/Modal";
import { useLanguage } from "@/shared/hooks";
import { formatCurrency } from "@/lib/formatters";;
import { terminalService } from "@/modules/ops/service/pos/infrastructure/payment-terminal/PaymentTerminalService";
import type { PaymentResult } from "@/modules/ops/service/pos/infrastructure/payment-terminal/types";
import { printerService } from "@/modules/ops/service/printers/hardware/PrintingService";

interface PaymentDialogProps {
    isOpen: boolean;
    /** Amount in cents */
    total: number;
    /** TVA réelle du panier en cents (calculée par usePOSController) */
    tvaInCents?: number;
    orderId?: string;
    onClose: () => void;
    onPaymentComplete: () => Promise<string | void>;
}

type PaymentMethod = "card" | "cash" | "mobile";

type TerminalState = "idle" | "pending" | "manual_wait" | "error";

function applyHashIfPresent(hash: string | void, setCertifiedHash: (h: string) => void): void {
    if (hash) setCertifiedHash(hash);
}

export function PaymentDialog({ isOpen, total, tvaInCents, orderId, onClose, onPaymentComplete }: PaymentDialogProps) {
    const [method, setMethod] = useState<PaymentMethod | null>(null);
    const [isProcessing, setIsProcessing] = useState(false);
    const [isSuccess, setIsSuccess] = useState(false);
    const [certifiedHash, setCertifiedHash] = useState<string | null>(null);
    const [terminalState, setTerminalState] = useState<TerminalState>("idle");
    const [terminalError, setTerminalError] = useState<string | null>(null);
    const { t } = useLanguage();

    // Used to let the ManualAdapter know the operator confirmed
    const manualAdapterRef = useRef<ReturnType<typeof terminalService.getManualAdapter>>(null);
    const defaultDeviceRef = useRef<string | null>(null);

    if (!isOpen) return null;

    const amountInMicrounits = total * 10_000;

    const handleProcessPayment = async () => {
        if (method === "card") {
            await handleCardPayment();
        } else {
            await handleDirectPayment();
        }
    };

    const handleCardPayment = async () => {
        setTerminalState("pending");
        setTerminalError(null);

        const defaultDevice = terminalService.getDefault();
        defaultDeviceRef.current = defaultDevice?.id ?? null;

        let result: PaymentResult;
        try {
            if (defaultDevice?.adapter === "manual") {
                setTerminalState("manual_wait");
                // Ensure connected
                if (terminalService.getStatus(defaultDevice.id) === "disconnected") {
                    await terminalService.connect(defaultDevice.id);
                }
                manualAdapterRef.current = terminalService.getManualAdapter(defaultDevice.id);
            } else {
                setTerminalState("pending");
            }

            result = await terminalService.charge({
                amountInMicrounits,
                orderId: orderId ?? `ORDER_${Date.now()}`,
                description: `Commande POS`,
            });
        } catch (err) {
            setTerminalState("error");
            setTerminalError(err instanceof Error ? err.message : "Erreur terminal");
            return;
        }

        if (result.status === "approved") {
            setTerminalState("idle");
            setIsProcessing(true);
            try {
                const hash = await onPaymentComplete();
                applyHashIfPresent(hash, setCertifiedHash);
                setIsSuccess(true);
            } finally {
                setIsProcessing(false);
            }
        } else if (result.status === "cancelled") {
            setTerminalState("idle");
            setMethod(null);
        } else {
            setTerminalState("error");
            setTerminalError(result.error ?? "Paiement refusé");
        }
    };

    const handleDirectPayment = async () => {
        setIsProcessing(true);
        try {
            if (method === "cash") {
                printerService.openCashDrawer();
            }
            const hash = await onPaymentComplete();
            applyHashIfPresent(hash, setCertifiedHash);
            setIsSuccess(true);
        } catch {
            /* toast handled upstream */
        } finally {
            setIsProcessing(false);
        }
    };

    const handleManualConfirm = () => {
        manualAdapterRef.current?.confirmPayment(amountInMicrounits);
        manualAdapterRef.current = null;
        setTerminalState("pending");
    };

    const handleManualCancel = () => {
        manualAdapterRef.current?.cancelPayment();
        manualAdapterRef.current = null;
        setTerminalState("idle");
        setMethod(null);
    };

    const handleTerminalCancel = async () => {
        if (defaultDeviceRef.current) {
            await terminalService.cancelCurrent(defaultDeviceRef.current).catch(() => {});
        }
        setTerminalState("idle");
        setMethod(null);
    };

    const isTerminalBusy = terminalState === "pending" || terminalState === "manual_wait";

    return (
        <Modal
            isOpen={isOpen}
            onClose={isTerminalBusy ? () => {} : onClose}
            size="lg"
            className="p-0 border-none bg-transparent"
            showClose={false}
            noPadding
        >
            <div className="bg-bg-secondary w-full overflow-hidden relative border border-border/50 h-auto min-h-[600px] flex flex-col rounded-[3rem]">

                <div className="absolute top-0 right-0 w-48 h-48 bg-accent-gold/5 rounded-full blur-[100px] -mr-24 -mt-24 pointer-events-none" />
                <div className="absolute bottom-0 left-0 w-48 h-48 bg-accent-gold/5 rounded-full blur-[100px] -ml-24 -mb-24 pointer-events-none" />

                {isSuccess ? (
                    <div className="flex flex-col items-center justify-center p-16 md:p-24 space-y-10 animate-in fade-in slide-in-from-bottom-12 duration-1000 flex-1">
                        <div className="relative">
                            <div className="w-32 h-32 bg-accent-gold/10 rounded-full flex items-center justify-center text-accent-gold shadow-premium border border-accent-gold/20">
                                <CheckCircle className="w-16 h-16" strokeWidth={1} />
                            </div>
                            <div className="absolute -top-2 -right-2 w-10 h-10 bg-accent-gold rounded-2xl flex items-center justify-center text-text-primary shadow-premium animate-bounce">
                                <Sparkles className="w-5 h-5" />
                            </div>
                        </div>
                        <div className="text-center space-y-4">
                            <h2 className="text-4xl font-serif font-black text-text-primary tracking-tighter italic">{t('pos.payment.transaction_success')}</h2>
                            <p className="text-[10px] font-black text-text-muted uppercase tracking-[0.4em]">{t('pos.payment.archive_updated')}</p>
                            <div className="mt-6 p-4 bg-surface-sidebar/40 rounded-2xl border border-accent-gold/20 backdrop-blur-md">
                                <p className="text-[8px] font-black text-accent-gold/60 uppercase tracking-widest mb-1">NF525 Certified Seal</p>
                                <p className="text-[10px] font-mono text-accent-gold break-all font-bold">
                                    SHA256: {certifiedHash?.substring(0, 32) || 'NOT_AVAILABLE'}...CERTIFIED
                                </p>
                            </div>
                        </div>
                        <div className="w-full h-px bg-gradient-to-r from-transparent via-border to-transparent" />
                        <div className="flex items-center gap-4 text-[10px] font-black uppercase text-accent-gold tracking-[0.3em] bg-accent-gold/5 px-6 py-3 rounded-full border border-accent-gold/10">
                            <Receipt className="w-4 h-4 ml-[-4px]" />
                            {t('pos.payment.generating_receipt')}
                        </div>
                    </div>

                ) : (
