        const atomicDecrement = async () => {
            // Atomic operation simulation
            mockDbStock -= 1;
        };

        await Promise.all([
            atomicDecrement(),
            atomicDecrement(),
            atomicDecrement(),
            atomicDecrement()
        ]);

        if (mockDbStock === 96) {
