"use client";

import { useState, useEffect, useCallback } from "react";
import {
  Printer, Plus, Trash2, Star, CheckCircle2, AlertCircle, Loader2,
} from "lucide-react";
import { printerService } from "@/modules/ops/service/printers/hardware/PrintingService";
import type { PrinterDevice, PrinterRole, PrinterConnection } from "@/modules/ops/service/printers/hardware/types";
import { BRAND_LABELS, ROLE_LABELS, CONNECTION_LABELS } from "@/modules/ops/service/printers/hardware/types";
import { CONN_ICON, AddPrinterWizard } from '@/modules/ops';

const ROLE_COLORS: Record<PrinterRole, string> = {
  receipt: "text-status-success",
  kitchen: "text-orange-500",
  bar:     "text-sky-500",
  label:   "text-purple-500",
};

type TestStatus = "idle" | "testing" | "ok" | "error";

export default function PrinterSettings() {
  const [printers, setPrinters] = useState<PrinterDevice[]>([]);
  const [showWizard, setShowWizard] = useState(false);
  const [testStatus, setTestStatus] = useState<Record<string, TestStatus>>({});

  const refresh = useCallback(() => setPrinters(printerService.getAll()), []);
  useEffect(() => { refresh(); }, [refresh]);

  const handleTest = useCallback(async (printer: PrinterDevice) => {
    setTestStatus(s => ({ ...s, [printer.id]: "testing" }));
    const result = await printerService.testPrint(printer);
    setTestStatus(s => ({ ...s, [printer.id]: result.success ? "ok" : "error" }));
    setTimeout(() => setTestStatus(s => ({ ...s, [printer.id]: "idle" })), 3000);
  }, []);

  const handleRemove = useCallback((id: string) => {
    printerService.remove(id);
    refresh();
  }, [refresh]);

  const handleSetDefault = useCallback((id: string) => {
    printerService.setDefault(id);
    refresh();
  }, [refresh]);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-brand text-text-primary italic">Imprimantes</h2>
          <p className="text-xs text-text-muted mt-0.5">WiFi · Bluetooth · USB · Série · Navigateur</p>
        </div>
        <button
          onClick={() => setShowWizard(true)}
          className="inline-flex items-center gap-2 px-4 py-2.5 rounded-xl bg-action-primary text-bg-primary text-xs font-black uppercase tracking-widest hover:opacity-90 transition-opacity"
        >
          <Plus className="w-3.5 h-3.5" />
          Ajouter
        </button>
      </div>

      {printers.length === 0 ? (
        <EmptyState onAdd={() => setShowWizard(true)} />
      ) : (
        <div className="space-y-3">
          {printers.map(p => (
            <PrinterCard
              key={p.id}
              printer={p}
              testStatus={testStatus[p.id] ?? "idle"}
              onTest={() => handleTest(p)}
              onRemove={() => handleRemove(p.id)}
              onSetDefault={() => handleSetDefault(p.id)}
            />
          ))}
        </div>
      )}

      <div className="rounded-2xl border border-border bg-bg-secondary p-5">
        <p className="text-xs text-text-muted">
          <span className="text-text-primary font-semibold">Fallback navigateur</span> — si aucune
          imprimante n&apos;est configurée pour un rôle, le système bascule automatiquement sur
          <code className="mx-1 text-action-primary">window.print()</code> (dialogue d&apos;impression du navigateur).
        </p>
      </div>

      {showWizard && (
        <AddPrinterWizard
          onClose={() => setShowWizard(false)}
          onAdded={() => { refresh(); setShowWizard(false); }}
        />
      )}
    </div>
  );
}

function PrinterCard({
  printer, testStatus, onTest, onRemove, onSetDefault,
}: {
  printer: PrinterDevice;
  testStatus: TestStatus;
  onTest(): void;
  onRemove(): void;
  onSetDefault(): void;
}) {
  const connLabel  = CONNECTION_LABELS[printer.connection.type];
  const connDetail = getConnDetail(printer.connection);

  return (
    <div className={`rounded-2xl border p-5 transition-all ${printer.enabled ? "border-border bg-bg-secondary" : "border-border/50 bg-bg-secondary/50 opacity-60"}`}>
      <div className="flex items-start gap-4">
        <div className={`w-10 h-10 rounded-xl bg-bg-tertiary flex items-center justify-center shrink-0 ${ROLE_COLORS[printer.role]}`}>
          {CONN_ICON[printer.connection.type]}
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 flex-wrap">
            <span className="text-sm font-semibold text-text-primary">{printer.name}</span>
            {printer.isDefault && (
              <span className="inline-flex items-center gap-1 text-[9px] font-black uppercase tracking-widest text-action-primary bg-action-primary/10 border border-action-primary/20 px-2 py-0.5 rounded-full">
                <Star className="w-2.5 h-2.5" /> Défaut
              </span>
            )}
          </div>
          <div className="flex items-center gap-3 mt-1 flex-wrap text-xs text-text-muted">
            <span className={ROLE_COLORS[printer.role]}>{ROLE_LABELS[printer.role]}</span>
            <span>·</span>
            <span>{BRAND_LABELS[printer.brand]}</span>
            <span>·</span>
            <span>{connLabel}</span>
            {connDetail && <><span>·</span><span className="font-mono">{connDetail}</span></>}
            <span>·</span>
            <span>{printer.paperWidth}mm</span>
          </div>
        </div>
        <div className="flex items-center gap-2 shrink-0">
          {!printer.isDefault && (
            <button onClick={onSetDefault} title="Définir par défaut"
              className="w-8 h-8 rounded-lg hover:bg-bg-tertiary flex items-center justify-center text-text-muted hover:text-action-primary transition-colors">
              <Star className="w-3.5 h-3.5" />
            </button>
          )}
          <TestButton status={testStatus} onClick={onTest} />
          <button onClick={onRemove} title="Supprimer"
            className="w-8 h-8 rounded-lg hover:bg-danger/10 flex items-center justify-center text-text-muted hover:text-danger transition-colors">
            <Trash2 className="w-3.5 h-3.5" />
          </button>
        </div>
      </div>
    </div>
  );
}

function TestButton({ status, onClick }: { status: TestStatus; onClick(): void }) {
  const map: Record<TestStatus, { icon: React.ReactNode; label: string; cls: string }> = {
    idle:    { icon: <Printer className="w-3.5 h-3.5" />, label: "Test", cls: "text-text-muted hover:text-action-primary hover:bg-action-primary/10" },
    testing: { icon: <Loader2 className="w-3.5 h-3.5 animate-spin" />, label: "…", cls: "text-action-primary" },
    ok:      { icon: <CheckCircle2 className="w-3.5 h-3.5" />, label: "OK", cls: "text-success bg-success/10" },
    error:   { icon: <AlertCircle className="w-3.5 h-3.5" />, label: "Err", cls: "text-danger bg-danger/10" },
  };
  const { icon, label, cls } = map[status];
  return (
    <button onClick={onClick} disabled={status === "testing"} title="Imprimer ticket de test"
      className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold transition-colors ${cls}`}>
      {icon}{label}
    </button>
  );
}

function getConnDetail(conn: PrinterConnection): string | null {
  if (conn.type === "network")   return `${conn.ip}:${conn.port}`;
  if (conn.type === "bluetooth") return conn.deviceName ?? null;
  if (conn.type === "usb")       return conn.deviceName ?? null;
  if (conn.type === "serial")    return `${conn.baudRate} baud`;
  return null;
}

function EmptyState({ onAdd }: { onAdd(): void }) {
  return (
    <div className="rounded-3xl border border-dashed border-border p-12 text-center">
      <Printer className="w-10 h-10 text-text-muted mx-auto mb-4" />
      <p className="text-sm font-semibold text-text-primary mb-1">Aucune imprimante configurée</p>
      <p className="text-xs text-text-muted mb-6">L&apos;impression bascule automatiquement sur le navigateur jusqu&apos;à ce qu&apos;une imprimante soit ajoutée.</p>
      <button onClick={onAdd}
        className="inline-flex items-center gap-2 px-5 py-2.5 rounded-xl bg-action-primary text-bg-primary text-xs font-black uppercase tracking-widest hover:opacity-90 transition-opacity">
        <Plus className="w-3.5 h-3.5" />
        Configurer ma première imprimante
      </button>
    </div>
  );
}

export { PrinterSettings };

"use client";

import { useState } from "react";
import { AnimatePresence } from "framer-motion";
import { useTables } from "@/modules/ops";
import {
    LayoutGrid,
    Users,
    Box,
    Cpu,
} from "lucide-react";
import { TablesToolbar, FloorArchitecture, ZoneService, MobilierConfig } from "@/modules/facility/spaces/settings";

export default function TablesSettings() {
    const tablesHook = useTables();
    const tables = tablesHook.tables;
    const zones = tablesHook.zones;
    const floors = tablesHook.floors;
    const {
        addTable,
        updateTable,
        deleteTable,
        addZone,
        updateZone,
        deleteZone,
        addFloor,
        updateFloor,
        deleteFloor
    } = tablesHook;

    const [isSaving, setIsSaving] = useState(false);
    const [activeTab, setActiveTab] = useState<'zones' | 'tables' | 'floors'>('zones');

    const [isEditingZone, setIsEditingZone] = useState(false);
    const [isEditingTable, setIsEditingTable] = useState(false);
    const [isEditingFloor, setIsEditingFloor] = useState(false);

    const handleSave = async () => {
        setIsSaving(true);
        // 🚀 INDUSTRIAL SOUDURE: Instantaneous Floor Plan Sync
        setIsSaving(false);
    };

    const tablesCount = tables.length;
    const totalSeats = tables.reduce((acc: number, t: { seats: number }) => acc + t.seats, 0);

    const isEditing = isEditingZone || isEditingTable || isEditingFloor;

    const handleAddButtonClick = () => {
        if (activeTab === 'zones') setIsEditingZone(true);
        else if (activeTab === 'tables') setIsEditingTable(true);
        else if (activeTab === 'floors') setIsEditingFloor(true);
    };

    return (
        <div className="space-y-12 pb-20">
            <TablesToolbar 
                activeTab={activeTab}
                setActiveTab={setActiveTab}
                isEditing={isEditing}
                onAdd={handleAddButtonClick}
                onSave={handleSave}
                isSaving={isSaving}
                floors={floors}
            />

            {/* Quick Context Stats */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {[
                    { label: 'CONFIGURATION', value: activeTab === 'zones' ? 'Zones' : activeTab === 'tables' ? 'Tables' : 'Étages', icon: LayoutGrid },
                    { label: 'ELEMENTS VISIBLES', value: activeTab === 'zones' ? zones.length : activeTab === 'tables' ? tablesCount : floors.length, icon: Box },
                    { label: 'CAPACITÉ TOTALE', value: totalSeats + ' PAX', icon: Users },
                    { label: 'TAUX OPTIMISATION', value: '94%', icon: Cpu },
                ].map((stat, idx) => (
                    <div key={idx} className="bg-bg-secondary border border-border p-4 rounded-2xl flex items-center justify-between group hover:border-accent/30 transition-all">
                        <div>
                            <p className="text-[9px] font-bold text-text-muted uppercase tracking-widest mb-1">{stat.label}</p>
                            <p className="text-lg font-serif text-text-primary italic">{stat.value}</p>
                        </div>
                        <div className="w-10 h-10 rounded-xl bg-bg-primary flex items-center justify-center text-text-muted group-hover:text-accent transition-colors">
                            <stat.icon className="w-5 h-5" />
                        </div>
                    </div>
                ))}
            </div>

            {/* Content Switcher */}
            <AnimatePresence mode="wait">
                {activeTab === 'floors' && (
                    <FloorArchitecture 
                        floors={floors}
                        addFloor={addFloor}
                        updateFloor={updateFloor}
                        deleteFloor={deleteFloor}
                        isEditingFloor={isEditingFloor}
                        setIsEditingFloor={setIsEditingFloor}
                    />
                )}

                {activeTab === 'zones' && (
                    <ZoneService 
                        zones={zones}
                        floors={floors}
                        tables={tables}
                        addZone={addZone}
                        updateZone={updateZone}
                        deleteZone={deleteZone}
                        isEditingZone={isEditingZone}
                        setIsEditingZone={setIsEditingZone}
                    />
                )}

                {activeTab === 'tables' && (
                    <MobilierConfig 
                        tables={tables}
                        zones={zones}
                        floors={floors}
                        addTable={addTable}
                        updateTable={updateTable}
                        deleteTable={deleteTable}
                        isEditingTable={isEditingTable}
                        setIsEditingTable={setIsEditingTable}
                    />
                )}
            </AnimatePresence>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Coins, Clock, Users, Award, FileSpreadsheet, ShieldCheck, Check } from "lucide-react";
import { motion } from "framer-motion";
import { cn } from "@/lib/ui.foundations";
import {
  TipsDistributionSettings,
  TipDistributionMethod,
  DEFAULT_TIPS_SETTINGS,
} from "@/modules/human/remuneration/services/TipsDistributionEngine";

interface Props {
  settings?: TipsDistributionSettings;
  onSave?: (updated: TipsDistributionSettings) => void;
  userRole?: string; // 'super_admin' | 'admin' | 'directeur' | 'manager'
}

const METHOD_OPTIONS: Array<{ value: TipDistributionMethod; label: string; description: string }> = [
  {
    value: "hours_by_role_weight",
    label: "Pro-Rata Heures + Pondération par Rôle (Recommandé HCR)",
    description: "Répartition selon le temps présent ajusté par le coefficient de chaque poste (salle, cuisine, bar).",
  },
  {
    value: "equal_per_shift_staff",
    label: "Part Égale par Salarié du Shift",
    description: "Division stricte à parts égales entre tous les membres ayant participé au service.",
  },
  {
    value: "hours_strict",
    label: "Pro-Rata Strict des Heures Travaillées",
    description: "Calcul uniquement basé sur les heures pointées sur la caisse, sans distinction de rôle.",
  },
  {
    value: "points_system",
    label: "Système de Points par Qualification",
    description: "Attribution selon une grille de points fixe par niveau d'ancienneté ou qualification.",
  },
];

export function TipsDistributionSettingsSection({ settings = DEFAULT_TIPS_SETTINGS, onSave, userRole = "manager" }: Props) {
  const [config, setConfig] = useState<TipsDistributionSettings>(settings);
  const [isSaved, setIsSaved] = useState(false);

  const canEdit = ["super_admin", "admin", "directeur", "manager"].includes(userRole);

  const handleUpdate = (updated: TipsDistributionSettings) => {
    setConfig(updated);
    if (onSave) {
      onSave(updated);
      setIsSaved(true);
      setTimeout(() => setIsSaved(false), 2500);
    }
  };

  const handleRoleWeightChange = (roleKey: string, weight: number) => {
    const updated = {
      ...config,
      roleWeights: {
        ...config.roleWeights,
        [roleKey]: weight,
      },
    };
    handleUpdate(updated);
  };

  return (
    <div className="space-y-8 p-8 bg-bg-secondary border border-border rounded-3xl backdrop-blur-xl shadow-lg">
      {/* En-tête de section */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 rounded-2xl bg-amber-500/10 border border-amber-500/20 flex items-center justify-center text-amber-500">
            <Coins className="w-6 h-6" />
          </div>
          <div>
            <h3 className="text-xl font-serif italic text-text-primary">Répartition Automatique des Pourboires CB</h3>
            <p className="text-xs text-text-muted">Réglages gérables par Admin & Manager — Distribution équitable à la clôture de service</p>
          </div>
        </div>

        {/* Toggle Principal ON / OFF */}
        <div className="flex items-center gap-3">
          <span className="text-xs font-semibold text-text-muted">
            {config.autoTipsDistributionEnabled ? "Automatique Activé" : "Désactivé"}
          </span>
          <button
            disabled={!canEdit}
            onClick={() => handleUpdate({ ...config, autoTipsDistributionEnabled: !config.autoTipsDistributionEnabled })}
            className={cn(
              "w-14 h-8 rounded-full relative transition-all duration-300",
              config.autoTipsDistributionEnabled ? "bg-amber-500 shadow-lg shadow-amber-500/20" : "bg-bg-tertiary border border-border"
            )}
          >
            <motion.div
              animate={{ x: config.autoTipsDistributionEnabled ? 26 : 2 }}
              transition={{ type: "spring", stiffness: 500, damping: 30 }}
              className="absolute top-1 left-1 w-6 h-6 bg-surface-card rounded-full shadow-md"
            />
          </button>
        </div>
      </div>

      {config.autoTipsDistributionEnabled && (
        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="space-y-8">
          {/* Choix de la méthode de répartition */}
          <div className="space-y-4">
            <label className="text-xs font-black uppercase tracking-widest text-text-muted flex items-center gap-2">
              <Award className="w-4 h-4 text-amber-500" /> Méthode de Répartition des Pourboires
            </label>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {METHOD_OPTIONS.map(opt => (
                <button
                  key={opt.value}
                  disabled={!canEdit}
                  onClick={() => handleUpdate({ ...config, tipsDistributionMethod: opt.value })}
                  className={cn(
                    "p-5 rounded-2xl border text-left transition-all duration-300 relative overflow-hidden",
                    config.tipsDistributionMethod === opt.value
                      ? "bg-amber-500/10 border-amber-500/40 text-text-primary shadow-md"
                      : "bg-bg-tertiary/40 border-border text-text-muted hover:border-amber-500/20"
                  )}
                >
                  <p className="font-semibold text-sm text-text-primary flex items-center justify-between">
                    {opt.label}
                    {config.tipsDistributionMethod === opt.value && <Check className="w-4 h-4 text-amber-500" />}
                  </p>
                  <p className="text-xs text-text-muted mt-2 leading-relaxed">{opt.description}</p>
                </button>
              ))}
            </div>
          </div>

          {/* Configuration des coefficients par Rôle (Si méthode Pro-rata ou Points) */}
          {config.tipsDistributionMethod === "hours_by_role_weight" && (
            <div className="space-y-4 bg-bg-tertiary/30 p-6 rounded-2xl border border-border">
              <label className="text-xs font-black uppercase tracking-widest text-text-muted flex items-center gap-2">
                <Users className="w-4 h-4 text-amber-500" /> Coefficients de Pondération par Rôle (Poids Métier)
              </label>
              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
                {Object.entries(config.roleWeights).map(([roleKey, weight]) => (
                  <div key={roleKey} className="space-y-2 p-3 bg-bg-secondary rounded-xl border border-border">
                    <span className="text-xs font-serif capitalize text-text-primary block">
                      {roleKey.replace("_", " ")}
                    </span>
                    <div className="flex items-center gap-2">
                      <input
                        type="number"
                        step="0.1"
                        min="0"
                        max="3"
                        disabled={!canEdit}
                        value={weight}
                        onChange={e => handleRoleWeightChange(roleKey, parseFloat(e.target.value) || 0)}
                        className="w-full px-3 py-2 bg-bg-primary border border-border rounded-lg text-sm text-text-primary font-mono outline-none focus:border-amber-500"
                      />
                      <span className="text-xs text-text-muted font-bold">x</span>
                    </div>
                  </div>
                ))}
