export function registerAntiCorruptionLayerHandler() {
  const unsubOrder = NexusEventBus.on(
    'integration.delivery_order_received',
    async (payload) => {
      const { tenantId, integrationId, platform, rawPayload } = payload;

      const config = await Nexus.adapter.get<IntegrationConfig>(`tenants/${tenantId}/integrations/${integrationId}`);

      if (config && config.autoAccept) {
        logger.info(`[ACL] Auto-Accept activé pour ${platform}. Traduction du payload brut vers les événements natifs de l'Empire.`);

        const canonicalOrderId = `order_${crypto.randomUUID()}`;
        const rp = rawPayload as JsonObject;
        const amount = (rp.total_price_cents as number) * 100 || 0; 

        await NexusEventBus.emitDurable('order.placed', {
          v: 1,
          tenantId,
          orderId: canonicalOrderId,
          tableId: null,
          operatorId: `integration_${platform}`,
          items: (rp.items as unknown as RawDeliveryItem[])?.map((i: RawDeliveryItem) => ({
            productId: i.external_data?.plu ?? i.id,
            name: i.title ?? i.name,
            quantity: i.quantity,
            unitPriceInMicrounits: (i.price_cents ?? 0) * 10_000,
            notes: i.special_instructions ?? '',
          })) as unknown as import('@/modules/ops').CartItem[] ?? []
        });

        await NexusEventBus.emitDurable('order.paid', {
          v: 1,
          tenantId,
          orderId: canonicalOrderId,
          tableId: null,
          operatorId: `integration_${platform}`,
          items: (rp.items as unknown as RawDeliveryItem[])?.map((i: RawDeliveryItem) => ({
            productId: i.external_data?.plu ?? i.id,
            name: i.title ?? i.name,
            quantity: i.quantity,
            unitPriceInMicrounits: (i.price_cents ?? 0) * 10_000,
            notes: i.special_instructions ?? '',
          })) as unknown as import('@/modules/ops').CartItem[] ?? [],
          totalInMicrounits: amount,
          paymentMode: platform
        });

        empireAudit.log({
          module: 'ops',
          action: 'ACL_AUTO_ACCEPT_TRANSLATED',
          details: { canonicalOrderId, platform },
          severity: 'low',
          timestamp: new Date(),
        });
      }
    },
    { id: 'anti-corruption-layer', priority: 'HIGH' }
  );

  const unsubResa = NexusEventBus.on(
    'integration.reservation_received',
    async (payload) => {
      const { tenantId, integrationId, platform, rawPayload } = payload as ReservationPayload;

      if (platform === 'lafourchette') {
        logger.info(`[ACL] Traduction de réservation LaFourchette vers l'Empire.`);

        await NexusEventBus.emitDurable('reservation.confirmed', {
          v: 1,
          tenantId,
          reservationId: `resa_${crypto.randomUUID()}`,
          customerName: rawPayload.customer_name || 'Inconnu',
          pax: rawPayload.pax || 2,
          date: rawPayload.date,
          time: rawPayload.time,
          channel: 'lafourchette',
        } as Parameters<typeof NexusEventBus.emitDurable>[1]);

        empireAudit.log({
          module: 'crm',
          action: 'ACL_LAFOURCHETTE_TRANSLATED',
          userId: 'system',
          instanceId: tenantId,
          details: { platform, rawPayload },
          severity: 'low',
          timestamp: new Date(),
        });
      }
    },
    { id: 'acl-reservation', priority: 'HIGH' }
  );

  return () => {
    unsubOrder();
    if (unsubResa) unsubResa();
  };
}

import { NexusEventBus } from '../NexusEventBus';
import { empireAudit } from '@/lib/audit';
import { Nexus } from '@/lib/nexus/NexusAdapter';
import { logger } from '@/lib/logger';
import { toError } from "@/lib/toError";

interface TicketZRecord {
  date: string;
  totalInMicrounits: number;
  ordersCount?: number;
}

export class CashflowForecastHandler {
  /**
   * Calcule la prévision de CA pour J+1 en utilisant une moyenne mobile 7 jours
   * pondérée par le jour de la semaine (day-of-week factor).
   */
  private static computeForecast(
    historicalData: TicketZRecord[],
    forecastDate: Date,
    fallbackAmount: number
  ): { predictedRevenueInMicrounits: number; method: string; dataPoints: number } {
    if (historicalData.length < 3) {
      // Pas assez de données : fallback +5%
      return {
        predictedRevenueInMicrounits: Math.round(fallbackAmount * 1.05),
        method: 'fallback_5pct',
        dataPoints: historicalData.length
      };
    }

    // Moyenne mobile 7 jours
    const movingAvg = historicalData.reduce((sum, d) => sum + d.totalInMicrounits, 0) / historicalData.length;

    // Day-of-week factor : pondérer davantage les jours identiques
    const targetDow = forecastDate.getDay(); // 0=dim, 1=lun, ...
    const sameDowEntries = historicalData.filter(d => new Date(d.date).getDay() === targetDow);

    if (sameDowEntries.length === 0) {
      // Pas de jour similaire dans l'historique, utiliser la moyenne simple
      return {
        predictedRevenueInMicrounits: Math.round(movingAvg),
        method: 'moving_avg_7d',
        dataPoints: historicalData.length
      };
    }

    // Moyenne des jours identiques (même jour de semaine)
    const dowAvg = sameDowEntries.reduce((sum, d) => sum + d.totalInMicrounits, 0) / sameDowEntries.length;

    // Pondération : 60% jour de semaine, 40% moyenne globale
    const weightedForecast = Math.round(dowAvg * 0.6 + movingAvg * 0.4);

    return {
      predictedRevenueInMicrounits: weightedForecast,
      method: 'weighted_dow_moving_avg',
      dataPoints: historicalData.length
    };
  }

  static register() {
    return NexusEventBus.on('finance.ticket_z_closed', async (payload) => {
      const { tenantId, date, totalInMicrounits, ordersCount } = payload;

      logger.info(`[CashflowForecast] Ticket Z fermé le ${date} pour ${totalInMicrounits}µ. Calcul prévision J+1...`);

      const forecastDate = new Date(new Date(date).getTime() + 86400000);
      const forecastDateStr = forecastDate.toISOString().split('T')[0];
      const forecastId = `forecast_${forecastDateStr}`;

      // Récupérer les 7 derniers jours de Ticket Z pour la moyenne mobile
      const sevenDaysAgo = new Date(new Date(date).getTime() - 7 * 86400000).toISOString().split('T')[0];

      let historicalData: TicketZRecord[] = [];
      try {
        historicalData = await Nexus.adapter.query<TicketZRecord>(
          `tenants/${tenantId}/finance/ticketZ`, {
            where: [
              { field: 'date', operator: '>=', value: sevenDaysAgo },
              { field: 'date', operator: '<=', value: date }
            ]
          }
        );
      } catch (err) {
        logger.warn(`[CashflowForecast] Impossible de récupérer l'historique Ticket Z, fallback +5%`, toError(err).message);
      }

      const forecast = CashflowForecastHandler.computeForecast(
        historicalData,
        forecastDate,
        totalInMicrounits
      );

      // Ecriture de la prévision dans le ledger
      await Nexus.adapter.update(`tenants/${tenantId}/finance/forecasts/${forecastId}`, {
        date: forecastDateStr,
        predictedRevenueInMicrounits: forecast.predictedRevenueInMicrounits,
        method: forecast.method,
        dataPoints: forecast.dataPoints,
        basedOnTicketZDate: date,
        basedOnRevenue: totalInMicrounits,
        updatedAt: Date.now()
      });

      empireAudit.log({
        module: 'finance',
        action: 'CASHFLOW_FORECAST_GENERATED',
        userId: 'system',
        instanceId: tenantId,
        details: {
          date: forecastDateStr,
          forecastedAmount: forecast.predictedRevenueInMicrounits,
          method: forecast.method,
          dataPoints: forecast.dataPoints
        },
        severity: 'low',
        timestamp: new Date(),
      });
    }, { id: 'cashflow-forecast', priority: 'BACKGROUND' });
  }
}

