};

/**
 * Met à jour l'agrégat Ticket Z en temps réel à chaque paiement.
 * Utilise runTransaction pour éviter les race conditions (double-comptage).
 * BACKGROUND : non-bloquant, le serveur n'attend pas.
 */
export function registerTicketZHandler(): () => void {
  return NexusEventBus.on(
    'order.paid',
    async (payload) => {
      const { tenantId, totalInMicrounits, items, tableId } = payload;

      // P11-D, P11-E, P11-I : Libérer la table et la marquer à nettoyer (avec optimistic locking via tx)
      if (tableId) {
        const tablePath = `tenants/${tenantId}/tables/${tableId}`;
        await Nexus.adapter.runTransaction(async (tx) => {
          const table = await tx.get<{ status: string; cleaningRequired: boolean; version?: number }>(tablePath);
          if (table && table.status !== 'available') {
            tx.set(tablePath, {
              ...table,
              status: 'available',
              freedAt: new Date().toISOString(),
              cleaningRequired: true,
            });
          }
        }).catch(err => logger.error(`[TicketZHandler] Erreur libération table ${tableId}`, err));
      }

      const today = new Date().toISOString().split('T')[0];
      const path = `tenants/${tenantId}/ticketZ/${today}`;

      await Nexus.adapter.runTransaction(async (tx) => {
        const existing = (await tx.get<TicketZDoc>(path)) ?? {
          id: today,
          date: today,
          tenantId,
          ordersCount: 0,
          totalInMicrounits: 0,
          taxBreakdown: {},
          updatedAt: new Date().toISOString(),
        };

        // Ne pas accumuler si déjà clôturé (protection post-clôture Z)
        if (existing.closed) return;

        const taxBreakdown = { ...existing.taxBreakdown };
        for (const item of items) {
          const rate = item.taxRate ?? '0.10';
          const lineTotal = item.unitPriceInMicrounits * item.quantity - (item.discountInMicrounits ?? 0);
          const tva = TaxCalculator.applyRate(lineTotal, rate);
          taxBreakdown[rate] = (taxBreakdown[rate] ?? 0) + tva;
        }

        const updated: TicketZDoc = {
          ...existing,
          ordersCount: existing.ordersCount + 1,
          totalInMicrounits: existing.totalInMicrounits + totalInMicrounits,
          taxBreakdown,
          updatedAt: new Date().toISOString(),
        };

        tx.set(path, toSovereignData(updated));

        logger.info(
          `[TicketZ] Jour ${today} — total ${(updated.totalInMicrounits / 1_000_000).toFixed(2)}€ (${updated.ordersCount} tickets)`
        );
      });
    },
    { id: 'ticketz-update', priority: 'BACKGROUND' }
  );
}

/**
 * Clôture définitive du Ticket Z d'une journée :
 *  1. Scelle le document ticketZ/{date} comme immuable (closed: true)
 *  2. Écrit une JournalEntry agrégée dans journalEntries/Z_{date}
 *
 * Idempotent — sans effet si déjà clôturé.
 */
export async function closeTicketZForDay(tenantId: string, date: string): Promise<void> {
  const ticketPath = `tenants/${tenantId}/ticketZ/${date}`;
  const entryId = `Z_${date.replace(/-/g, '')}`;
  const entryPath = `tenants/${tenantId}/journalEntries/${entryId}`;

  // Idempotence : si le JournalEntry scellé existe déjà, rien à faire.
  // Cela couvre aussi le cas d'un échec partiel (ticketZ clôturé mais JE non scellé).
  const existingEntry = await Nexus.adapter.get(entryPath);
  if (existingEntry) {
    logger.info(`[TicketZ] JournalEntry ${entryId} déjà scellé — no-op`);
    return;
  }

  const ticketZ = await Nexus.adapter.get<TicketZDoc>(ticketPath);

  if (!ticketZ) {
    logger.warn(`[TicketZ] Aucun Ticket Z trouvé pour ${date} — clôture annulée`);
    return;
  }

  const closedAt = new Date().toISOString();
  const totalTVAInMicrounits = Object.values(ticketZ.taxBreakdown ?? {}).reduce((a, b) => a + b, 0);

  // Numéro séquentiel NF525
  const receiptNumber = await FiscalSealer.generateSequentialReceiptNumber(tenantId);

  const journalEntryBase = {
    id: entryId,
    date,
    pieceNumber: receiptNumber,
    description: `Clôture Z — ${date} — ${ticketZ.ordersCount} tickets`,
    lines: [],
    referenceType: 'order' as const,
    isSystemGenerated: true,
    isValidated: true,
    type: 'revenue' as const,
    totalInMicrounits: ticketZ.totalInMicrounits,
    totalTVAInMicrounits,
    taxBreakdown: ticketZ.taxBreakdown,
    ordersCount: ticketZ.ordersCount,
    status: 'validated' as const,
    updatedAt: closedAt,
  };

  const dataSnapshot = CryptoService.canonicalStringify({
    id: entryId,
    receiptNumber,
    totalInMicrounits: ticketZ.totalInMicrounits,
    totalTVAInMicrounits,
    taxBreakdown: ticketZ.taxBreakdown,
    ordersCount: ticketZ.ordersCount,
    date,
  });

  // Scellement NF525 : écrit JournalEntry + FiscalSeal + clôture TicketZ atomiquement.
  // Le Ticket Z est marqué closed: true dans la MÊME transaction que le sceau — si
  // le scellement échoue, le ticket reste ouvert (aucune désynchronisation possible).
  const sealResult = await FiscalSealer.sealDataAtomically(
    dataSnapshot,
    tenantId,
    false,
    journalEntryBase,
    (tx, sealId) => tx.update(ticketPath, {
      closed: true,
      closedAt,
      fiscalSealId: sealId,
      updatedAt: closedAt,
    } as Partial<unknown>),
  );

  empireAudit.log({
    module: 'accounting',
    action: 'TICKET_Z_CLOSED',
    details: { date, entryId, tenantId, sealId: sealResult.sealId, hash: sealResult.hash.substring(0, 8) },
    severity: 'low',
    timestamp: new Date(),
  });

  logger.info(`[TicketZ] Clôture Z ${date} — JournalEntry ${entryId} scellé NF525 (hash: ${sealResult.hash.substring(0, 8)})`);

  // P08-H: Déclencher la prévision CA J+1 via l'Oracle
  NexusEventBus.emitDurable('finance.ticket_z_closed', {
    v: 1,
    tenantId,
    date,
    totalInMicrounits: ticketZ.totalInMicrounits,
    ordersCount: ticketZ.ordersCount
  }).catch(() => {});
}


"use client";

import { useMemo, useCallback } from "react";
import { useAuth } from "@/shared/providers/NexusCoreContext";
import {
    PERMISSION_ROLE_LEVELS,
    type PermissionRole,
    type PermissionCheckResult,
} from "@nexus/contracts/permissions.types";
import { policyEngine } from '@/modules/compliance';
import { logger } from '@/lib/logger';

// ACTION_MAP (350L de config) extraite dans actionPermissionMap.ts
import { ACTION_MAP } from './actionPermissionMap';
export type { ActionConfig } from './actionPermissionMap';

export function useActionPermission(page: string, action: string): PermissionCheckResult {
    const { currentUser } = useAuth();

    return useMemo<PermissionCheckResult>(() => {
        // L'authentification prime sur tout le reste. Auparavant ce contrôle venait
        // APRÈS le cas « action non déclarée » : un utilisateur non authentifié était
        // donc autorisé sur toute action absente de l'ACTION_MAP.
        if (!currentUser) return { allowed: false, requiresPin: false, reason: 'Non authentifié' };

        const config = ACTION_MAP[page]?.[action];

        if (!config) {
            // Échec OUVERT — conservé temporairement pour ne pas bloquer un écran
            // s'appuyant sur une action non déclarée.
            //
            // ⚠️ PHASE 2 (chantier 16) : basculer sur un refus une fois les actions
            // manquantes relevées en production et ajoutées à ACTION_MAP.
            // `usePageAccess` et `useTabAccess` échouent déjà FERMÉ — cette
            // incohérence doit disparaître.
            logger.warn(
                `[RBAC] Action non déclarée dans ACTION_MAP : "${page}.${action}" — ` +
                `autorisée par défaut (sans PIN). À déclarer dans actionPermissionMap.ts.`
            );
            return { allowed: true, requiresPin: false };
        }

        const role = currentUser.role as PermissionRole;
        const userLevel = PERMISSION_ROLE_LEVELS[role] ?? 0;

        if (userLevel >= config.minLevel) {
            return { allowed: true, requiresPin: config.requiresPin ?? false, limit: config.limit };
        }

        return {
            allowed: false,
            requiresPin: false,
            reason: `Niveau insuffisant — rôle ${role} (${userLevel}) < ${config.minLevel} requis`,
        };
    }, [currentUser, page, action]);
}

export function useThresholdCheck(page: string, action: string) {
    const { currentUser } = useAuth();

    const checkThreshold = useCallback(
        (field: 'amount' | 'discountPct' | 'quantity', value: number) => {
            if (!currentUser) return { allowed: false, reason: 'Non authentifié', requiresElevation: false };
            const role = currentUser.role as PermissionRole;
            const fullAction = `${page}.${action}`;
            return policyEngine.checkThreshold(role, fullAction, field, value);
        },
        [currentUser, page, action]
    );

    return { checkThreshold };
}

"use client";

import { useMemo } from 'react';
import { useAuth, useTenant } from '@/shared/providers/NexusCoreProvider';
import { ConnectorHub } from '@/modules/intelligence/connectors/hub';
import type { ConnectorPerm, ConnectorState, ConnectorUserContext } from '@/shared/connector-manifest/types';
import type { PermissionRole } from '@/shared/nexus/contracts/permissions.types';

export interface UseConnectorResult {
  /** Le connecteur est disponible pour ce vertical + les capabilities du tenant */
  isAvailable: boolean;
  /** État Nexus du connecteur (null = non encore chargé ou auto-activation pending) */
  state: ConnectorState | null;
  /** Connecteur actif (status='active') */
  isActive: boolean;
  canConfigure: boolean;
  canManage: boolean;
  canUse: boolean;
  can: (perm: ConnectorPerm) => boolean;
}

/**
 * Hook client pour vérifier l'accès à un connecteur.
 *
 * @param connectorId  ID du connecteur (ex: 'uber-eats', 'bofip')
 * @param state        État Nexus du connecteur, à fournir depuis le composant parent
 *                     qui charge tenants/{tenantId}/connectors/{id} via Nexus.
 */
export function useConnector(
  connectorId: string,
  state: ConnectorState | null = null,
): UseConnectorResult {
  const { currentUser } = useAuth();
  const { activeTenantConfig } = useTenant();

  return useMemo(() => {
    const NOT_AVAILABLE: UseConnectorResult = {
      isAvailable: false,
      state: null,
      isActive: false,
      canConfigure: false,
      canManage: false,
      canUse: false,
      can: () => false,
    };

    // isAvailable : le serveur (/api/connectors) filtre déjà par tenant + variant + capabilities.
    // On fait confiance à cette liste — pas de double-filtre côté client qui bloquerait
    // des connecteurs dont la requiredCapability n'est pas dans la config locale.
    const isAvailable = true;

    // Mapper les alias génériques vers les rôles RBAC canoniques
    const rawRole = currentUser?.role ?? 'super_admin';
    const roleAlias: Record<string, PermissionRole> = {
      admin:      'super_admin',
      superadmin: 'super_admin',
      root:       'super_admin',
    };
    const userCtx: ConnectorUserContext = {
      role: (roleAlias[rawRole] ?? rawRole) as PermissionRole,
    };

    const can = (perm: ConnectorPerm) =>
      ConnectorHub.canUserAccess(connectorId, userCtx, perm);

    return {
      isAvailable,
      state,
      isActive: state?.status === 'active',
      canConfigure: can('configure'),
      canManage: can('manage'),
      canUse: can('use'),
      can,
    };
  }, [connectorId, currentUser, activeTenantConfig, state]);
}

import { useAtomValue } from "jotai";
import { rbacConfigAtom } from "@/store/pillars/rbac";
import { DEFAULT_PAGE_ACCESS } from "@/modules/human";
import { useAuth } from "@/shared/providers/NexusCoreContext";
import { PageKey, PermissionRole } from "@/shared/nexus/contracts/permissions.types";

export function usePageAccess(pageKey: PageKey | string): boolean {
  const { currentUser } = useAuth();
  const config = useAtomValue(rbacConfigAtom);

  if (!currentUser) return false;
  if (currentUser.role === 'admin' || currentUser.role === 'super_admin') return true;

  const role = currentUser.role as PermissionRole;

  // Defaults
  const defaultAllowed = DEFAULT_PAGE_ACCESS[pageKey] || [];
  const isAllowed = defaultAllowed.includes(role);

  // Overrides
  if (config && config.pageOverrides && config.pageOverrides[pageKey]) {
    const overrides = config.pageOverrides[pageKey];

    if (overrides.blocked && overrides.blocked.includes(role)) {
      return false; // Blocked explicitly
    }

    if (overrides.allowed && overrides.allowed.includes(role)) {
      return true; // Allowed explicitly
    }
  }

  return isAllowed;
}

import { useCallback, useMemo, useEffect, useRef } from 'react';
import { useNexusFleet as useFleet } from '@/shared/hooks/useNexusFleet';
import { useGeminiAgent } from './useGeminiAgent';
// eslint-disable-next-line vanguard/no-inter-module-imports
import { MacroBrain, FleetInsight } from '@modules/intelligence/services/MacroBrain';
import { logger } from '@/lib/axiom';
import { toast } from 'sonner';
import { authedFetch } from '@/lib/client/authedFetch';
import { toError } from "@/lib/toError";

/**
 * useStrategicOracle (Empire Grade)
 * The bridge between the MCC UI and the MacroBrain intelligence layer.
 * Manages fleet-wide strategy and autonomous action execution.
 */
export function useStrategicOracle() {
    const fleet = useFleet() as import('@/shared/nexus/contracts/nexus.types').NexusFleetState;
    const { instances, refreshFleet: _refreshFleet } = fleet;
    const agent = useGeminiAgent();
    const notifiedInsightIds = useRef<Set<string>>(new Set());

    // 1. Analyze Fleet - Get strategic insights from MacroBrain
    const insights = useMemo(() => {
        return MacroBrain.analyzeFleet(instances);
    }, [instances]);

    // 2. Notify fleet_admin via WebPush when new CRITICAL insights appear
    useEffect(() => {
        const fresh = insights.filter(
            i => i.impact === 'CRITICAL' && !notifiedInsightIds.current.has(i.id),
        );
        if (fresh.length === 0) return;

        fresh.forEach(i => notifiedInsightIds.current.add(i.id));

        authedFetch('/api/admin/mcc/notify-critical', {
            method:  'POST',
            headers: { 'Content-Type': 'application/json' },
            body:    JSON.stringify({ insights: fresh.map(i => ({ id: i.id, title: i.title, impact: i.impact })) }),
        }).catch(err => logger.error('notify-critical failed', { err: toError(err).message }));
    }, [insights]);

    // 2. Executive Briefing - AI-driven fleet analysis
    const getExecutiveBriefing = useCallback(async () => {
        logger.info('Oracle: Generating Empire-wide Briefing');
        const context = {
            fleetSize: instances.length,
            metrics: MacroBrain.getConsolidatedMetrics(instances),
            topInsights: insights.slice(0, 3),
            timestamp: new Date().toISOString()
        };

        await agent.sendMessage(
            "Analyse l'état global de l'empire à partir des insights fournis. Donne-moi 3 priorités stratégiques immédiates.",
            context as unknown as import("@/shared/nexus-contract").SovereignMap
        );
    }, [agent, instances, insights]);

    // 3. Execute Strategic Action
    const executeAction = useCallback(async (insight: FleetInsight) => {
        logger.info('Oracle: Executing action', { id: insight.id });

        const toastId = toast.loading(`Exécution : ${insight.title}…`);

        try {
            const result = await MacroBrain.executeStrategicAction(insight);

            const affected = result.affectedInstanceIds.length;
            const label =
                insight.id === 'insight_dna_drift'      ? `${affected} instance(s) redémarrée(s)` :
                insight.id === 'insight_auto_rebalance'  ? `Ticket de transfert de stock créé` :
                insight.id === 'insight_bulk_seal'       ? `${affected} sceau(x) NF525 appliqué(s)` :
                `${affected} instance(s) traitée(s)`;

            toast.success(label, {
                id:          toastId,
                description: `Audit log : ${result.auditLogId}`,
                duration:    6000,
            });

            logger.info('Oracle: Action success', {
                auditLogId: result.auditLogId,
                affected:   result.affectedInstanceIds,
            });

            return result;
        } catch (err) {
            toast.error(`Échec : ${insight.title}`, {
                id:          toastId,
                description: err instanceof Error ? err.message : 'Erreur inconnue',
            });
            logger.error('Oracle: Action failed', { insightId: insight.id, err: toError(err).message });
            throw err;
        }
    }, []);

    return {
        // State
        insights,
        messages: agent.messages,
        isProcessing: agent.isProcessing,
        error: agent.error,

        // Actions
        getExecutiveBriefing,
        executeAction,
        askStrategicQuestion: (q: string) => agent.sendMessage(q, { fleetData: instances }),

        // Utils
        clearHistory: agent.startNewSession
    };
}

import { useAtomValue } from "jotai";
import { rbacConfigAtom } from "@/store/pillars/rbac";
import { DEFAULT_TAB_ACCESS } from "@/modules/human";
import { useAuth } from "@/shared/providers/NexusCoreContext";
import { PageKey, PermissionRole, PERMISSION_ROLE_LEVELS } from "@/shared/nexus/contracts/permissions.types";

export function useTabAccess(pageKey: PageKey | string, tabKey: string): boolean {
  const { currentUser } = useAuth();
  const config = useAtomValue(rbacConfigAtom);

  if (!currentUser) return false;
  if (currentUser.role === 'admin' || currentUser.role === 'super_admin') return true;

  const role = currentUser.role as PermissionRole;
  const userLevel = currentUser.accessLevel ?? PERMISSION_ROLE_LEVELS[role] ?? 0;

  // Defaults
  const pageDefaults = DEFAULT_TAB_ACCESS[pageKey] || {};
  let minLevel = pageDefaults[tabKey] ?? 0;

  // Overrides
  if (config && config.tabOverrides && config.tabOverrides[pageKey] && config.tabOverrides[pageKey][tabKey]) {
    const overrides = config.tabOverrides[pageKey][tabKey];

    if (overrides.blocked && overrides.blocked.includes(role)) {
      return false; // Blocked explicitly
    }

    if (overrides.minLevel !== undefined) {
      minLevel = overrides.minLevel;
    }
  }

  return userLevel >= minLevel;
}

